window.DEST=window.DEST||{};window.DEST.a2={"id":"a2","name":"Destination A2","level":"Elementary","credit":"Uzbek translations and example sentences by Zoir Akramov (@Zoir_Akramov). Word list from “Destination A2” by Malcolm Mann and Steve Taylore-Knowles.","secs":["Nouns","Verbs","Phrasal verbs","Phrases","Adjectives & adverbs","Word formation"],"units":[{"n":3,"t":"Family And Friends","c":[["Aunt","xola/amma",0,"We only have one aunt–my mum's sister.","Bizning bor yo'g'i birgina xolamiz bor–oyimning singlisi."],["Best friend","eng yaxshi do'st",0,"I met my best friend when we were five.","Men eng yaxshi do'stimni 5 yoshligimizda uchratganman."],["Cousin","amakivachcha, tog'avachcha, ammavachcha, xolavachcha",0,"My aunt's children are my cousins.","Xolamning farzandlari mening xolavachchalarimdir."],["Curly hair","jingalak soch",0,"Her sister has curly hair, but hers is straight.","Uning singlisining sochi jingalak, lekin o'ziniki silliq."],["Dyed hair","bo'yalgan soch",0,"Look at that boy's dyed hair–it's red and green!","Anavi bolaning bo'yalgan sochiga qarang–qizil va yashil rangda ekan!"],["Straight hair","silliq soch, tekis soch",0,"Anne has straight hair, not curly hair!","Anning sochi silliq, zinhor jingalak emas!"],["Light hair","och rangli soch",0,"Your dad and mum have dark hair, but you have light hair.","Otangiz va onangizning sochlari to'q rangda, biroq sizniki och rangda ekan."],["Dark hair","to'q rangli soch",0,"My brother has dark hair, but mine is fair.","Akamning sochi to'q rangli, lekin meniki och rangli."],["Daughter","qiz farzand",0,"They have two sons and one daughter.","Ularning ikki o'g'il va bir qiz farzandi bor."],["Grandchild","nabira",0,"Our son got married, and we'll have a grandchild soon.","O'g'limiz turmush qurdi, va tez orada biz nabiralik bo'lamiz."],["Granddaughter","qiz nabira",0,"The old man looked after his granddaughter every summer.","Qariya har yozda nabira qiziga qarab turardi."],["Grandfather","bobo",0,"Is the grandfather staying with you, your father's father?","Bobo sizlar bilan turibdilarmi, dadangizni otasi demoqchiman?"],["Grandmother","buvi",0,"Their grandmother taught them to swim.","Ularning buvisi ularga suzishni o'rgatgan."],["Grandparent","yoki bobo yoki buvi, ulardan biri tushuniladi",0,"My grandparents are coming to stay at Christmas.","Bobom bilan buvim Rojdestvoda biznikida qolish uchun kelishyapti."],["Grandson","o'g'il nabira",0,"Their son is having a boy–their first grandson!","Ularning o'g'li o'g'il farzandlik bo'lyapti–bu ularning birinchi o'g'il nabirasi!"],["Husband","er",0,"Where did you and your husband get married?","Siz va eringiz qayerda turmush qurgansizlar?"],["Neighbour","qo'shni",0,"Peter kicked his ball into the neighbour's garden.","Piter koptogini qo'shnisining bog'iga tepib yubordi."],["Parent","ota yoki ona, ulardan biri tushuniladi",0,"Children usually ask their parents for advice.","Bolalar odatda ota-onalaridan maslahat so'rashadi."],["Pen friend","faqatgina xat orqali yozishadigan do'stingiz, odatda real hayotda ko'rishmagansiz chunki u olisda yashaydi",0,"I write to my pen friend every week.","Men xatdoshimga har hafta xat yozib turaman."],["People","odamlar",0,"There are many people in the park today.","Bugun parkda odamlar ko'p."],["Secret","sir",0,"I can tell my best friend all my secrets.","Men eng yaxshi do'stimga barcha sirlarimni ayta olaman."],["Son","o'g'il farzand",0,"John's son is six and his daughter is eight.","Jo'nning o'g'li 6 yoshda, qizi esa 8 da."],["Surname","familiya",0,"I know your first name's Tony, but what's your surname?","Sizning ismingiz To'ni ekanligini bilaman, lekin familiyangiz nima?"],["Uncle","tog'a/amaki",0,"We only have one uncle–my mum's brother.","Bizning bor yo'g'i birgina tog'amiz bor–oyimning ukasi."],["Wife","xotin, jufti yor, rafiqa",0,"Michael's wife Judy works and he looks after their kids.","Mayklning xotini Jyudi ishlaydi va Maykl bolalariga qaraydi."],["Admire","qoyil qolmoq",1,"I admire my mum because she is good at her job.","Men oyimga qoyil qolaman chunki u o'z ishining ustasi."],["Annoy","asabiga tegmoq, jahlini chiqarmoq",1,"It annoys me when my brother takes my toys.","Akam mening o'yinchoqlarimni olishlari asabimga tegadi."],["Argue","bahslashmoq, tortishmoq",1,"I'm upset because I argued with my friend.","Men xafaman chunki do'stim bilan tortishib qoldim."],["Believe","ishonmoq",1,"He says his dad's a footballer, but I don't believe him.","Uning aytishicha uning dadasi futbolchi ekan, lekin men unga ishonmayman."],["Chat","suhbatlashmoq",1,"He chats with his friends about football.","U do'stlari bilan futbol to'g'risida suhbatlashadi."],["Fight","urushmoq",1,"Don't fight with your brother. Try to be friendly.","Ukangiz bilan urushmang. Do'stona munosabatda bo'lishga harakat qiling."],["Miss","sog'inmoq",1,"I miss my friends during the summer holidays.","Yozgi ta'til davomida men do'stlarimni sog'inaman."],["Prefer","afzal ko'rmoq",1,"I prefer pizza to hamburgers.","Men gamburgerdan ko'ra pitsani afzal ko'raman."],["Realise","tushunib yetmoq, anglab yetmoq",1,"Do you realise how important this exam is?","Bu imtihon qanchalar muhim ekanligini tushunyapsizmi?"],["Share","baham ko'rmoq, bo'lishmoq, ulashmoq",1,"Share your chips with your brother!","Chipslaringizni ukangiz bilan birga baham ko'ring!"],["Wave","qo'l silkitmoq",1,"As we were leaving, we waved goodbye.","Jo'nab ketar ekanmiz, qo'l silkitib xayrlashdik."],["Wonder","qiziqmoq, bilishni xohlamoq",1,"I wonder why Aunt Judy didn't visit this year.","Jyudi xola bu yil nega kelmadi ekan-a?"],["Bring up","tarbiyalamoq, voyaga yetkazmoq",2,"My parents worked, so my grandma brought me up.","Ota-onam ishlashardi, shuning uchun meni buvim tarbiyalaganlar."],["Get on (well/badly) (with someone)","(biron kim bilan) yaxshi munsobatda bo'lmoq/chiqisha olmaslik",2,"I get on well with my sister–we have a great relationship.","Men singlim bilan yaxshi chiqishaman–o'rtamizdagi munosabat ajoyib."],["Go on","sodir bo'lmoq",2,"There's a lot of noise next door–I wonder what's going on?","Yon qo'shnimiznikida rosa shovqin bo'lyapti–nima bo'layotgan ekan-a?"],["Grow up","o'smoq, voyaga yetmoq",2,"I grew up in a small town and left the minute I turned 18.","Men kichik bir shaharchada o'sib voyaga yetganman va 18 yoshga to'lgan zahotim u yerni tark etganman."],["Look after","vaqtinchalik qarab turmoq",2,"Can you look after the baby while I go to the shops?","Men do'konga chiqib ketganimda chaqaloqqa qarab tura olasizmi?"],["Agree with (someone/something)","(biror kimning fikriga/biror narsaga) qo'shilmoq",3,"I agree with Owen that we should go to the cinema.","Men Ovenning fikriga qo'shilaman, kinoga borish kerak."],["At present","hozirgi paytda",3,"At present, my sister is at university, but it's her final year.","Hozirgi paytda singlim universitetda, ammo bu yil uning oxirgi yili."],["Belong to (someone)","(biror kim) ga tegishli bo'lmoq",3,"Does this phone belong to you or is it Jane's?","Bu telefon sizga tegishlimi yoki u Jeynnikimi?"],["Group of friends","do'stlar",3,"Is it better to have a big or small group of friends?","Ko'p do'stlarga ega bo'lish yaxshiroqmi yoki kam do'stlargami?"],["Have a chat/discussion","suhbatlashmoq/muhokama qilmoq",3,"I had a discussion with my parents about my future.","Men ota-onam bilan kelajagimni muhokama qilib oldim."],["Have a great/good time","vaqtni ajoyib o'tkazmoq, mazza qilmoq",3,"We had a great time at the party–it was so much fun!","Biz ziyofatda ajoyib vaqt o'tkazdik–juda qiziqarli bo'ldi!"],["In love with (someone)","(biror kim) bilan ishqiy munosabatda",3,"He is still in love with his wife after all these years!","Shuncha yildan so'ng u hali ham xotinini sevadi!"],["Look like (someone/something)","ko'rinishi jihatdan (biror kim/narsa) ga o'xshamoq",3,"Peter looks like his dad–they both have dark hair and brown eyes.","Piter dadasiga o'xshaydi– ularning ikkovi tim qora soch va jigarrang ko'zlarga ega."],["Talk about (someone/something)","(biror kim/narsa) haqida gapirmoq",3,"Are you talking about the film last night? Wasn't it great!","O'tgan tundagi film haqida gapiryapsizmi? Zo'r ekan-a!"],["Talk to (someone)","(biror kim) bilan gaplashmoq",3,"I want to talk to you about your bad behaviour yesterday.","Men kechagi yomon xulqingiz to'g'risida siz bilan gaplashib olishni istayman."],["Think about (someone/something)","(biror kim/narsa) haqida o'ylamoq",3,"You're smiling–are you thinking about your holiday?","Siz jilmayyapsiz–ta'tilingiz haqida o'ylayapsizmi?"],["Alike","o'xshash",4,"She and her dad are very alike. They have the same interests.","U va uning dadasi juda o'xshash. Ular bir xil qiziqishlarga ega."],["Clever","aqlli, zukko",4,"Jim's very clever and always gets good marks.","Jim juda aqlli va har doim yaxshi baholar oladi."],["Good-looking","chiroyli, kelishgan",4,"That film star is really good-looking.","Anavi kino yulduzi juda ham chiroyli."],["Lazy","dangasa, yalqov",4,"His dog is so lazy–it sleeps all the time.","Uning iti juda yalqov–u har doim uxlaydi."],["Married","turmush qurgan: uylangan yoki turmushga chiqqan",4,"Is your brother married to that woman?","Sizning akangiz o'sha ayolga uylanganmi?"],["Only","yagona, yolg'iz",4,"John is an only child and wants a brother or sister.","Jo'n yolg'iz farzand va u uka yoki singil xohlaydi."],["Overweight","ortiqcha vaznli, semiz",4,"My uncle is overweight and needs to do more exercise.","Mening tog'am semizlar va ular ko'proq mashq qilishlari kerak."],["Pale","rangida rang yo'q, rangi oqarib ketgan",4,"Don't stay long in the sun if you have pale skin.","Agar teringizning rangi oqargan bo'lsa, quyoshda uzoq turmang."],["Similar","o'xshash",4,"My sister and I look similar, but have different characters.","Singlim va men o'xshash ko'rinamiz, lekin turli xarakterlarga egamiz."],["Skinny","ozg'in, oriq",4,"I'm very skinny because I was ill.","Men juda oriqman chunki xasta edim."],["Slim","ozg'in va xushbichim (modellarga o'xshab)",4,"The model was tall and slim.","Model baland bo'yli va xushbichim edi."],["Special","maxsus, boshqacha, alohida",4,"Your birthday is a special day.","Tug'ilgan kuningiz boshqacha kun."],["Tanned","quyoshda toblangan, qoraygan",4,"By the end of the beach holiday, we were all tanned.","Plyajdagi ta'tilning oxiriga kelib, hammamiz qoraygan edik."],["Thin","ozg'in",4,"He's good at basketball because he's tall and thin.","U basketbol o'ynashda usta chunki u baland bo'yli va ozg'in."],["Occasionally","gohi-gohida",4,"We occasionally go to London to see my aunt.","Biz gohi-gohida xolamni ko'rish uchun Londonga borib turamiz."],["Rarely","kamdan-kam",4,"It rarely snows in the Sahara.","Sahara cho'lida qor kamdan-kam yog'adi."],["Regularly","doimiy ravishda",4,"We go to the cinema regularly–about twice a month.","Biz doimiy ravishda kinoga borib turamiz–oyiga taxminan ikki marta."],["Agree","fikriga qo'shilmoq",5,"I totally agree with you!","Men sizning fikringizga butunlay qo'shilaman!"],["Disagree","fikriga qo'shilmaslik",5,"My brother says it's the best film ever but I disagree.","Akamning aytishicha, u kinolar ichida eng zo'ri ekan, ammo men uning fikriga qo'shilmayman."],["Agreement","kelishuv",5,"Paul has an agreement with his mum to do the dishes every day.","Po'l har kuni idish-tovoqlarni yuvishiga doir kelishuvga ega onasi bilan."],["Describe","tasvirlamoq",5,"Can you describe him to me?","Menga uni tasvirlab bera olasizmi?"],["Description","ta'rif, tasvir",5,"Can you give me a description of your sister so I know which girl she is?","Singlingiz qaysi qiz ekanligini bilishim uchun menga uning tasvirini bera olasizmi (= tasvirlab bera olasizmi)?"],["Discuss","muhokama qilmoq",5,"We need to discuss the situation at home.","Biz holatni uyda muhokama qilishimiz zarur."],["Discussion","muhokama",5,"Let's have a discussion about where to go on holiday.","Keling ta'tilda qayerga borishni muhokama qilib olamiz."],["Friend","do'st",5,"Jane's a friend of the family.","Jeyn oilamiz do'sti."],["Friendship","do'stlik",5,"My friendship with John began when we were in school together.","Jo'n bilan do'stligim maktabda birga bo'lgan paytimizda boshlangan."],["Friendly","do'stona, muloyim",5,"Don't be scared of the dog–it's very friendly.","Itdan qo'rqmang–u juda muloyim."],["Unfriendly","do'stona emas, qo'rs, qo'pol",5,"That boy is very unfriendly–I said hello and he walked away.","Anavi bola juda qo'rs ekan–men unga salom degandim, u esa indamay ketib yubordi."],["Happy","xursand",5,"You don't look very happy today.","Siz bugun juda xursand ko'rinmaysiz."],["Unhappy","xafa",5,"Your teacher is unhappy with your low mark in the test.","O'qituvchingiz testdagi past bahoyingizdan xafa."],["Happiness","quvonch, xursandchilik, baxt",5,"The girl smiled with happiness when she saw her present.","Qiz sovg'asini ko'rganda quvonchdan tabassum qildi."],["Happily","xursandchilik bilan",5,"The children laughed happily as they played in the garden.","Bolalar bog'da o'ynashar ekan, xursandchilik bilan kulishdi."],["Help","yordam",5,"I really appreciate your help.","Yordamingizni rosa qadrlayman."],["Help","yordam bermoq",5,"Come and help me lift this box.","Kelib, menga mana bu qutini ko'tarishga yordamlashib yuboring."],["Helpful","foydasi tegadigan",5,"My aunt was very helpful when I had a problem with maths.","Matematikadan qiynalgan paytlarimda, xolamni juda foydasi tekkan."],["Unhelpful","foydasi tegmaydigan",5,"The map you drew me was completely unhelpful and I got lost.","Menga chizib bergan xaritangizning umuman foydasi tegmadi va men adashib qoldim."],["Helpfully","yordam berib, yaxshiyamki",5,"Helpfully, John left instructions about how to turn on the computer.","Jo'n yordam berib, kompyuterni qanday yoqish haqida ko'rsatmalar qoldiribdi."],["Like","yoqtirmoq",5,"I personally liked this song a lot.","Shaxsan menga bu qo'shiq rosa yoqdi."],["Dislike","yomon ko'rmoq, yoqtirmaslik",5,"I dislike people telling me what to do–it's so annoying!","Odamlar menga nima qilishim kerakligini aytishini yoqtirmayman–bu juda asabga tegadi!"],["Mess","kir va betartib holat",5,"The kids made a mess in the bathroom.","Bolalar vannani yoyib tashlashibdi."],["Messy","kir va betartib",5,"Your room's very messy. Go and tidy it up.","Xonangiz juda betartib–borib tartibga soling."],["Person","odam, shaxs",5,"She's the only person I can talk to about my problems.","U muammolarim to'g'risida gapira oladigan yagona odam men uchun."],["Personality","shaxsiyat, xarakter",5,"Jenny's got a great personality–she's so warm and friendly.","Jenni ajoyib xarakterga ega–u juda iliq va muloyim."],["Personal","shaxsiy",5,"I never talk to people I don't know about my personal life.","Men hech qachon tanimaydigan odamlarimga shaxsiy hayotim to'g'risida gapirmayman."],["Personally","shaxsan",5,"Personally, I think you need to find a new job.","Shaxsan men o'ylashimcha, siz yangi ish topishingiz kerak."],["Real","haqiqiy",5,"Are those real flowers?","Bular haqiqiy gullarmi?"],["Unreal","noreal, haqiqiy bo'lmagan",5,"It feels unreal that I no longer have to go to school.","Bundan buyon maktabga borishga majbur emasligim haqiqiy emasdek tuyulyapti."],["Reality","haqiqat",5,"In reality, the actor is very nice, but he always plays bad characters.","Haqiqatda, aktyor juda yaxshi, lekin u doim yomon ro'llarni o'ynaydi."],["Realise","anglab yetmoq, tushunmoq",5,"I realise you worked very hard on this homework.","Tushunishim bo'yicha, bu uy vazifasi ustida rosa qattiq ishlabsiz."],["Really","juda",5,"He looks unfriendly but he's really nice.","U ko'rinishidan do'stona emasdek, lekin u juda ham yaxshi odam."],["Tidy","tartibga solmoq, yig'ishtirmoq",5,"I've tidied the bedroom and the bathroom.","Men yotoqxona hamda vannani yig'ishtirib qo'ydim."],["Untidy","betartib",5,"Why is your bedroom so untidy? Pick up those clothes!","Nima uchun yotoqxonangiz bu qadar betartib? Anavi kiyimlarni yerdan oling!"],["Tidy","tartibli",5,"The room was clean and tidy.","Xona toza va tartibli edi."],["Tidily","tartib bilan",5,"She put her clothes away tidily in the wardrobe.","U kiyimlarini shkafga tartib bilan joyladi."],["Untidily","betartiblik bilan",5,"He went to school so untidily dressed that the head teacher sent him home.","U maktabga shu qadar betartiblik bilan kiyinib bordiki, direktor uni uyga yubordi."]]},{"n":6,"t":"Leisure Time","c":[["Activity","mashg'ulot",0,"Fishing is an activity anyone can do.","Baliq tutish istalgan odam qila oladigan mashg'ulot."],["Art","san'at",0,"I love all art, but painting most of all.","Men hamma san'at turini sevaman, lekin hammasidan ham bo'yashni ko'proq."],["Bicycle/Bike","velosiped",0,"Do you ride your bicycle to school?","Maktabga velosipedingizni minib borasizmi?"],["Camera","kamera, fotoapparat",0,"Can I take your picture with my new camera?","Yangi fotoapparatim bilan sizni rasmga olsam bo'ladimi?"],["CD (player)","CD disk pleyer",0,"My CD player doesn't play this pop music CD.","Mening CD disk pleyerim bu pop qo'shig'i diskini chalmaydi."],["Cinema","kinoteatr",0,"John went to the cinema to watch a film on Friday.","Jo'n juma kuni kino tomosha qilish uchun kinoteatrga bordi."],["Club","klub, to'garak",0,"My sister is in the chess club and plays every lunchtime.","Singlim shaxmat to'garagida va har tush vaqtida shaxmat o'ynaydi."],["Concert","konsert",0,"My favourite band gave a concert in my town yesterday.","Mening yoqtirgan guruhim kecha shahrimda konsert berdi."],["Drum","baraban, do'mbira",0,"The job of the drum is to keep the beat.","Do'mbiraning vazifasi ketma-ket ovozni ta'minlab berish."],["DVD (player)","DVD disk pleyer",0,"The DVD player is broken so we can't watch the film.","DVD disk pleyer buzilgan, shuning uchun biz kinoni tomosha qila olmaymiz."],["Film","kino",0,"My favourite kind of film is romantic comedy.","Mening yoqtirgan kino turim romantik komediya."],["Free time","bo'sh vaqt",0,"Do you do any sports in your free time?","Bo'sh vaqtingizda qandaydir sport bilan shug'ullanasizmi?"],["Guitar","gitara",0,"My sister plays guitar in a rock band.","Singlim ro'k guruhida gitara chaladi."],["Magazine","jurnal",0,"Do you know any good fishing magazines I can read?","O'qishim mumkin bo'lgan baliq tutish haqidagi qandaydir yaxshi jurnalni bilasizmi?"],["Member","a'zo",0,"Every member of the club must come to the meeting.","Klubning har bir a'zosi majlisga kelishi shart."],["MP3 (player)","MP3 pleyer",0,"How many songs have you got on your MP3 player?","MP3 pleyeringizda nechta qo'shiq bor?"],["Music","musiqa",0,"What kind of music do you prefer, pop or rock?","Musiqaning qanday turini afzal ko'rasiz, pop yoki ro'k?"],["Piano","pianina, fortepiano",0,"Joanne plays the piano beautifully.","Jo'an pianinani chiroyli chaladi."],["Television/TV","televizor",0,"Is there any good comedy on TV tonight?","Bugun oqshomda televizorda qandaydir yaxshi komediya beradimi?"],["Theatre","teatr",0,"The actor first performed in the theatre when she was ten.","Aktyor birinchi marta 10 yoshligida teatrda chiqish qilgan."],["Act","rol o'ynamoq",1,"Who acts in this film?","Bu kinoda kim rol o'ynaydi?"],["Collect","to'plamoq, yig'moq",1,"Lee collects coins and has ones from all over the world.","Li tangalar to'playdi va unda butun dunyodan tangalar bor."],["Dance","raqs tushmoq",1,"Nobody at the party is dancing because they dislike the music.","Bazmdagi hech kim raqs tushmayapti chunki ularga musiqa yoqmadi."],["Fix","tuzatmoq",1,"My dad fixes my bike when it has a problem.","Qachonki velosipedimda muammo bo'lsa, otam uni tuzatadi."],["Improve","yaxshila(n)moq",1,"You can improve at tennis if you practise a lot.","Agar ko'p shug'ullansangiz, tennisda yaxshilana olasiz."],["Join","qo'shilmoq",1,"It costs £10 to join the karate club.","Karate to'garagiga qo'shilish 10 funt sterling turadi."],["Perform","ijro etmoq, namoyish etmoq",1,"They performed the play in front of 200 people.","Ular 200 ta odam ko'z oldida spektaklni namoyish etishdi."],["Play","chalmoq (musiqa asbobi)",1,"Can you play any musical instruments?","Qandaydir musiqiy asbobni chala olasizmi?"],["Sing","kuylamoq",1,"She takes voice lessons to help her sing better.","U yaxshiroq kuylashiga yordam berishi uchun ovozni yaxshilaydigan darslar oladi."],["Visit","tashrif buyurmoq",1,"How often does your aunt from Miami visit you?","Mayamilik xolangiz qanchalik tez-tez siznikiga tashrif buyurib turadi?"],["Watch (TV/a programme)","televizor/ko'rsatuvni tomosha qilmoq",1,"I don't want to watch TV again tonight.","Bugun oqshomda yana televizor tomosha qilishni xohlamayman."],["Dress up (in fancy dress)","mashhur inson/qahramon libosinikidek libos kiymoq",2,"I'm dressing up as a rock star for the fancy dress party.","Men maskaradga (= odamlar qiyofani o'zgartirib boshqacha liboslarda boradigan kecha) ro'k yulduzidek kiyinib boraman."],["Go out (with)","(...bilan) ko'chaga aylanishga chiqmoq",2,"Do you go out with your friends on Friday nights?","Siz juma tunlarida do'stlaringiz bilan tashqariga aylangani chiqasizmi?"],["Hang out/around (with)","(...bilan) ko'p vaqt o'tkazmoq",2,"The girls spent the day hanging out at the mall.","Qizlar kunni do'konda sarflab o'tkazishdi."],["Laze around","yalqovlik qilmoq, kam ish qilib ko'p dam olmoq",2,"Ivan just lazed around doing nothing all Sunday.","Ivan butun yakshanba davomida hech narsa qilmay shunchaki yalqovlik qildi."],["Take up","odat sifatida boshlamoq",2,"If you're bored, take up a new hobby.","Agar zeriksangiz, yangi hobbi boshlang."],["Be good at (something)","(biron narsa qilish) da yaxshi bo'lmoq, usta bo'lmoq",3,"Pat is very good at tennis and always beats me.","Pat tennisda juda usta va har doim meni mag'lub qiladi."],["Belong to (a club/etc)","(klub/va hokazo) ga a'zo bo'lmoq",3,"We belong to a cycling club and go out on our bikes every Sunday.","Biz velosiped uchish klubiga a'zomiz va har yakshanba kuni velosipedimizda aylanishga chiqamiz."],["Enjoy myself/yourself/etc","mazza qilmoq",3,"I really enjoyed myself at the pool–let's go again soon!","Basseynda juda mazza qildim–keling yaqin kunlarda yana boramiz!"],["Go horse-riding","ot minishga bormoq",3,"Joan doesn't want to go horse-riding as she thinks she'll fall off.","Jo'un ot minishga borishni xohlamaydi chunki u yiqilib tushaman deb o'ylaydi."],["Go skateboarding","skeytbord uchishga bormoq",3,"Go skateboarding every weekend and you'll soon learn to go really fast.","Har dam olish kuni skeytbord uchishga boring va tez orada juda tez uchishni o'rganib olasiz."],["Go to the cinema","kinoga bormoq",3,"Can we go to the cinema and watch that new action film?","Kinoga borib, yangi chiqqan jangari filmni ko'rsak bo'ladimi?"],["Listen to (something)","(biron narsa) ni tinglamoq",3,"What music are you listening to on your MP3 player?","MP3 pleyeringizda qanday musiqa tinglayapsiz?"],["Look at (someone/something)","(biron kim/narsa) ga qaramoq",3,"Look at Natasha running! Isn't she fast?","Natashaning yugurishiga qarang! U tezkor-a?"],["Ride a bike","velosiped uchmoq",3,"Everyone falls off a few times while they're learning to ride a bike.","Velosiped uchishni o'rganayotib hamma ham bir necha marta yiqilib tushadi."],["Write a blog","blog yuritmoq",3,"Harry writes a blog about fishing and he has 500 readers!","Hari baliq tutish haqida blog yuritadi va uning 500 nafar o'quvchisi (= postlarni o'quvchilar) bor!"],["Beautiful","chiroyli",4,"The country is beautiful, with lots of forests and rivers.","Mamlakat ko'plab o'rmonlari va daryolari bilan chiroyli."],["Classical","mumtoz (musiqa): og'ir (musiqa)",4,"I went to a classical music concert with my dad.","Men dadam bilan mumtoz musiqa konsertiga bordim."],["Great","ajoyib, zo'r",4,"A great way to get fit is running–it's even better than cycling.","Jismonan tetiklikka erishishning ajoyib yo'li bu yugurishdir–u hattoki velosiped uchishdan ham yaxshiroq."],["Pop","po'p",4,"Young people like pop music because it's easy to listen to.","Yoshlar po'p musiqasini yoqtiradi chunki u tinglashga oson."],["Rock","ro'k",4,"I like rock music because I love the electric guitar.","Men ro'k musiqasini yoqtiraman chunki men elektrik gitarani sevaman."],["Weekly","haftalik",4,"I listen to a weekly radio show about sailing every Sunday.","Men har yakshanba kuni qayiqda suzish sporti haqidagi haftalik radio shouni tinglayman."],["Indoors","ichkari(ga/da)",4,"It's too hot out here–let's go indoors.","Tashqari haddan tashqari issiq–keling ichkariga kiramiz."],["Outdoors","tashqari(ga/da)",4,"The band are playing their last concert outdoors, in the park.","Musiqiy guruh oxirgi konsertlarini tashqarida–parkda–ijro etishadi."],["Recently","yaqinda",4,"The actor lived in London until recently, but he moved to LA.","Aktyor yaqin oragacha Londonda yashagan, lekin u Los Angelesga ko'chib o'tdi."],["Actor","aktyor",5,"My favourite actor plays in this film.","Mening sevimli aktyorim bu filmda o'ynagan."],["Actress","aktrisa",5,"Jenny's an actress on TV.","Jeni televizorda aktrisa."],["Acting","rol o'ynash",5,"Most of the acting in the show was excellent.","Shouda ro'l o'ynashlarning ko'pchiligi a'lo darajada bo'lgan."],["Art","san'at: asosan rassomchilik va haykaltaroshlik",5,"It's a very beautiful piece of art.","U juda maftunkor san'at asari."],["Artist","rassom, musavvir",5,"The art gallery offered to put on the artist's first show.","San'at galareyasi musavvirning ilk namoyishini tashkillashtirish taklifini berdi."],["Artistic","san'atda qobiliyatli, didli",5,"Ursula's very artistic and likes painting.","Ersyula san'atda juda qobiliyatli va u rasm chizishni yoqtiradi."],["Camp","chodir ko'tarib, qisqa muddat davomida tabiat qo'ynida yashamoq",5,"I camped overnight in a field.","Men keng maydonda bir kecha chodir ichida tunadim."],["Camp","chodir",5,"Let's return to camp.","Keling chodirga qaytamiz."],["Camper","chodirchi, chodir tikib ta'til o'tkazadigan odam",5,"Campers must not light fires near the tents.","Chodir tikib ta'til o'tkazayotganlar chodirlar yaqinida olov yoqmasliklari shart."],["Camping","ta'tilni tabiat qo'ynida chodir tikib o'tkazmoq, kemping",5,"My family always goes camping because it's cheap.","Oilam doim kemping qiladi chunki bu arzon."],["Campsite","chodir tikish uchun mo'ljallangan hudud",5,"The campsite could fit 500 tents and 100 caravans.","Chodir tikish uchun mo'ljallangan hudud 500 ta chodirni hamda 100 ta mashinaga ulangan vagonni sig'dira olardi."],["Collection","to'plam",5,"Can I look at your stamp collection?","Markalar to'plamingizni ko'rib chiqsam bo'ladimi?"],["Collecting","to'plash",5,"Collecting toy cars is something I did as a child.","O'yinchoq mashinalar to'plash bolalik chog'imda qilgan narsam."],["Collector","yig'uvchi, biron narsa to'plovchi, kolleksioner",5,"A serious collector can have coins worth thousands.","Jiddiy kolleksionerning bahosi minglarga teng tangalari bo'lishi mumkin."],["Compete","musobaqalashmoq, raqobatlashmoq",5,"He regularly competes in races.","U doimiy tarzda poygalarda musobaqalashadi."],["Competition","musobaqa, raqobat",5,"The winner of the competition gets a medal.","Musobaqa g'olibi medal oladi."],["Competitive","raqobatbardosh",5,"Roger's very competitive and always wants to win.","Ro'jer juda raqobatbardosh va doim yutishni xohlaydi."],["Entertain","biron kimni ko'nglini chog' qilmoq",5,"She entertained us with stories of her travels.","U sayohatlari haqidagi hikoyalari bilan bizni ko'nglimizni chog' qildi (= zeriktirmadi)."],["Entertainment","o'yin-kulgi, sayr-tomosha",5,"What's your favourite form of entertainment? Mine's the cinema.","O'yin-kulgining qaysi turi sizning sevimligingiz? Meniki kino."],["Entertainer","qiziqchi",5,"We called a children's entertainer to hire him for the birthday party.","Biz tug'ilgan kun bazmi uchun yollash maqsadida bolalar qiziqchisiga qo'ng'iroq qildik."],["Entertaining","ko'ngilochar, qiziqarli, maroqli",5,"It was an entertaining film that made me laugh quite often.","U meni rosa kuldirgan maroqli film edi."],["Dance","raqs",5,"The next dance will be a waltz.","Navbatdagi raqs vals bo'ladi."],["Dancing","raqs tushish",5,"I like pop music because it's good for dancing.","Menga po'p musiqa yoqadi chunki u raqs tushish uchun yaxshi."],["Dancer","raqqos",5,"Kate's sister is a dancer who performs in music videos.","Keytning singlisi musiqiy videolarda chiqadigan raqqosa."],["Draw","chizmoq",5,"You draw beautifully.","Siz chiroyli rasm chizarkansiz."],["Drawing","rasm, surat (mo'yqalamda chizilgani); chizish",5,"The artist did a drawing of me and my dog in pencil.","Musavvir qalam yordamida men va itimning suratimizni chizib berdi."],["Interest","qiziqish",5,"Her main interests are music and tennis.","Uning asosiy qiziqishlari musiqa va tennisdir."],["Interesting","qiziqarli",5,"Tell me more about the book–it's very interesting.","Kitob haqida ko'proq aytib bering–juda qiziqarli ekan."],["Interested","biron narsaga qiziqqan",5,"Our son is interested in photography, so we bought him a camera.","O'g'limiz fotograflikka qiziqadi, shuning uchun unga fotoapparat sotib olib berdik."],["Paint","chizmoq",5,"My mother paints well.","Oyim yaxshi rasm chizadilar."],["Paint","bo'yoq",5,"The paint is starting to peel off.","Bo'yoq ko'cha boshlamoqda."],["Painting","rasm, surat (mo'yqalamda chizilgani)",5,"There was a colourful painting of some flowers on the wall.","Devorda rang-barang gullar surati bor edi."],["Painter","rassom",5,"Picasso was probably the greatest painter of the 20th century.","Pikasso 20-asrning eng buyuk rassomi bo'lgan bo'lsa kerak."],["Photograph","rasmga tushirmoq",5,"He has photographed many other celebrities too.","U boshqa ko'plab mashhurlarni ham rasmga tushirgan."],["Photograph","rasm, surat (fotoapparatda olingani)",5,"His photograph appeared in the local paper.","Uning surati mahalliy gazetada chiqdi."],["Photographer","fotograf",5,"The photographer told us to smile so he could take our picture.","Fotograf bizni rasmga ola olishi uchun tabassum qilishimizni aytdi."],["Photography","rasmga tushirish san'ati",5,"Photography is a cheap hobby now that there are digital cameras.","Hozirda raqamli kameralar mavjud bo'lgani sababli, fotograflik arzongarov mashg'ulot."],["Singer","qo'shiqchi",5,"Their brother is the singer in a rock band.","Ularning akasi ro'k guruhida qo'shiqchi."],["Song","qo'shiq",5,"Do you write all the songs for your band?","Guruhingiz uchun barcha qo'shiqlarni o'zingiz yozasizmi?"]]},{"n":9,"t":"Sport","c":[["Basketball","basketbol",0,"It's good to be tall if you play basketball.","Agar basketbol o'ynasangiz, baland bo'yli bo'lish yaxshi."],["Captain","sardor, kapitan",0,"Joe's the captain of the team, so on the pitch you listen to him.","Jo' jamoa sardori, shunday ekan maydonda unga quloq solasiz."],["Coach","murabbiy",0,"The coach told me I have to be fitter to get on the team.","Murabbiy menga aytdiki, jamoaga kirishim uchun men baquvvatroq va sog'lomroq bo'lishim kerak ekan."],["Competition","musobaqa",0,"Her grandson came first in the swimming competition.","Uning nabirasi suzish musobaqasida birinchi bo'lib keldi."],["Fan","muxlis, fonat",0,"He is a huge fan and goes to every game they play.","U ashaddiy muxlis va ular o'ynaydigan har bir o'yinga boradi."],["Football","futbol",0,"Football is the most popular team sport in the world.","Futbol dunyodagi eng mashhur jamoaviy sport."],["Goal","go'l",0,"I scored a goal at the end of the game, so we won 1:0.","Men o'yin yakunida bitta go'l urdim, shuning uchun biz 1:0 hisobda g'alaba qozondik."],["Gym","sport zali",0,"Sue goes to the gym to build up her muscles after the accident.","Syu halokatdan so'ng muskullarini chiniqtirish uchun sport zaliga boradi."],["Hockey","hakkey",0,"In hockey, you can't raise your stick above the shoulder.","Hakkey o'yinida, tayoqchani yelkadan yuqoriga ko'tara olmaysiz (= taqiqlangan)."],["Ice skating","muz ustida konkida uchish",0,"I never go ice skating because I'm scared of slipping over.","Men hech qachon muz ustida konkida uchishga bormayman chunki men sirpalib tushishdan qo'rqaman."],["Player","o'yinchi",0,"The best player on the team is Simon and he scores all the goals.","Jamoadagi eng yaxshi o'yinchi Saymen va barcha go'llarni u uradi."],["Practice","mashg'ulot, mashq",0,"It takes practice to shoot baskets from so far away.","Savatchani bunday uzoqlikdan mo'ljalga olish ko'p mashq talab qiladi."],["Prize","sovrin, yutuq",0,"The winner of the bike race won a prize of £5000.","Velosiped poygasining g'olibi 5000 funt sterlingga teng yutuq yutib oldi."],["Race","poyga",0,"Ten runners are taking part in this ten-mile race.","Ushbu 10 milya uzunlikdagi poygada o'n nafar yuguruvchi qatnashmoqda."],["Racket","tennis raketkasi 🎾",0,"The tennis player hit the ball so hard that he broke his racket.","Tennischi koptokchani shu qadar qattiq urdiki, u raketkasini sindirib qo'ydi."],["Skiing","chang'i uchish",0,"Lots of people come to this mountain village in winter for skiing.","Ko'plab odamlar chang'i uchish uchun qishda ushbu tog'da joylashgan qishloqqa keladi."],["Snowboarding","snovbordda uchish",0,"Snowboarding is a popular winter sport among skateboarders.","Snovbordda uchish skeytbordchilar orasida mashhur qish sporti."],["Sports centre","sport markazi: ichida turli-tuman sportlar bilan shug'ullanish mumkin",0,"Liam joined the sports centre and goes there every day to use the gym or pool.","Liem sport markaziga qo'shildi va u yerga har kuni sport zali yoki basseyndan foydalanish uchun boradi."],["Stadium","stadion",0,"The stadium was full of fans enjoying the match.","Stadion o'yindan mazza qilayotgan muxlislarga to'la edi."],["Swimming","suzish",0,"Swimming is great exercise because it's hard to get injured in the water.","Suzish ajoyib mashq chunki suvda jarohat olish qiyin."],["Table tennis","stol tennisi",0,"Table tennis is a great indoor sport played with two bats 🏓 and a ball.","Stol tennisi ikkita tayoqcha va bitta koptokcha bilan bino ichida o'ynaladigan ajoyib sport turi."],["Team","jamoa",0,"There are five players on a basketball team.","Bitta basketbol jamoasida besh nafar o'yinchi bo'ladi."],["Tennis player","tennischi",0,"The biggest competition for a tennis player is probably Wimbledon.","Tennischi uchun eng katta musobaqa, ehtimol, Uimbldondir."],["Ticket","chipta, bilet",0,"How much is a ticket for the football match tomorrow?","Ertangi futbol o'yini uchun chipta necha pul?"],["Cancel","bekor qilmoq",1,"They cancelled the football match because it was raining so hard.","Futbol o'yinini bekor qilishdi chunki sharroz yomg'ir yog'ayotgandi."],["Catch","ushlab olmoq",1,"You throw the ball and I'll catch it.","Siz to'pni uloqtirasiz, men esa uni ushlab olaman."],["Cycle","velosiped uchmoq",1,"The plan was to cycle 50 miles, but my bike had a problem.","Reja 50 milya masofani velosipedda bosib o'tish edi, lekin mening velosipedimda muammo ro'y berdi."],["Deserve","munosib bo'lmoq",1,"You were unlucky to lose. You deserved to win.","Mag'lub bo'lishingiz omadsizlik bo'ldi. Siz g'alaba qozonishga munosib edingiz."],["Drop","tashlab yubormoq, tushirib yubormoq",1,"I threw the ball to him but he dropped it.","Men to'pni unga uloqtirdim, ammo u tushirib yubordi."],["Encourage","ruhlantirmoq, chorlamoq, da'vat qilmoq, undamoq",1,"Our coach encouraged us to try a little harder.","Murabbiyimiz bizni biroz qattiqroq harakat qilishga undadi."],["End","tugamoq, yakunlanmoq",1,"The match starts at five and ends at six forty-five.","O'yin soat 5 da boshlanadi va 6.45 da tugaydi."],["Enter (a competition/race/etc)","(musobaqa/poyga/va hokazoga) qo'shilmoq",1,"You have to be under 16 to enter the race.","Poygaga qo'shilish uchun 16 yoshdan kichik bo'lishingiz lozim."],["Push","itarmoq",1,"The other player pushed me away from the ball and I fell down.","Boshqa o'yinchi meni to'pdan nariga itarib yubordi va men yiqilib tushdim."],["Reach","yetib bormoq",1,"Tony was tired when he reached the end of the race.","To'ni poyganing oxiriga yetganida, u charchagan edi."],["Ride","velosiped yoki mototsikl haydamoq; ot minmoq",1,"The first time you ride a horse can be scary because they're big animals.","Birinchi marta ot minish qo'rqinchli bo'lishi mumkin chunki ular katta hayvonlar."],["Roll","yumalamoq, dumalamoq",1,"The ball rolled slowly across the line and into the net. Goal!","To'p sekinlik bilan chiziq bo'ylab to'r ichiga dumaladi. Go'l!"],["Score","go'l urmoq, natija qayd etmoq",1,"Sharon's our best player–she scored fifteen goals last year.","Sheron bizning eng yaxshi o'yinchimiz–u o'tgan yilda o'n beshta go'l urdi."],["Select","tanlamoq",1,"I'm playing well at the moment, so the coach selected me for the team.","Men ayni damda yaxshi o'ynayapman, shuning uchun murabbiy jamoaga meni tanladi."],["Shove","turtkilamoq, turtib yubormoq",1,"You can't shove the other player out of the way to get to the ball.","To'pga yetish uchun boshqa o'yinchini turtib yo'ldan olib tashlolmaysiz."],["Skate","konkida uchmoq",1,"The ice hockey player skated fast towards the goal.","Hakkeychi tezlik bilan darvoza tomon uchdi."],["Throw","uloqtirmoq, otmoq",1,"The basketball player threw the ball towards the basket.","Basketbolchi to'pni savat tomon uloqtirdi."],["Touch","ushlamoq, qo'l bilan teginmoq",1,"Only the goalkeeper can touch the ball with their hand in football.","Futbolda faqatgina darvozabon to'pga qo'li bilan tegina oladi."],["Watch (a game/match)","(o'yinni) tomosha qilmoq",1,"Let's go and watch the match in the stadium, not on TV.","Keling o'yinni borib stadionda tomosha qilamiz, televizorda emas."],["Congratulate someone on something","biror kimni biror narsa bilan tabriklamoq",3,"The coach congratulated the team on winning the cup.","Murabbiy jamoani kubokni yutgani bilan tabrikladi."],["Do judo/tae kwon do/karate/etc","dzyudo/taekvando/karate/va hokazo bilan shug'ullanmoq",3,"I do judo and I've got a black belt.","Men dzyudo bilan shug'ullanaman va mening qora belbog'im bor."],["Football boots","futbol butsalari (futbol o'ynash uchun mo'ljallangan oyoq kiyimlar)",3,"My old football boots have got a hole near the toe.","Mening eski futbol butsalarimning barmoq qismida (= uchida) teshik bor."],["Go skiing/snowboarding/surfing/etc","chang'i uchishga/snovbordda uchishga/dengizda syo'rfing qilishga/va hokazo qilishga bormoq",3,"We'll go skiing this weekend if it snows in the mountains.","Agar tog'da qor yog'sa, bu hafta oxirida chang'i uchishga boramiz."],["In the end","oxirida, so'ngida, oxir-oqibat",3,"In the end we won the game, though it was really hard.","Qiyin bo'lishiga qaramay, oxir-oqibat o'yinda biz g'olib bo'ldik."],["Lose a match/game/competition","o'yinni/musobaqani boy bermoq, mag'lub bo'lmoq",3,"We lost the match when the other team scored near the end.","Narigi jamoa yakunga yaqin qolganda go'l urgan vaqtda biz o'yinni boy berdik."],["On TV","televizorda (ko'rsatilmoq)",3,"Is the match on TV tonight?","O'yin bugun oqshomda televizorda ko'rsatiladimi?"],["Play golf/football/baseball/etc","golf/futbol/beysbol/va hokazo o'ynamoq",3,"Can you play golf? It looks very hard.","Siz golf o'ynay olasizmi? U juda qiyin ko'rinadi."],["Take part in (something)","(biror narsa)da ishtirok etmoq",3,"Fifty runners are taking part in the race.","Poygada ellik nafar yuguruvchi ishtirok etmoqda."],["Win a match/game/competition","o'yin/musobaqada g'olib bo'lmoq",3,"We rarely win our matches, but we enjoy playing anyway.","Biz kamdan-kam holatda o'yinda g'alaba qonozamiz, ammo shunga qaramay o'ynashdan rohatlanamiz."],["Exciting","maroqli, ajoyib",4,"What an exciting game! I don't know who's going to win!","Naqadar ajoyib o'yin-a! Bilmasam kim yutadi!"],["Fantastic","ajoyib",4,"The team was fantastic and won 5:0.","Jamoa ajoyib bo'ldi va 5:0 hisobda g'alaba qozondi."],["Fast","tezkor",4,"Oscar's very fast and usually wins running races.","O'skr juda tezkor va odatda yugurish poygalarida g'olib bo'ladi."],["Indoor","bino ichidagi",4,"The hotel has an indoor swimming pool, which is good when it's winter.","Mehmonxonada ichki basseyn bor va bu qish faslida yaxshi."],["Outdoor","ochiq havodagi, bino ichida bo'lmagan",4,"I like to get fresh air, so I prefer outdoor sports.","Men toza havo olishni yoqtiraman, shuning uchun ochiq havoda bajariladigan sportlarni afzal ko'raman."],["Popular","taniqli",4,"Football is a popular sport, with many people playing it or watching it.","Futbol mashhur sport turi bo'lib, uni ko'pchilik o'ynaydi yoki tomosha qiladi."],["Strong","kuchli",4,"He's a strong swimmer who wins all the races that he enters.","U qo'shilgan barcha poygasida g'olib bo'ladigan kuchli suzuvchi."],["First","birinchi",4,"The team that comes first in the competition wins a cup.","Musobaqada birinchi bo'lib kelgan jamoa kubokni yutadi."],["Last","oxirgi",4,"She hurt her leg and came last in the race.","U oyog'ini shikastlab oldi va poygada oxirgi bo'lib keldi."],["Well","yaxshi",4,"Wendy got on the team because she plays well.","Vendi jamoaga kirdi chunki u yaxshi o'ynaydi."],["Congratulate","tabriklamoq",5,"I congratulated them all on their results.","Men ularning barini natijalari bilan tabrikladim."],["Congratulations","tabriklar (= tabriklayman)",5,"Congratulations on winning the prize!","Sovrinni yutganingiz bilan tabriklayman!"],["Danger","xavf",5,"We weren't in any danger.","Biz hech qanday xavf ostida emasdik."],["Dangerous","xavfli",5,"Snowboarding can be dangerous if you fall while going fast.","Agar tez ketayotganda yiqilib tushsangiz, snovbordda uchish sporti xavfli tus olishi mumkin."],["Enter","kirmoq",5,"Someone entered the room behind me.","Kimdir mening ortimdan xonaga kirdi."],["Entrance","kirish joyi",5,"The entrance to the stadium was full of fans.","Stadionga kirish joyi muxlislarga to'la edi."],["Excite","quvontirmoq",5,"Nothing about my life excites me at present.","Hozirgi paytda hayotimdagi hech narsa meni quvontirmaydi."],["Excitement","xursandchilik, maroq, quvonch",5,"The fans were full of excitement as the teams came out.","Jamoalar chiqar ekan, muxlislar quvonchga to'la edi."],["Exciting","ajoyib, maroqli",5,"It was an exciting game, with four goals before the end of the first half.","Ajoyib o'yin bo'ldi, birinchi yarmi tugashidan avval to'rtta go'l urildi."],["Excited","xursand, zavq-shavqqa to'la",5,"I'm very excited–I'm taking part in my first swimming competition today.","Men juda zavqlanib ketyapman–bugun men birinchi suzish musobaqamda ishtirok etyapman."],["Fame","mashhurlik, shon-shuhrat",5,"She first rose to fame as a singer at the age of 16.","U ilk bor 16 yoshida qo'shiqchi sifatida mashhurlikka ko'tarildi."],["Famous","mashhur",5,"Ronaldo's a famous football player who has won every cup you can imagine.","Ronaldo siz tasavvur qilishingiz mumkin bo'lgan har qanday kubokni yutgan mashhur futbolchi."],["Lose","yutqazmoq, mag'lub bo'lmoq",5,"We lost to a stronger team.","Biz kuchliroq jamoaga yengildik."],["Loser","mag'lub",5,"The winner of the final gets £300,000, but the loser gets some money too.","Final g'olibi 300,000 funt sterling oladi, lekin mag'lub ham ozgina pul oladi."],["Play","o'ynamoq",5,"She has played in every game this season.","U ushbu mavsumdagi har bir o'yinda o'ynadi."],["Practise","mashq qilmoq, shug'ullanmoq",5,"She's the best tennis player because she practises every day.","U eng yaxshi tennischi chunki u har kuni shug'ullanadi."],["Ski","chang'i uchmoq 🎿",5,"Our children want to learn to ski.","Farzandlarimiz chang'i uchishni o'rganishni istashadi."],["Train","shug'ullanmoq",5,"I train in the gym for two hours a day.","Men kuniga ikki soat sport zalida shug'ullanaman."],["Training","mashg'ulot",5,"When Joe arrived late at training, the coach shouted at him.","Jo' mashg'ulotga kech yetib kelganida, murabbiy unga baqirdi."],["Trainer","trener, murabbiy",5,"Paula's a trainer at a local gym.","Po'la mahalliy sport zalda trener."],["Win","yutmoq, g'olib bo'lmoq",5,"Our team easily won the competition.","Bizning jamoa musobaqada osonlik bilan g'olib bo'ldi."],["Winner","g'olib",5,"The winner of the competition held the cup above his head.","Musobaqa g'olibi kubokni boshi uzra ko'tardi."]]},{"n":12,"t":"School","c":[["Board","doska",0,"The teacher wrote the homework up on the board.","O'qituvchi uy vazifasini doskaga yozdi."],["Class(room)","sinf (xonasi)",0,"The kids had covered the walls of the classroom with their work.","Bolalar sinfxona devorlarini o'zlari tayyorlagan narsalar bilan qoplab chiqishgan edi."],["Desk","parta, o'quvchi stoli",0,"The students were sitting at their desks writing an essay.","O'quvchilar o'z partalarida insho yozib o'tirgan edi."],["Dictionary","lug'at",0,"Look up any words you don't know in your dictionary.","Bilmaydigan har qanday so'zlaringizni lug'atdan qidiring."],["Exam","imtihon",0,"You must get 55% to pass the exam.","Imtihondan muvaffaqiyatli o'tish uchun 55% olishingiz shart."],["Head teacher","maktab direktori",0,"His teacher sent him to the head teacher for talking in class.","Uning o'qituvchisi uni darsda gaplashgani uchun maktab direktoriga yubordi."],["Homework","uyga berilgan vazifa",0,"Our teacher asked us to do some research on the Internet for homework.","O'qituvchimiz bizdan uy vazifasi uchun internetda biroz izlanish qilishimizni so'radi."],["IWB (interactive white board)","interaktiv doska",0,"Our teacher made Julie go to the front of the class and write the answer on the IWB.","O'qituvchimiz Julini sinf oldiga olib borib, javobni interaktiv doskaga yozdirdi."],["Language","til",0,"The English language is the language of business.","Ingliz tili tadbirkorlik tilidir."],["Lesson","dars",0,"Our Maths lesson can be quite boring sometimes.","Matematika darsimiz ba'zida ancha zerikarli bo'lib turadi."],["Library","kutubxona",0,"We can borrow three books from the library every week.","Kutubxonadan har haftada uchta kitob olib turishimiz mumkin."],["Notebook","daftar, qaydnoma",0,"Write down these nouns in your notebooks.","Ushbu otlarni daftarlaringizga yozib oling."],["Project","loyiha, proyekt, vazifa",0,"Ivan is doing a project on growing fruit this term.","Ivan ushbu chorakda meva o'stirish ustida loyiha olib boryapti."],["Pupil","(faqatgina) maktab o'quvchisi",0,"All the pupils in the class helped to get the class ready for parents' evening.","Sinfdagi barcha o'quvchilar sinfni ota-onalar kechasi uchun tayyorlashga yordam berishdi."],["Report","o'quvchining baholari to'g'risidagi hisobot (maktabda)",0,"Peter's parents were pleased with his report–he got all A's!","Piterning ota-onasi uning baholari to'g'risidagi hisobotidan mamnun bo'lishdi–u faqat A baholari (= a'lo baho) olgandi!"],["School trip","maktab tomonidan uyushtirilgan sayohat",0,"The class went on a school trip to the science museum.","Sinf maktab tomonidan ilm-fan muzeyiga sayohatga bordi."],["School uniform","maktab formasi",0,"The school uniform is black trousers, a white shirt and a blue tie.","Maktab formasi qora shim, oq ko'ylak va ko'k bo'yinboqdir."],["Student","o'quvchi: maktab o'quvchisi, universitet o'quvchisi, o'quv markazida biror narsa o'rganadigan o'quvchi, istalgan turdagi o'quvchi",0,"There are thirty students in my class.","Mening sinfimda o'ttiz nafar o'quvchi bor."],["Art","tasviriy san'at fani (rassomchilik)",0,"We learned how to draw faces in Art today.","Biz bugun tasviriy san'at darsida yuz tuzilishini qanday chizishni o'rgandik."],["Biology","biologiya",0,"The Biology teacher is telling us about how plants grow.","Biologiya o'qituvchisi bizga o'simliklar qanday o'sishi haqida aytib beryapti."],["Chemistry","kimyo",0,"Do you do real experiments in Chemistry?","Kimyo darsida haqiqiy tajribalar o'tkazasizlarmi?"],["Geography","geografiya",0,"I'm learning the capital cities of the world for a Geography test.","Men geografiya fanidan test uchun dunyodagi poytaxt shaharlarni o'rganyapman."],["History","tarix",0,"We're doing the Second World War in History at the moment.","Ayni damda tarix darsida Ikkinchi Jahon Urushini o'tyapmiz."],["IT (Information Technology)","informatika texnologiyalari fani",0,"Do you learn how to program in IT?","Informatika texnologiyalari fanida qanday qilib dasturlashni o'rganasizmi?"],["Literature","adabiyot",0,"We are studying Tolstoy's Anna Karenina in Literature.","Adabiyot fanida Tolstoyning Anna Karenina asarini o'rganyapmiz."],["Maths","matematika",0,"We did some geometry in Maths today.","Bugun matematika darsida biroz geometriya o'rgandik."],["Music","musiqa",0,"We're learning about opera in Music at the moment.","Ayni damda musiqa darsida opera haqida o'rganyapmiz."],["PE (Physical Education)","jismoniy tarbiya",0,"In PE today, we played a game of football.","Bugun jismoniy tarbiya darsida biz futbol o'ynadik."],["Physics","fizika",0,"I'm learning Newton's laws for my Physics test.","Men fizika fanidan testim uchun Nyuton qonunlarini o'rganyapman."],["RE (Religious Education)","diniy ta'lim asoslari",0,"We learned about the life of the Prophet (PBUH) in RE today.","Bugun diniy ta'lim asoslari darsida biz Rasululloh (SAV) ning hayoti to'g'risida o'rgandik."],["Social Science","sotsiologiya (jamiyatni o'rganuvchi fan)",0,"Social Science teaches us how people live with one another.","Sotsiologiya fani bizga insonlar bir- biri bilan qanday qilib yashashini o'rgatadi."],["Term","chorak (maktabda), semestr (universitetda)",0,"At the end of Christmas term, we always give our teacher a present.","Rojdestvo choragining yakunida (= qishki kanikuldan avval), biz har doim o'qituvchimizga sovg'a beramiz."],["Timetable","o'quv jadvali, raspisaniya",0,"Ronny's timetable is hard on Tuesdays–he has Maths and Physics.","Seshanba kunlari Ro'nining o'quv jadvali og'ir–matematika va fizika darsi bor."],["Answer","javob bermoq",1,"You haven't answered my question.","Mening savolimga javob bermadingiz."],["Fail","imtihondan yiqilmoq",1,"Students who fail the test must take it again.","Imtihondan yiqilgan o'quvchilar uni qayta topshirishi shart."],["Know","bilmoq",1,"I don't know the answer to that question.","U savolga javobni bilmayman."],["Learn","o'rganmoq",1,"Our teacher makes us learn ten new verbs every week.","O'qituvchimiz bizni har hafta o'nta yangi fe'l o'rganishga majburlaydi."],["Mark","baholamoq",1,"If you don't hand your homework in on time, I won't mark it.","Agar uyga vazifangizni o'z vaqtida topshirmasangiz, men uni baholamayman."],["Match","mos keladiganini topmoq",1,"The exercise asks students to match pictures to vocabulary.","Ushbu mashq o'quvchilardan rasmlarga mos keladigan so'zlarni topishni so'raydi."],["Mean","ma'no anglatmoq",1,"Find out what the word means by looking it up in a dictionary.","Lug'atdan qidirish orqali, so'z nima ma'no bildirishini toping."],["Pass","imtihondan muvaffaqiyatli o'tmoq",1,"If I pass all my exams, my mum will buy me a new jacket.","Agar hamma imtihonlarimdan muvaffaqiyatli o'tsam, oyim menga yangi pidjak sotib olib beradilar."],["Read","(kitob, gazeta) o'qimoq",1,"I love to read comics and magazines.","Men ko'mik kitoblar va jurnallar o'qishni yoqtiraman."],["Remember","yodda tutmoq, eslab qolmoq",1,"We have to remember a lot of important dates for the History exam.","Tarix imtihoni uchun juda ko'p muhim sanalarni yodda saqlab qolishimiz kerak."],["Teach","o'qitmoq, o'rgatmoq",1,"Our English teacher taught us the past tenses today.","Ingliz tili o'qituvchimiz bugun bizga o'tgan zamonlarni o'rgatdilar."],["Tick","ptichka ( ✓) qo'yib belgilamoq",1,"Please tick the appropriate box.","Iltimos, tegishli katakchani belgilang."],["Understand","tushunmoq",1,"I still don't understand how to make programs in IT.","Men hali-hanuz informatika texnologiyalari fanida qanday qilib dasturlar yaratishni tushunmayman."],["Write","yozmoq",1,"We have to write an essay discussing a book we read in Literature.","Adabiyot darsida o'qigan kitobimizni muhokama qilgan holda bir insho yozishimiz kerak."],["Cross out","biror xatoni ustidan o'chirmoq (x chiziq chizmoq)",2,"When you make a mistake, just cross it out neatly.","Xatoga yo'l qo'yganingizda, shunchaki uni orastalik bilan ustidan chizib qo'ying."],["Give/Hand in","topshirmoq",2,"Hand in your homework to me at the end of the lesson.","Dars yakunida uyga vazifangizni menga topshiring."],["Give/Hand out","tarqatmoq",2,"The teacher handed out exam papers to the class.","O'qituvchi imtihon varaqalarini sinfga tarqatdi."],["Put up (your hand)","(qo'lini) yuqoriga ko'tarmoq",2,"Put up your hand if you know the answer–don't shout it out.","Agar javobni bilsangiz, qo'lingizni yuqoriga ko'taring–uni baqirib aytib yubormang."],["Rub out","o'chirg'ich bilan o'chirmoq",2,"Rub out the word that is spelled wrong and write it correctly.","Noto'g'ri harflar bilan yozilgan so'zni o'chirg'ich bilan o'chirib tashlang va uni to'g'rilab yozing."],["Write down","yozmoq, daftariga ko'chirib olmoq",2,"Write down these adjectives in your notebooks.","Ushbu sifatlarni daftarlaringizga yozib oling."],["Arrive at school","maktabga yetib bormoq",3,"I arrive at school at nine in the morning.","Men maktabga tonggi soat 9 da yetib boraman."],["At breaktime","tanaffus vaqtida",3,"At breaktime, my friends and I usually play football.","Tanaffus vaqtida, do'stlarim va men odatda futbol o'ynaymiz."],["Correct/Make a mistake","xatoni to'g'rilamoq/xato qilmoq",3,"I made a mistake and answered the wrong question in the exam.","Men xatoga yo'l qo'ydim va imtihonda noto'g'ri (= boshqa bir) savolga javob berib qo'ydim."],["Do homework","uyga vazifani bajarmoq",3,"Do you do your homework as soon as you get home?","Uyga yetib borishingiz bilanoq uyga vazifangizni bajarasizmi?"],["Do your best","qo'lidan kelgancha zo'r bajarmoq",3,"You don't have to get the top mark–just do your best.","Eng yuqori bahoni olishingiz shart emas– shunchaki qo'lingizdan kelgancha harakat qiling."],["Drive (someone) to school","(biror kimni) maktabga mashinada tashlab qo'ymoq",3,"Does your mother drive you to school every morning?","Har tongda onangiz sizni maktabga mashinada tashlab qo'yadimi?"],["Get a good/bad mark","yaxshi/yomon baho olmoq",3,"I got a bad mark in Maths–just 45%.","Matematikadan yomon baho oldim–bor yo'g'i 45%."],["Get to school","maktabga bormoq",3,"How do you get to school in the morning–by bus or car?","Tongda qanday qilib maktabga borasiz–avtobus orqalimi yoki mashinada?"],["Have a break/lesson","tanaffus/dars bo'lmoq",3,"They have a lesson with Mrs Evans at two o'clock.","Soat ikkida ularning Evens xonim bilan darslari bor."],["In ink/pencil","siyoh bilan (ruchkada)/qalamda",3,"When you write in ink, you can't rub out your mistakes.","Ruchkada yozganingizda, xatolaringizni o'chirg'ich bilan o'chirib tashlolmaysiz."],["Pay attention","diqqat qaratmoq, e'tibor bermoq",3,"I didn't pay attention to the teacher in class, so I couldn't do my homework.","Darsda men o'qituvchiga diqqatimni qaratmagandim, shuning uchun uyga vazifamni bajarolmadim."],["Take the register","davomat qilmoq, yo'qlama qilmoq, o'quvchi kelgan yoki kelmaganini belgilamoq",3,"The teacher takes the register every morning to see who's absent.","O'qituvchi kim darsda yo'q ekanligini ko'rish uchun har tongda davomat qiladi."],["Absent","(darsga) kelmagan, yo'q, ishtirok etmayotgan",4,"Carl was absent from school again today–is he sick?","Karl bugun yana maktabga kelmadi–u betobmi?"],["Complicated","murakkab",4,"A good teacher knows how to explain a complicated subject simply.","Yaxshi o'qituvchi qanday qilib murakkab bir mavzuni sodda tarzda tushuntirib berishni biladi."],["Favourite","sevimli",4,"English is my favourite subject–I love it!","Ingliz tili mening sevimli fanim–u menga yoqadi!"],["Important","muhim",4,"Catherine the Great is an important figure in Russian history.","Buyuk Kasrin Rossiya tarixida muhim shaxsdir."],["Intelligent","aqlli, zukko",4,"John's intelligent and always gets high marks.","Jo'n zukko va u doim yuqori baholar oladi."],["Right","to'g'ri",4,"Does anyone know the right answer?","Kimdir to'g'ri javobni biladimi?"],["Serious","jiddiy",4,"My best friend is sick today. I hope it's nothing serious.","Mening eng yaxshi do'stim bugun betob. Umid qilamanki, bu jiddiy narsa emas."],["Wrong","noto'g'ri",4,"I was so embarrassed when I gave the wrong answer to an easy question.","Oson savolga noto'g'ri javob berganimda juda uyalib ketdim."],["Right","to'g'ri tarzda",4,"Question 3 was really difficult, but I think I got it right.","3-savol juda qiyin edi, lekin menimcha uni to'g'ri topdim."],["Wrong","noto'g'ri tarzda",4,"If you get an answer wrong, you get zero.","Agar javobni noto'g'ri topsangiz, 0 olasiz."],["Apology","kechirim, uzr",5,"I think you should make an apology to your teacher for your rudeness.","O'ylashimcha, qo'polligingiz uchun o'qituvchingizdan uzr so'rashingiz kerak."],["Apologise","kechirim so'ramoq, uzr so'ramoq",5,"Why should I apologise?","Nima uchun men uzr so'rashim kerak?"],["Begin","boshlamoq",5,"I began piano lessons at the age of six.","Men olti yoshimda pianino saboqlarini boshlaganman."],["Beginner","biror narsani o'rganishni endigina boshlagan odam",5,"I'm only a beginner at tennis, so I'm not very good yet.","Tennisda bor yo'g'i boshlovchiman, shuning uchun hali juda usta emasman."],["Beginning","boshlanish",5,"Tell me the story from the beginning. How did it start?","Hikoyani boshidan aytib bering. U qanday boshlandi?"],["Correct","to'g'rilamoq",5,"Read through your work and correct any mistakes that you find.","Ishingizni o'qib chiqing va topgan har qanday xatolaringizni to'g'rilang."],["Correction","to'g'rilash",5,"I've made a few small corrections to your report.","Hisobotingizga bir nechta kichik to'g'rilashlar kiritdim."],["Correct","to'g'ri",5,"\"Your name is Angela Black?\" \"That is correct.\"","\"Ismingiz Anjela Blek-a?\" \"Ha, to'g'ri.\""],["Incorrect","noto'g'ri",5,"That's incorrect, Martin–the right answer is 25.","Bu noto'g'ri, Martin–to'g'ri javob 25."],["Correctly","to'g'ri tarzda",5,"A tick shows you answered the question correctly.","Ptichka belgisi ( ✓) savolga to'g'ri javob berganingizni ko'rsatadi."],["Incorrectly","noto'g'ri tarzda",5,"Of course the program doesn't work–you installed it incorrectly.","Albatta dastur ishlamaydida– uni noto'g'ri o'rnatgansiz."],["Educate","ta'lim bermoq",5,"Films can entertain and educate, make you laugh or cry.","Filmlar ko'ngilni ko'tarishi va ta'lim berishi, kuldirishi yoki yig'latishi mumkin."],["Education","ta'lim",5,"He got a good education in one of the best schools in the country.","U mamlakatdagi eng zo'r maktablardan birida yaxshi ta'lim olgan."],["Educational","tarbiyaviy, ta'limiy",5,"We brought the children on an educational trip to the Science Museum.","Biz bolalarni Ilm-fan Muzeyiga bo'lgan ta'limiy sayohatga olib bordik."],["Encourage","ruhlantirmoq, qo'llab-quvvatlamoq, dalda bo'lmoq",5,"\"You're doing fine,\" he encouraged her.","\"Yaxshi bajaryapsiz,\" deya yigit qizga dalda berdi."],["Encouragement","dalda, ruhlantirish, qo'llab-quvvatlash",5,"Children need the encouragement of their parents to do well.","Bolalar yaxshi harakat qilishlari uchun ota-onasining qo'llab-quvvatlashiga muhtoj."],["Encouraging","dalda bo'luvchi, ruhlantiruvchi, shijoatni oshiradigan",5,"I try to be encouraging of my son's plans, even if I don't agree with them.","Men o'g'limning rejalariga dalda bo'luvchi bo'lishga harakat qilaman, hattoki rozi bo'lmasam ham."],["Unimportant","ahamiyatsiz, muhim bo'lmagan",5,"Your mark is unimportant to me as long as you do your best.","Qo'lingizdan kelgancha yaxshi harakat qilar ekansiz, bahoyingiz menga ahamiyatsiz."],["Importance","ahamiyat, muhimlilik",5,"An education is of great importance to a child.","Ta'lim yosh bola uchun ulkan ahamiyatga ega."],["Meaning","ma'no",5,"What is the exact meaning of the word?","So'zning aniq ma'nosi nima?"],["Spell","so'zni harflab yozmoq yoki aytmoq: D-E-S-T-I-N-A-T-I-O-N",5,"Can you spell your last name, please?","Familyangizni harflab ayta olasizmi, iltimos?"],["Spelling","so'zning harflab yozilishi, imlo",5,"This word has a different spelling in American and British English.","Bu so'z Amerika va Britaniya ingliz tilisida turli xil yozilishga ega."],["Study","o'qimoq, tahsil olmoq",5,"My brother studied photography at the Royal College of Art.","Mening akam Qirollik San'at Kollejida fotograflik bo'yicha tahsil olgan."],["Student","o'quvchi",5,"Over 10,000 students attend that university.","10,000 dan ziyod o'quvchilar u universitetga boradi."],["Studies","o'qish, o'rganish, tahsil olish",5,"He's going to an American university to continue his studies.","U o'qishini davom ettirish uchun Amerikadagi universitetga ketyapti."],["Teach","o'qitmoq, dars bermoq",5,"He teaches English to advanced students.","U yuqori darajadagi o'quvchilarga ingliz tilidan dars beradi."],["Teacher","o'qituvchi",5,"His mother's a teacher at his school.","Uning oyisi u o'qiydigan maktabda o'qituvchi."]]},{"n":15,"t":"Work","c":[["Boss","boshliq, xo'jayin",0,"Sean asked his boss if he could take Friday off work.","Sho'n boshlig'idan juma kuni ishdan dam olsam maylimi, deb so'radi."],["Career","karyera, ish faoliyati",0,"You have to study hard if you want to go on to a career in law.","Agar huquqshunoslik sohasida faoliyat yuritishni xohlasangiz, qattiq o'qishingiz kerak."],["Chance","imkon, ehtimollik",0,"Is there any chance of me getting a pay rise?","Maoshimni oshirish imkoni bormi?"],["Company","kompaniya, korxona",0,"The company Frank works for makes sports equipment.","Frenk ishlaydigan kompaniya sport jihozlari ishlab chiqaradi."],["Difficulty","qiyinchilik",0,"You won't have any difficulty with the work. It's very simple.","Ish bilan hech qanday qiyinchilik bo'lmaydi. U juda oson."],["Driving licence","haydovchilik guvohnomasi",0,"The driving licence for a lorry is much harder to get than the one for a car.","Yuk mashinasi uchun haydovchilik guvohnomasi olish mashinanikidan ancha qiyinroq."],["Effort","urinish, sa'y-harakat",0,"If we make a real effort, we can get the work finished by Friday.","Agar rostmanasiga urinsak, ishni juma kunigacha tugata olamiz."],["Engineer","muhandis",0,"The engineer who designed that machine did a wonderful job.","Ushbu mashinani yaratgan muhandis ajoyib ish qilgan."],["Factory","fabrika, zavod",0,"Yuri works in the paint shop of a car factory.","Yuriy avtomobil zavodining bo'yoq sexida ishlaydi."],["Job","ish",0,"His father's first job was cooking in a café.","Uning otasining birinchi ishi kafeda taom pishirish bo'lgan."],["Journalist","jurnalist",0,"Roger works as a journalist for the local newspaper.","Ro'jer mahalliy gazetada jurnalist bo'lib ishlaydi."],["Manager","ish boshqaruvchi, menejer",0,"I asked the manager for a day off on Monday.","Men ish boshqaruvchidan dushanba kuni dam olishni so'radim."],["Mechanic","mashina ustasi, mexanik",0,"A mechanic is looking at my car at the moment.","Mexanik ayni damda mashinamga qarayapti."],["Meeting","uchrashuv; majlis",0,"The boss held a meeting in his office this morning, but I was late!","Boshliq bugun ertalab ofisida majlis o'tkazdi, biroq men kech qoldim!"],["Money","pul",0,"She makes very good money in her new job.","U yangi ishida juda yaxshi pul topadi."],["Newspaper","gazeta",0,"I read about the fire in the newspaper.","Men yong'in to'g'risida gazetada o'qidim."],["Occupation","bandlik; kasb",0,"A good occupation for a caring person is nurse.","G'amxo'r inson uchun yaxshi kasb bu hamshiralik."],["Office","ofis",0,"I work in an office and wear a suit and tie to work.","Men ofisda ishlayman va ishga kostyum- shim hamda bo'yinboq kiyaman."],["Police officer","politsiya ofitseri",0,"The police officer stopped the car and asked for the driving licence.","Politsiya ofitseri mashinani to'xtatdi va haydovchilik guvohnomasini so'radi."],["Staff","ischi xodimlar",0,"The restaurant staff are friendly and helpful.","Restoran xodimlari samimiy va foydali."],["Type","tur, xil",0,"What type of person are we looking for to fill the position?","Ish o'rnini to'ldirish uchun qanday turdagi odamni qidiryapmiz?"],["Work","ish",0,"Joe can't find work–do you know of a job he can do?","Jo' ish topolmayapti–u qila oladigan biror ish bilasizmi?"],["Accept","qabul qilmoq",1,"They offered me the job and I accepted–I start on Monday!","Ular menga ishni taklif qilishdi va men qabul qildim–dushanba kuni ish boshlayman!"],["Build","qurmoq",1,"Our company is building 100 new houses.","Bizning kompaniyamiz 100 ta yangi uylar qurmoqda."],["Call","qo'ng'iroq qilmoq",1,"Olive's not here yet–can you call her and see if she's all right?","Oliv hali bu yerda emas–unga qo'ng'iroq qilib, hammasi joyida ekanligini aniqlay olasizmi?"],["Carry","olib yurmoq, ko'tarib bormoq",1,"Can you carry some of these files? They're very heavy.","Mana bu fayllarning ba'zilarini ko'tarib bora olasizmi? Ular juda og'ir."],["Complete","yakunlamoq, bitirmoq",1,"When we complete the project, I can relax.","Loyihani bitirganimizda, men dam ola olaman."],["Create","yaratmoq",1,"My brother's job is to create websites for small companies.","Akamning ishi kichik kompaniyalar uchun vebsaytlar yaratishdir."],["Drive","avtomobil haydamoq",1,"Steven can drive a car and he's learning to drive a van now.","Stiven mashina hayday oladi va u hozir furgon haydashni o'rganmoqda."],["Earn","pul ishlab topmoq",1,"Do you earn more money in your new job than in the old one?","Yangi ishingizda eskisidan ko'ra ko'proq pul ishlab topasizmi?"],["Finish","tugatmoq",1,"We can leave when we finish the work.","Ishni tugatganimizda ketsak bo'ladi."],["Lift","ko'tarmoq",1,"Don't lift that heavy box or you'll hurt your back!","U og'ir qutini ko'tarmang, aks holda belingizni shikastlab olasiz!"],["Manage","boshqarmoq",1,"How does she manage a company and bring up three kids?","U qanday qilib kompaniya boshqaradi va uchta bolani voyaga yetkazadi?"],["Please","xursand qilmoq, mamnun qilmoq",1,"It pleases me to see your work is getting better.","Ishingiz yaxshilanib borayotganini ko'rish meni mamnun qiladi."],["Speak","gapirmoq",1,"Can you speak to Janine about her lateness, please?","Janin bilan uning kechikishi to'g'risida gaplashib qo'ya olasizmi, iltimos?"],["Start","boshlamoq",1,"The manager asked me if I could start the job on Monday!","Ish boshqaruvchi mendan ishni dushanba kuni boshlay olasizmi, deb so'radi!"],["Train","shug'ullantirmoq",1,"I have to train three new members of staff this week.","Bu hafta uch nafar yangi ishchi xodimni shug'ullantirishim kerak."],["Try","harakat qilmoq, urinmoq",1,"She's trying hard to get the work finished on time.","U ishni o'z vaqtida tugatish uchun qattiq urinyapti."],["Get back","qaytmoq",2,"Their dad gets back from work at 8 pm.","Ularning dadasi ishdan kechki soat 8 da qaytadi."],["Get up","uyqudan turmoq",2,"He works as a milkman, and gets up at 5 in the morning.","U sut tarqatuvchi bo'lib ishlaydi va tonggi soat 5 da uyqudan turadi."],["Tidy up","yig'ishtirmoq, tartibga solmoq, tozalamoq",2,"She can't find anything on her desk, so she's tidying it up.","U stolidan hech narsani topa olmayapti, shuning uchun uni tartibga solyapti."],["Wake up","uyg'onmoq",2,"He wakes up at 6 so he can catch the 7.30 train to work.","U ishga borish uchun 7.30 dagi poyezdga ulgurish uchun soat 6 da uyg'onadi."],["At work","ishda",3,"Don't call him at work–he's usually too busy to talk.","Ishdaligida unga qo'ng'iroq qilmang–u odatda gaplashish uchun o'ta band bo'ladi (= o'ta band bo'lganidan gaplasholmaydi)."],["Be able to do (something)","(biror narsa) qila olmoq, qilishga qodir bo'lmoq",3,"I'm afraid I won't be able to finish the work on time.","Ishni o'z vaqtida tugata olmayman deb qo'rqaman."],["By myself/yourself/himself/herself/itself/yourselves/ourselves/themselves","bir o'zi = yolg'iz, hech kimning yordamisiz",3,"Did you do the work by yourself or did you have help?","Ishni bir o'zingiz bajardingizmi yoki yordam oldingizmi?"],["Decide on (something)","(biror narsa) to'g'risida bir qarorga kelmoq, tanlamoq",3,"We need to decide on which chairs to buy.","Qaysi stullarni sotib olishni tanlashimiz kerak."],["Earn a living","kun kechirishi uchun yetarli pul ishlab topmoq",3,"Mike earns a living as a taxi driver.","Mayk taksi haydovchisi sifatida kun ko'radi."],["Earn money","pul ishlab topmoq",3,"Do you earn a lot of money in your job?","Siz ishingizda ko'p pul topasizmi?"],["Make a living","tirikchilik qilish uchun yetarli pul ishlab topmoq = earn a living",3,"I don't want a job that makes me rich. I just want to make a living.","Men boy-badavlat qilib yuboradigan ish xohlamayman. Men shunchaki tirikchilik qilish uchun yetarli pul ishlab topishni istayman."],["Make money","pul ishlab topmoq = earn money",3,"He chose that career because he wants to make money.","U o'sha karyerani tanladi chunki u pul topishni istaydi."],["On business","ish yuzasidan; ish safarida, komandirovkada",3,"Michelle isn't in this week–she's in Paris on business.","Mishel bu hafta ish joyida emas–u ish yuzasidan Parijda."],["On time","o'z vaqtida",3,"The manager told the staff to get to work on time in the morning.","Ish boshqaruvchi xodimlarga tongda o'z vaqtida ishga kelishni aytdi."],["Bored","zerikkan",4,"The students were bored with doing Maths problems on a warm summer day.","O'quvchilar issiq yoz kunida matematik misollar yechishdan zerikib ketishgandi."],["Boring","zerikarli",4,"When you do the same job for years, it gets boring.","Bir xil ishni yillab qilsangiz, u zerikarli bo'lib qoladi."],["Busy","band; serqatnov",4,"The high street is always busy on Saturdays, full of shoppers.","Markaziy ko'cha shanba kunlari har doim gavjum bo'ladi, xaridorlarga to'la."],["Daily","har kunlik",4,"Liam gets a daily wage of £60, but he doesn't work every day.","Liem kunlik 60 funt sterling miqdorida maosh oladi, lekin u har kuni ishlamaydi."],["Difficult","qiyin",4,"I'm so tired–I had a difficult day at work.","Men juda charchadim–ishda qiyin kun bo'ldi."],["Necessary","zarur, muhim",4,"It's necessary to get very high marks to get into medical school.","Tibbiyot oliygohiga kirish uchun yuqori baholar olish zarur."],["Wonderful","ajoyib",4,"Teaching is the most wonderful job in the world–I love it!","Dars berish dunyodagi eng ajoyib ish– men uni sevaman!"],["Alone","yolg'iz, bir o'zi",4,"I prefer to work alone as I don't like to depend on others.","Men yolg'iz ishlashni afzal ko'raman chunki boshqalarga suyanishni yoqtirmayman."],["Certainly","aniq, albatta",4,"Yes, Kelly is certainly in a good position to get the job.","Ha, Keli albatta ishni olish uchun yaxshi holatda."],["Daily","har kuni",4,"The shop doesn't add up its profits daily, but at the end of the week.","Do'kon o'z daromadini har kuni emas, balki hafta oxirida qo'shadi."],["Hard","qattiq, tirishib",4,"There were very few customers in the shop today, so we didn't have to work very hard.","Bugun do'konda juda kam sonli xaridor bo'ldi, shuning uchun qattiq ishlashimiz shart bo'lmadi."],["Able","qodir, qila olmoq",5,"Are you able to come on Saturday?","Shanba kuni kela olasizmi?"],["Unable","qodir emas, qo'lidan kelmaydigan",5,"After my illness, I was unable to get out of bed by myself.","Xastaligimdan keyin, men yotoqdan birovning yordamisiz turolmay qoldim."],["Ability","qobiliyat, salohiyat",5,"I don't think he has the ability to do the job, unfortunately.","Afsuski, u ishni bajarish uchun kerakli salohiyatga ega deb o'ylamayman."],["Arrange","avvaldan belgilab olmoq, tashkillashtirmoq",5,"Can I arrange an appointment for Monday?","Dushanba kuni uchun uchrashuv belgilatsam bo'ladimi?"],["Arrangement","tayyorgarlik, tashkiliy ishlar",5,"Can you make the arrangements for our trip to New York?","Nyu Yorkka sayohatimiz uchun tashkiliy ishlarni qila olasizmi?"],["Certain","aniq, amin, ishonchi komil",5,"Are you absolutely certain about this?","Bu haqida ishonchingiz komilmi?"],["Certainly","albatta, aniq",5,"Sergei will certainly help if you ask. He's a great worker.","Sergey albatta yordam beradi agar so'rasangiz. U ajoyib ishchi."],["Choose","tanlamoq",5,"The children chose milk over juice.","Bolalar sharbatni emas, sutni tanladilar."],["Choice","tanlov",5,"You can't do both jobs, so you need to make a choice.","Ikkala ishni bajara olmaysiz, shuning uchun tanlov qilishingiz kerak."],["Day","kun",5,"We spent five days in Paris.","Biz Parijda besh kun o'tkazdik."],["Daily","har kuni, kuniga",5,"Phil earns over £200 daily, but he doesn't work every day.","Fil kuniga 200 funt sterlingdan ziyod pul ishlab topadi, ammo u har kuni ishlamaydi."],["Decide","qaror qabul qilmoq",5,"Why did you decide to look for a new job?","Nima uchun yangi ish izlashga qaror qildingiz?"],["Decision","qaror",5,"It was a difficult decision to make, but I chose Sam.","U qarorni qabul qilish qiyin bo'ldi, lekin men Semni tanladim."],["Engine","mashina motori",5,"I got in the car and started the engine.","Men mashinaga o'tirdim va motorni o't oldirdim."],["Engineering","muhandislik (sohasi)",5,"She works in engineering–mostly factory machinery design.","U muhandislik sohasida ishlaydi– asosan fabrika mashinalarini loyihalash."],["Management","boshqaruv",5,"The management of the company is poor, so everything's badly organised.","Kompaniya boshqaruvi talabga javob bermaydi, shuning uchun hamma narsa yomon tashkillashtirilgan."],["Music","musiqa",5,"Could you turn that music down?","Musiqani pasaytira olasizmi?"],["Musician","musiqachi",5,"How many musicians are there in the orchestra?","Orkestrada nechta musiqachi bor?"],["Musical","musiqiy",5,"Can you play a musical instrument?","Biror musiqiy asbob chala olasizmi?"],["Suit","mos tushmoq, yarashmoq",5,"Blue suits you. You should wear it more often.","Ko'k rang sizga yarashadi. Siz uni ko'proq kiyishingiz kerak."],["Suit","kostyum-shim",5,"He was wearing a grey business suit.","U kulrang biznes kostyum-shimi kiyib olgandi."],["Suitable","mos, munosib",5,"We believe you are the suitable person for the job–do you want it?","Siz ish uchun munosib odam ekanligingizga ishonamiz–ishni xohlaysizmi?"],["Unsuitable","nomunosib",5,"He's unsuitable as a manager–he's much too young, for one thing.","U ish boshqaruvchi lavozimiga nomunosib–birinchidan, u o'ta yosh."]]},{"n":18,"t":"Shopping","c":[["Advert","reklama",0,"There was an advert for coffee on the side of the bus.","Avtobusning yon tomonida kofe reklamasi bor edi."],["Butcher's","go'sht do'koni",0,"Go to the butcher's and get me some sausages.","Go'sht do'koniga borib, menga ozgina sosiska olib keling."],["Cash","naqd pul",0,"They don't accept credit cards in that shop–only cash.","U do'konda plastik kartochkalar qabul qilishmaydi–faqatgina naqd pul."],["Changing room","kiyimni sotib olishdan avval uni kiyib ko'radigan xona, kiyim almashtirish xonasi",0,"Where are the changing rooms? I want to try on these trousers.","Kiyim almashtirish xonalari qayerda? Men mana bu shimni kiyib ko'rmoqchiman."],["Chemist's","dorixona",0,"When you're at the chemist's, will you get me some aspirin?","Dorixonada ekanligingizda menga ozgina aspirin ola olasizmi?"],["Credit card","plastik kartochka",0,"Can I pay by credit card here?","Bu yerda plastik kartochka orqali to'lasam bo'ladimi?"],["Customer","xaridor",0,"He's the shop's best customer. He comes in and buys something nearly every day.","U do'konning eng yaxshi xaridori. U deyarli har kuni kirib, biror narsa sotib oladi."],["Baker's","nonvoyxona, qandolat do'koni: non mahsulotlari, to'rt, bulochka, pishiriqlar tayyorlanadigan joy",0,"I went to the baker's to buy some bread.","Ozgina non sotib olish uchun nonvoyxonaga bordim."],["Bill","scho't, xizmat yoki iste'mol uchun to'lov",0,"Let me pay the bill for the meal this time.","Bu safar taom uchun to'lovni men to'lashimga ruxsat bering."],["Bookshop","kitob do'koni",0,"Alex went into the bookshop to buy a book.","Aleks kitob sotib olish uchun kitob do'koniga kirdi."],["Department store","univermag, savdo markazi: birgina katta do'kon ichida barcha turdagi mahsulotlar sotiladi",0,"You can buy nearly anything in a department store.","Univermagda deyarli istalgan narsani sotib ola olasiz."],["Gift","sovg'a",0,"Fred bought his dad a gift for his birthday.","Fred dadasiga tug'ilgan kuni uchun bir sovg'a sotib oldi."],["Greengrocer's","meva va sabzavotlar do'koni",0,"I bought some bananas and apples at the greengrocer's.","Men meva va sabzavotlar do'konida ozgina banan va olmalar sotib oldim."],["Online shopping","internetda xarid qilish",0,"Online shopping is much easier than going out to the shops.","Internetda xarid qilish do'konga borishdan ancha osonroq."],["Pocket money","cho'ntak puli: ota-onalar farzandiga ehtiyoj tug'ilganda biror yegulik, o'quv qurollari va hokazolar uchun sarflashi uchun beradi",0,"Do your parents give you pocket money every week?","Ota-onangiz sizga har hafta cho'ntak puli berishadimi?"],["Present","sovg'a = gift",0,"Yvonne bought her mother a lovely present for Mother's Day.","Ivo'n onasiga Onalar Kuni munosabati bilan ajoyib sovg'a sotib oldi."],["Price","narx",0,"All the shops bring their prices down after Christmas.","Hamma do'konlar Rojdestvodan so'ng narxlarni tushiradilar."],["Queue","navbat",0,"There was a long queue in the bank, so I went to do my shopping instead.","Bankda uzun navbat bor edi, shuning uchun uning o'rniga bozorligimni qilish uchun ketdim."],["Shop assistant","sotuvchi",0,"The shop assistant in the clothes shop asked Greg if he needed any help.","Kiyim do'konidagi sotuvchi Gregdan yordam kerakmi deb so'radi."],["Shopping centre/mall","savdo majmuasi: turli-tuman mahsulotlar sotishga mo'ljallangan ko'plab do'konlardan tashkil topgan bo'ladi",0,"They go to the shopping mall every weekend to shop and eat.","Ular har hafta oxirida xarid qilish hamda ovqatlanish uchun savdo majmuasiga borishadi."],["Street market","bozorcha",0,"Tourists love shopping in this street market in Istanbul.","Sayyohlar Istanbuldagi ushbu bozorchada xarid qilishni yoqtiradilar."],["Supermarket","supermarket",0,"He went to the supermarket with his mum to help with the shopping.","U xarid qilishda yordam berish uchun onasi bilan supermarketga bordi."],["Buy","sotib olmoq",1,"Jane went shopping but she didn't buy anything.","Jeyn xarid qilishga bordi, lekin hech narsa sotib olmadi."],["Change","o'zgartirmoq",1,"I want to change this top because it's too small for me.","Men mana bu ustki kiyimni almashtirishni istayman chunki u men uchun haddan tashqari kichik."],["Charge","haq olmoq, pul olmoq",1,"How much do they charge for a haircut here?","Bu yerda soch olish uchun necha pul olishadi?"],["Close","yopmoq, yopilmoq",1,"Do the shops close at 5 pm or 6 pm today?","Bugun do'konlar kechki soat 5 da yopiladimi yoki 6 dami?"],["Cost","narxda turmoq",1,"How much does a loaf of bread cost?","Bir buxanka non necha pul turadi?"],["Decide","qaror qabul qilmoq, bir qarorga kelmoq",1,"I can't decide which shirt to buy.","Qaysi ko'ylakni sotib olish haqida bir qarorga kelolmayapman."],["Open","ochmoq, ochilmoq",1,"What time do the shops open here in the morning?","Bu yerda do'konlar tongda soat nechada ochiladi?"],["Order","buyurtma bermoq",1,"Well, I know what I want to eat–are you ready to order?","Xo'sh, men nima yeyishni xohlayotganimni bilaman–sizchi, buyurtma berishga tayyormisiz?"],["Pay","to'lamoq",1,"Ruth's dad always pays for the meal when they go out.","Rusning dadasi ular aylanishga chiqqanda har doim ovqat uchun to'laydi."],["Return","qaytarmoq",1,"Henry returned the MP3 player because it stopped working.","Henri MP3 pleyerni qaytarib berdi chunki u ishlashdan to'xtabdi."],["Sell","sotmoq",1,"They sell great steaks 🥩 in that butcher's.","Anavi go'sht do'konida ajoyib lahm go'shtlar sotishadi."],["Spend","pul sarflamoq",1,"Julie spent all her pocket money on one top.","Juli hamma cho'ntak pulini bittagina ustki kiyimga sarfladi."],["Wrap","(asosan sovg'ani) o'ramoq, upakovka qilmoq",1,"Did you get paper to wrap the Christmas presents with?","Rojdestvo sovg'alarini o'rash uchun qog'oz oldingizmi?"],["Come/Go down","tushmoq, pasaymoq (narxlarga nisbatan)",2,"Wait for the prices to go down in the sales.","Chegirmada narxlar pasayishini kuting."],["Go up","ko'tarilmoq, o'smoq (narxlarga nisbatan)",2,"Prices always go up before Christmas.","Rojdestvodan avval narxlar har doim ko'tariladi."],["Make up your/her/etc mind","bir qarorga kelmoq",2,"I can't make up my mind–which shirt is better?","Men bir qarorga kelolmayapman–qaysi ko'ylak yaxshiroq?"],["Take back","sotib olgan narsani do'konga qaytarib olib bormoq",2,"That dress doesn't fit. You should take it back.","Bu ko'ylak mos tushmadi. Uni do'konga qaytarib olib borishingiz kerak."],["Take down","pastga olmoq",2,"He took the teddy bear 🧸 down from the shelf for his daughter.","U yumshoq ayiqchani qizi uchun tokchadan olib berdi."],["Wrap up","(asosan sovg'ani) o'ramoq, upakovka qilmoq",2,"Let's wrap up the presents and put them under the tree.","Keling sovg'alarni o'raymiz va daraxtning tagiga qo'yamiz."],["A couple of (things)","bir nechta (narsa)",3,"Can you get a couple of things for me at the supermarket?","Supermarketda men uchun bir nechta narsalar olib ola olasizmi?"],["Difference between (two things)","(ikki narsa) o'rtasidagi farq, tafovut",3,"There's no difference between those two shirts–buy either.","Bu ikki ko'ylak o'rtasida hech qanday farq yo'q–birini sotib oling."],["For sale","sotuvda",3,"The coat on the counter wasn't for sale–it was the shop assistant's.","Peshtaxtadagi palto sotuvda emasdi–u sotuvchiniki edi."],["Get a refund","to'lagan pulini qaytarib olmoq",3,"Bring the DVD player back and get a refund–it doesn't work.","DVR pleyerni qaytarib olib keling va to'lagan pulingizni qaytarib oling–u ishlamaydi."],["Go with (someone)","(biror kim) bilan birga bormoq",3,"Go with your father to the supermarket, Diane.","Dayan, dadangiz bilan supermarketga boring."],["In cash","naqd pul orqali",3,"Are you paying by credit card or in cash?","Plastik kartochka orqali to'laysizmi yoki naqd pul orqalimi?"],["It costs","uning narxi... (biror narsaning narxi/qiymatini aytishda foydalaniladi)",3,"It costs £15 to watch a film in that cinema.","U kinoteatrda film tomosha qilishning narxi 15 funt sterling."],["Go shopping","xarid uchun bormoq",3,"Do you go shopping in town every Saturday?","Shaharda xarid qilish uchun har shanba kuni borasizmi?"],["Made of (something)","(biror material)dan yasalgan, tayyorlangan, tikilgan, qurilgan",3,"What is this shirt made of–cotton or polyester?","Bu ko'ylak qanday materialdan tikilgan– paxtami yoki sintetik materialmi?"],["Pay for (something)","(biror narsa) uchun to'lamoq",3,"Pay for lunch today and I will tomorrow.","Tushlik uchun bugun siz to'lang, men esa ertaga to'layman."],["Brand-new","zamonaviy, yap-yangi",4,"She's got a brand-new mobile phone–it was her birthday last week.","U zamonaviy telefon oldi– o'tgan hafta uning tug'ilgan kuni edi."],["Cheap","arzon",4,"The clothes are so cheap–I bought all these for £10!","Bu kiyimlar rosa arzon–bularning barini 10 funt sterlingga sotib oldim!"],["Expensive","qimmat",4,"The clothes there are too expensive for her to buy.","U yerdagi kiyimlar u sotib olishi uchun haddan tashqari qimmat."],["Open-air","ochiq havoda joylashgan, tom ostida emas, tepasi o'ralmagan",4,"We visited an open-air market while we were in Thailand.","Biz Tailandda bo'lgan paytimizda ochiq havoda joylashgan bozorga tashrif buyurdik."],["Extremely","juda ham, nihoyatda",4,"Mark always takes an extremely long time to choose clothes.","Mark har doim kiyim tanlash uchun juda ham uzoq vaqt oladi."],["Fairly","anchagina",4,"The shoes were fairly expensive, but not too much.","Oyoq kiyimlar anchagina qimmat edi, lekin haddan tashqari qimmat emas."],["Quite","anchagina, juda ham",4,"It's quite cheap to eat in that restaurant, but the food's great.","U restoranda ovqatlanish anchagina arzon, lekin ovqati ajoyib."],["Assist","yordamlashmoq",5,"Your job will be to assist the production manager.","Sizning ishingiz ishlab chiqarish menejeriga yordamlashish bo'ladi."],["Assistant","yordamchi",5,"My mum works as an assistant to the manager.","Mening oyim ish boshqaruvchi yordamchisi bo'lib ishlaydi."],["Assistance","yordam",5,"Can I give you any assistance with choosing a suit, sir?","Kostyum-shim tanlashda biror yordam bera olamanmi, janob?"],["Centre","markaz",5,"We both work in the city centre.","Biz ikkovimiz ham shahar marzkazida ishlaymiz."],["Central","markaziy",5,"The shop does well because it's in a central part of the city.","Do'kon yaxshi ishlaydi (= savdo yaxshi) chunki u shaharning markaziy qismida joylashgan."],["Centrally","markaziy joyda",5,"Restaurants that are centrally located do better.","Markaziy joyda joylashgan restoranlar yaxshiroq ishlaydi (= xo'randalar soni va tushum yaxshi bo'ladi)."],["Closed","yopiq",5,"We got to the shop at 5.30 and it was closed.","Biz do'konga soat 5.30 da bordik va u yopiq edi."],["Differ","farq qilmoq, turlicha bo'lmoq",5,"The models differ in size and shape.","Modellar o'lchami va shakli jihatdan farq qiladi."],["Difference","farq, tafovut",5,"What's the difference between a grocer's and a greengrocer's?","Oziq-ovqat do'koni va meva- sabzavotlar do'koni o'rtasidagi farq nimada?"],["Different","boshqacha, farqli, har xil",5,"She's tired of wearing the same old clothes–she wants something different.","U bir xil eski kiyimlarni kiyaverishdan charchadi–u biror boshqacha narsa xohlayapti."],["Differently","turli tarzda, har xil, boshqacha",5,"The two sisters are dressed very differently, but their hair is the same.","Ikki opa-singil juda ham turli tarzda kiyinishgan, lekin ularning sochi bir xil."],["Extreme","keskin darajada jiddiy, o'ta kuchli",5,"The heat in the desert was extreme.","Sahrodagi issiqlik o'ta kuchli edi."],["Feel","his qilmoq",5,"I felt like a complete idiot.","Men o'zimni butunlay ahmoqdek his qildim."],["Feeling","hissiyot, tuyg'u",5,"Finding exactly the right dress for the party was a great feeling.","Bazm uchun aynan kerakli ko'ylakni topish juda ajoyib tuyg'u edi."],["Perfect","mukammal, ajoyib, eng mos",5,"Hawaii is the perfect place for a honeymoon.","Havayi (= o'zbeklar Gavayi deyishadi, ammo inglizchada bu so'zning to'g'ri talaffuzi Havayi bo'ladi) asaloyi uchun ajoyib joy."],["Perfectly","mutlaqo, butunlay",5,"That shirt fits you perfectly–you have to buy it!","U ko'ylak sizga mutlaqo mos tushdi–uni sotib olishingiz lozim!"],["Sale","savdo, sotish",5,"We made three sales in the car showroom today.","Bugun mashina ko'rgazmasida uchta sotuvni amalga oshirdik (= uchta mashina sotdik)."],["Seller","sotuvchi",5,"The seller is not allowed to lie to the buyer.","Sotuvchi xaridorga yolg'on gapirishiga ruxsat berilmaydi (= taqiqlangan)."],["Shop","xarid qilmoq",5,"I shop for clothes every season.","Men har faslda kiyim xarid qilaman."],["Shop","do'kon",5,"She opened a flower shop in the High Street.","U Hay Stritda (= Markaziy Ko'chada) gul do'koni ochdi."],["Shopper","xaridor",5,"The mall is full of shoppers on Saturdays.","Savdo markazi shanba kunlari xaridorlarga to'la."],["Shopping","xarid qilish",5,"I hate shopping with my mum because she takes me to about fifty different shops.","Men oyim bilan xarid qilishni yomon ko'raman chunki ular meni taxminan ellikta har xil do'konga olib boradilar."]]},{"n":21,"t":"Customs And Traditions","c":[["Cardboard","karton",0,"The boy's mother cut him a mask out of cardboard.","Yigitchaning onasi unga kartondan niqob kesib berdi."],["Circus","sirk",0,"My favourite act in the circus are the clowns.","Sirkdagi mening sevimli sahna ko'rinishim bu masxarabozlardir."],["Costume","libos, ust-bosh, kiyim",0,"What costume will you dress up in at Halloween?","Halevin bayramida qanday libosda kiyinasiz (= qaysi film yoki mult qahramoniga o'xshab kiyinasiz)?"],["Decoration","bezak, dekoratsiya",0,"There were balloons hanging everywhere as decoration.","Bezak sifatida hamma yerda sharlar osilib turgan edi."],["Fair","yarmarka; karnaval, istirohat bog'i, park",0,"Her favourite ride at the fair is the carousel 🎠 .","Uning yarmarkadagi sevimli atraksioni bu karuseldir."],["Festival","bayram, tantana, shodiyona",0,"They have a spring festival here every year.","Bu yerda har yili bahoriy shodiyona qilishadi."],["Fun","xursandchilik, vaqtichog'lik, ko'ngilxushlik",0,"We had a lot of fun at the fair–it was great!","Yarmarkada rosa vaqtichog'lik qildik–ajoyib bo'ldi!"],["Habit","odat",0,"It's Grandad's habit to take a walk every morning.","Har tongda piyoda sayr qilish bu bobomning odati."],["Mood","kayfiyat",0,"Why are you in a bad mood? Did something go wrong?","Nima uchun yomon kayfiyatdasiz? Nimadir xato ketdimi (= o'xshamadimi)?"],["Noise","shovqin",0,"The children are making a lot of noise. Tell them to be quiet.","Bolalar rosa shovqin qilishyapti. Jim bo'lishni ayting ularga."],["Organiser","tashkillashtiruvchi",0,"The mayor is a good organiser, so the carnival went perfectly.","Shahar hokimi yaxshi ish tashkillashtiruvchi, shunday ekan karnival a'lo darajada o'tdi."],["Parade","parad, nishonlash",0,"We watched the dancers in the parade go by.","Biz paraddagi raqqoslarni o'tib ketishini kuzatdik."],["Reason","sabab",0,"The reason for the festival is to welcome the return of spring.","Shodiyonaning sababi bu bahorning qaytishini iliq kutib olishdir."],["Scream","qichqiriq",0,"The screams of the fans got louder and louder.","Muxlislarning qichqiriqlari tobora balandlashib bordi."],["Show","ko'rsatuv, shou, tomosha",0,"Let's go in and sit down because the show's about to start.","Keling ichkariga kirib o'tiramiz, chunki tomosha boshlanish arafasida (= hademay boshlanadi)."],["Speech","nutq",0,"The mayor made a speech to the people of the town.","Shahar hokimi shahar ahliga nutq so'zladi."],["Sword","qilich",0,"That sword was carried by a king in the past.","U qilich o'tmishda bir qirol tomonidan olib yurilgan."],["Town hall","shahar hokimiyati binosi",0,"The mayor's office is in the town hall.","Merning ofisi shahar hokimiyati binosida."],["Treasure","xazina",0,"The two boys were looking for pirates' treasure on the beach.","Ikki yigitcha plyajda qaroqchilar xazinasini izlayotgan edi."],["Voice","ovoz",0,"He was shouting so much that he lost his voice.","U shu qadar ko'p baqirayotgan ediki, natijada ovozini yo'qotdi."],["Amaze","lol qoldirmoq, hayratga solmoq",1,"That magician's tricks always amaze me.","O'sha fokuschining fokuslari doim meni hayratga soladi."],["Burst","yorilmoq",1,"The balloon burst and made a loud bang.","Shar yorildi va baland bang'illagan tovush chiqardi."],["Continue","davom etmoq",1,"The parade goes through the square and continues up the hill.","Parad maydon bo'ylab o'tadi va tepalikka qarab davom etadi."],["Guess","taxmin qilmoq",1,"Can you guess where we're going on holiday this year?","Bu yil ta'tilda qayerga borayotganligimizni taxmin qila olasizmi?"],["Invite","taklif qilmoq",1,"If Laura invites you to her party, will you go?","Agar Lo'ra sizni o'z bazmiga taklif qilsa, borasizmi?"],["Joke","hazillashmoq",1,"My dad jokes about his weight, but he's worried really.","Dadam vazni to'g'risida hazillashadi, lekin u rostdan ham tashvishlanadi."],["Judge","g'olibni aniqlab bermoq, hakamlik qilmoq",1,"Who is judging the best costume?","Eng yaxshi libosni kim aniqlab beryapti?"],["Organise","tashkillashtirmoq",1,"Do you know a good company that organises children's parties?","Bolalar bazmini tashkillashtiradigan yaxshi bir korxonani bilasizmi?"],["Prepare","tayyorlamoq",1,"It took two hours to prepare all the food for fifty guests.","Ellikta mehmon uchun hamma ovqatni tayyorlashga ikki soat vaqt ketdi."],["Pretend","mug'ombirlik qilib o'zini biror ko'yga solmoq,...dek tutmoq",1,"The footballer pretended to be hurt, but he was fine.","Futbolchi o'zini jarohatlangandek tutdi, lekin ahvoli joyida edi."],["Report","ma'lum qilmoq, xabar bermoq",1,"The newspaper reported the discovery of a 1000-year-old sword.","Gazeta 1000 yillik qilich topilgani haqida xabar berdi."],["Return","qaytmoq",1,"We leave for France on the 8th and return on the 17th.","Biz Fransiyaga 8-da jo'naymiz va 17-da qaytib kelamiz."],["Scream","qichqirmoq",1,"The children screamed with excitement when they saw the elephants.","Fillarni ko'rishganida, bolalar quvonchdan qichqirishdi."],["Smile","jilmaymoq, tabassum qilmoq",1,"The clowns always make me smile.","Masxarabozlar doim meni tabassum qilishga majbur qiladi."],["Spray","sepmoq, purkamoq",1,"The gardener sprayed his plants with water.","Bog'bon o'simliklariga suv sepdi."],["Go on","davom etmoq = continue",2,"The festival goes on for three days.","Bayram uch kun davom etadi."],["Put up","tepaga osmoq, ilmoq, yuqoriga o'rnatmoq = hang, mount",2,"The organisers put decorations up everywhere.","Tashkillashtiruvchilar hamma yerga bezaklar osib tashlashdi."],["Run after (someone/something)","(biror kim/narsa) ortidan yugurmoq, quvmoq",2,"They run after the horses shouting and screaming.","Ular baqirib va qichqirib otlarni quvishadi."],["As soon as","...bo'lishi bilanoq",3,"As soon as we get home, I'm calling your father!","Uyga yetib borishimiz bilanoq, dadangizga qo'ng'iroq qilaman!"],["Fancy dress costume/party","chiroyli va bashang libos/antiqa kiyimlar kiyib boriladigan bazm",3,"Who are you dressing up as for the fancy dress party?","Antiqa kiyimlar kiyib boriladigan bazm uchun kim (= qaysi film yoki mult qahramoni)ga o'xshab kiyinasiz?"],["Fight against (something)","(biror narsa)ga qarshi kurashmoq",3,"My grandfather fought against the Fascists in Spain.","Mening bobom Ispaniyada fashistlarga qarshi kurashgan."],["Have a party","bazm o'tkazmoq",3,"I always have a party for my birthday.","Men har doim tug'ilgan kunim uchun bazm o'tkazaman."],["Invite someone to something","biror kimni biror yerga taklif qilmoq",3,"My cousin invited me to his summer house this weekend.","Amakivachcham meni shu hafta oxirida (dam olish uchun) o'z dala hovlisiga taklif qildi."],["A kind of (something)","(biror narsaning) xili, turi, navi",3,"A pavlova is a kind of dessert.","Pavlova shirinlikning bir turi."],["Laugh at (someone/something)","(biror kim/narsaning) ustidan kulmoq",3,"We laughed at the clowns at the circus.","Biz sirkda masxarabozlarning ustidan kuldik."],["Look forward to (something)","(biror narsa)ni intiqib kutmoq",3,"I'm looking forward to the parade next week–it'll be great!","Keyingi haftadagi paradni intiqib kutyapman–ajoyib bo'ladi!"],["Of course","albatta",3,"Of course I'm coming to the party. I wouldn't miss it!","Albatta men bazmga boraman. Uni o'tkazib yubormagan bo'lardim!"],["Take photo(graph)s","rasm olmoq",3,"She took some lovely photos of the dancers for the newspaper.","U raqqoslarni gazeta uchun chiroyli qilib rasmga oldi."],["Take place","sodir bo'lmoq, bo'lib o'tmoq",3,"The festival takes place on the last weekend in November.","Tantana Noyabr oyining eng so'nggi dam olish kunida bo'lib o'tadi."],["Walk past","yonidan yurib o'tib ketmoq",3,"A man just walked past me dressed as a monkey!","Maymunga o'xshab kiyingan bir erkak hozirgina yonimdan yurib o'tib ketdi!"],["Common","odatiy, ko'p uchraydigan, keng tarqalgan",4,"It's very common for American boys to dress up as cowboys.","Amerikalik o'g'il bolalar uchun kovboylar kabi kiyinish juda keng tarqalgan."],["Crowded","gavjum, tiqilinch",4,"It was so crowded on the bus that we couldn't get on.","Avtobus shu qadar tiqilinch ediki, biz unga chiqa olmadik."],["Curious","qiziqqan, bilishni xohlaydigan",4,"I'm curious to see who wins the prize.","Kim yutuqni yutib olishini ko'rishga qiziqib ketyapman."],["Strange","g'alati",4,"It was such a strange show that I couldn't understand it.","U shunaqangi g'alati tomosha ediki, men uni tushunmadim."],["Traditional","an'anaviy",4,"It's a traditional festival that first took place 500 years ago.","U ilk bor 500 yil avval bo'lib o'tgan an'anaviy bayram."],["Whole","butun",4,"The whole town takes part in the parade–men, women and children.","Butun shahar paradda ishtirok etadi–erkaklar, ayollar va bolalar."],["Backwards","orqaga qarab",4,"He fell over backwards and bumped the back of his head.","U orqaga qarab yiqilib tushdi va boshini orqa tomonini urib oldi."],["Especially","ayniqsa",4,"She loves all parties, but especially fancy dress parties.","Unga barcha bazmlar yoqadi, lekin ayniqsa antiqa kiyimlar kiyib boriladigan bazmlar."],["Forwards","oldinga qarab",4,"The parade stopped and then moved forwards again.","Parad to'xtadi, keyin esa yana oldinga qarab harakatlandi."],["Indeed","haqiqatdan ham",4,"Their mother promised to take them fishing and indeed she did.","Ularning onasi ularni baliq oviga olib borishga va'da berdi va haqiqatdan ham bu ishni qildi."],["Amazement","hayrat",5,"We looked at the sight with amazement–we couldn't believe it.","Biz manzaraga hayrat bilan qaradik–unga ishonolmasdik."],["Amazing","ajoyib, hayratga soladigan",5,"What an amazing show!","Naqadar ajoyib tomosha!"],["Amazingly","ajablanarlisi shuki, hayratga soladigan jihati shuki",5,"Amazingly, no one got hurt when the lions escaped.","Ajablanarli jihati shundaki, sherlar qochib ketganda hech kim shikastlanmadi."],["Attend","e'tibor qaratmoq, diqqatini qaratmoq",5,"She hadn't been attending during the lesson.","Dars davomida u diqqatini qaratmayotgandi."],["Attention","e'tibor, diqqat",5,"Please pay attention to the rules that I'm telling you.","Iltimos, sizga aytayotgan qoidalarimga e'tiboringizni qarating."],["Crowd","olomon",5,"If you want to avoid the crowds, get there early.","Agar olomonni oldini olishni istasangiz, u yerga erta yetib boring."],["Decorate","bezatmoq",5,"They decorated the room with flowers and balloons.","Ular xonani gullar va sharlar bilan bezatishdi."],["Direct","to'g'ridan-to'g'ri, bevosita",5,"There's a direct train to Leeds.","Lidzga to'g'ridan-to'g'ri olib boradigan poyezd bor."],["Direct","yo'nalish ko'rsatmoq, qanday borish kerakligini aytmoq",5,"Could you direct me to the station?","Menga vokzalga yo'lni ko'rsatib yubora olasizmi?"],["Direction","yo'nalish",5,"What direction is the food tent in?","Oziq-ovqat chodiri qaysi yo'nalishda?"],["Directly","to'g'ridan-to'g'ri",5,"I went directly home after the show because I was tired.","Tomoshadan keyin men to'g'ri uyga ketdim chunki charchagandim."],["Frighten","qo'rqitmoq",5,"Spiders frighten him to death.","O'rgimchaklar uni o'lgudek qo'rqitadi."],["Frightened","qo'rqib ketgan",5,"The children were frightened by the strange people.","Bolalar notanish odamlardan qo'rqib ketishgandi."],["Frightening","qo'rqinchli",5,"Grandpa told us a frightening story about ghosts.","Bobom bizga arvohlar to'g'risida bir qo'rqinchli hikoya aytib berdilar."],["Fun","maroqli, qiziqarli",5,"This game looks fun!","Bu o'yin maroqli ko'rinadi (= ko'rinishidan maroqliga o'xshaydi)!"],["Funny","kulguli",5,"The joke was so funny that I couldn't stop laughing.","Hazil shu qadar kulguli ediki men kulishdan to'xtay olmadim."],["Laugh","kulmoq",5,"When I heard her excuse, I just laughed.","Uning bahonasini eshitganimda, men shunchaki kulib yubordim."],["Laugh","kulgu",5,"'It was pretty crazy,' she said with a laugh.","\"Bu judayam ahmoqona ish bo'ldi,\" dedi u kulgu bilan."],["Laughter","kulish (ovozi)",5,"The laughter of the kids told me they were having a great time.","Bolalarning kulayotgan ovozi ular vaqtni ajoyib o'tkazayotganini bildirdi."],["Luck","omad",5,"We wish her luck in her new career.","Uning yangi ish faoliyatida omad tilaymiz."],["Lucky","omadli",5,"One lucky woman won £300.","Bir omadli ayol 300 funt sterling yutib oldi."],["Unlucky","omadsiz",5,"You were very unlucky to break your leg.","Oyog'ingizni sindirib olganingiz omadsiz ish bo'libdi."],["Luckily","yaxshiyamki, xayriyat, baxtimga",5,"Luckily, someone found my bag and gave it to a policeman.","Baxtimga, kimdir mening sumkamni topib olib, politsiya ofitseriga beribdi."],["Noisy","shovqinli",5,"Don't be so noisy while I'm trying to sleep.","Men uxlashga urinayotgan paytimda unaqa shovqinli bo'lmang (= shovqin-suron qilmang)."],["Noisily","shovqinli tarzda, shovqin chiqarib",5,"Someone in the cinema was eating crisps noisily.","Kinoteatrda kimdir shovqin chiqarib chips yeyib o'tirdi."],["Organiser","tashkillashtiruvchi, tashkilotchi",5,"The organisers of the festival did a great job.","Festivalni tashkillashtiruvchilar ajoyib ish qilishibdi."],["Organisation","tashkillashtirish, uyushtirish, tashkiliy ishlar",5,"The organisation of the parade was terrible and nobody knew where to go.","Paradni tashkillashtirilishi rasvo bo'lgan va hech kim qayerga yurishni bilmadi."],["Prepare","tayyorla(n)moq",5,"The whole class is working hard preparing for the exams.","Butun sinf imtihonlarga tayyorlanib qattiq harakat qilishyapti."],["Preparation","tayyorgarlik",5,"We finished the preparations for the party just before the kids arrived.","Biz bazmga tayyorgarliklarni bolalar yetib kelishidan shundoqqina avval tugatdik."],["Report","hisobot, axborot",5,"According to this evening's weather report, there will be snow tomorrow.","Bugun oqshomgi ob- havo axborotiga ko'ra, ertaga qor yog'adi."],["Reporter","reportyor, muxbir",5,"He works as a reporter for the town newspaper.","U shahar gazetasida muxbir bo'lib ishlaydi."],["Tradition","urf-odat, an'ana",5,"By tradition, children play tricks on 1 April.","An'anaga ko'ra, bolalar 1-aprelda xiyla-nayranglar qilishadi."],["Traditionally","azaldan, qadimdan, urf-odatga ko'ra",5,"Traditionally, the women dress in white and enter the village singing songs.","Urf-odatga ko'ra, ayollar oppoq kiyinib olishadi va qishloqqa qo'shiq kuylagan holda kirishadi."]]},{"n":24,"t":"Fashion","c":[["Accessory/Accessories","aksessuar, qo'shimcha qism: kiyimingizga mos tushadigan biror narsa, masalan kamar yoki sumka",0,"The shop sells accessories like belts and bags.","Bu do'kon kamar va sumka kabi aksessuarlar sotadi."],["Anorak","yomg'irli sovuq havoda kiyiladigan kapyushonkali kurtka",0,"I need to buy an anorak–it's going to be a rainy winter.","Men kurtka sotib olishim kerak–bu qish yomg'irli qish bo'ladi."],["Belt","kamar",0,"You need to buy a brown belt to go with those brown trousers.","Bu jigarrang shimga mos tushadigan jigarrang kamar sotib olishingiz kerak."],["Boot","etik",0,"She was wearing a pair of leather boots that came up to her knees.","U tizzalarigacha chiqqan bir juft charm etik kiyib olgandi."],["Button","tugma",0,"One of the buttons came off the front of my shirt.","Ko'ylagimning old qismidagi tugmalardan biri chiqib ketdi."],["Cardigan","kofta, kardigan: to'qilgan, odatda yoqasiz kiyim turi",0,"My granddad was wearing a woolly cardigan buttoned all the way up.","Bobom tugmalari yuqorigacha taqilgan yungli kardigan kiyib olgandilar."],["Clothes","kiyimlar",0,"He's got so many clothes that they don't fit in his wardrobe.","Uning shunchalar ko'p kiyimlari borki, ular kiyim shkafiga sig'maydi."],["Dress","ayollar ko'ylagi, libos",0,"Kate is wearing a long flowery summer dress.","Keyt uzun, gulli yozgi ko'ylak kiyib olgan."],["Fashion (show)","moda (shousi)",0,"She loves fashion and spends all her money on clothes.","U modani sevadi va hamma pulini kiyimlarga sarflaydi."],["Handbag","ayollar sumkasi",0,"She was carrying a small black leather handbag under her arm.","U qo'lining ostida kichik bir qora rangdagi charm sumka ko'tarib olgandi."],["Jacket","kurtka, pidjak",0,"The trousers of the suit fit you, but the jacket's too small.","Kostyum-shimning shimi sizga mos tushdi, ammo pidjak haddan tashqari kichik."],["Jewellery","taqinchoqlar",0,"The shop sells jewellery like necklaces and rings.","Bu do'kon marjon va uzuk kabi taqinchoqlar sotadi."],["Make-up","makiyaj, pardoz-andoz, oro (berish)",0,"My mum doesn't put on much make-up–just lipstick.","Oyim ko'p pardoz-andoz qilmaydilar– faqatgina pomada suradilar."],["Perfume","atir",0,"Your perfume smells beautiful–what's it called?","Atiringiz chiroyli hid taratarkan–u qanday ataladi (= uning nomi nima)?"],["Shampoo","shampun",0,"Your hair's so shiny! What shampoo do you use?","Sochingiz juda yorqin ekan! Qanday shampundan foydalanasiz?"],["Shirt","erkaklar ko'ylagi",0,"Why don't you buy a brown tie to wear with that yellow shirt?","1) U sariq ko'ylak bilan kiyish uchun bitta jigarrang bo'yinboq sotib olishingiz kerak. 2) Nima uchun u sariq ko'ylak bilan kiyish uchun bitta jigarrang bo'yinboq sotib olmaysiz?"],["Shoe","oyoq kiyim: tufli, botinka",0,"I have to take off these shoes because they're hurting my feet.","Bu oyoq kiyimlarni yechishga majburman chunki ular oyoqlarimni og'rityapti."],["Size","o'lcham",0,"What size shoes do you take–ten?","Qanday o'lchamdagi oyoq kiyim olasiz–o'nmi?"],["(Skinny) jeans","(tanaga yopishib turadigan tor, tarang) jinsi",0,"He was wearing a pair of skinny jeans in black denim.","U qora denimdan tikilgan bir juft tor jinsi kiyib olgandi."],["Skirt","ayollar yubkasi",0,"What top are you thinking of wearing with that skirt?","U yubka bilan qanday ustki kiyim kiyishni o'ylayapsiz?"],["Style","stil, did, estetika, elegantlik",0,"She says I've got no style, but I think her clothes look bad.","Uning aytishicha mening hech qanday didim yo'q emish, lekin menimcha uning kiyimlari rasvo ko'rinadi."],["Suit","kostyum-shim",0,"My brother has to wear a suit and tie to work every day.","Akam har kuni ishga kostyum-shim va bo'yinboq kiyishi shart."],["Sweatshirt","sviter, tolstovka, fufayka",0,"Put a sweatshirt on after your run so you don't get cold.","Sovuqqotmaslik uchun, yugurishdan so'ng tolstovka kiyib oling."],["Tie","bo'yinboq, galstuk",0,"Many companies ask men to wear a shirt and tie to work.","Ko'plab kompaniyalar erkaklardan ishga ko'ylak va bo'yinboq kiyishini so'raydi."],["Trainers","(bir juft) krossovka",0,"He wears basketball trainers on and off the court.","U maydonda ham, maydondan tashqarida ham basketbol krossovkalari kiyadi."],["Trend","urf, ommalashuv",0,"Spiky hair is the trend in hair styles these days.","Uchli soch turmagi hozirgi kunlarda ommalashgan (= urfda)."],["Trousers","shim",0,"The trousers of this suit fit well and are the right length.","Bu kostyumning shimi yaxshi mos tushdi va kerakli uzunlikda ekan."],["T-shirt","futbolka",0,"Most teenagers wear jeans and T-shirts.","Ko'pchilik o'smirlar jinsi va futbolkalar kiyadi."],["Borrow","vaqtinchalik olib turmoq",1,"Can I borrow your suit? I have to go to a wedding.","Sizni kostyum-shimingizni vaqtinchalik olib tursam bo'ladimi? To'yga borishim zarur."],["Dress","kiyinmoq",1,"Can your children dress on their own yet?","Farzandlaringiz hech kimni yordamisiz o'zlari kiyina olishadimi?"],["Fasten","mahkamlanmoq, yopilmoq (kiyimga nisbatan)",1,"The dress fastens with buttons all the way up the side.","Ko'ylak yon tomondan yuqoriga tugmalar bilan mahkamlanadi."],["Fit","o'lchami mos tushmoq",1,"Those shoes don't fit you–they're too big.","Bu oyoq kiyimlar sizga mos tushmadi–ular haddan tashqari katta."],["Fold","taxlamoq, buklamoq",1,"If you fold your clothes, they won't need ironing all the time.","Agar kiyimlaringizni taxlasangiz, ular har doim dazmollanishi zarur bo'lmaydi."],["Follow","kuzatmoq, amal qilmoq",1,"Carl follows all the latest fashions.","Karl barcha oxirgi modalarni kuzatib boradi."],["Match","mos tushmoq",1,"I bought you a blue tie to match your eyes.","Sizni ko'zlaringizga mos tushadigan bir moviy rangli bo'yinboq sotib oldim siz uchun."],["Measure","o'lchamoq",1,"They measured my feet at the shoe shop and they were two sizes bigger!","Oyoq kiyim do'konida meni oyog'imni o'lchashdi va oyog'im ikki o'lcham kattaroq bo'lib chiqdi (oyoq kiyimdan)!"],["Suit","yarashmoq",1,"That scarf really suits you–the colour goes with your eyes.","U sharf sizga juda yarashdi–rangi ko'zlaringizga mos tushar ekan."],["Tie","(oyoq kiyim ipini) bog'lamoq",1,"My little brother is three, so he can't tie his shoes.","Mening ukam uch yoshda, shunday ekan u oyoq kiyimining ipini bog'lay olmaydi."],["Undo","yechmoq, bo'shatmoq",1,"It was hot, so I undid the top button on my shirt.","Havo issiq edi, shuning uchun men ko'ylagimning yuqori tugmasini bo'shatdim."],["Wear","kiymoq",1,"In this photo, I'm wearing a fancy dress costume.","Bu rasmda, men chiroyli libos kiyganman."],["Do up","tugmasini taqmoq",2,"Do up your coat to the top–it's cold out.","Paltoyingizni yuqori qismigacha tugmasini taqing– tashqari sovuq."],["Dress up (in)","(ma'lum bir uslubda, stilda) kiyinmoq",2,"Weddings are a chance to dress up in smart clothes.","To'ylar bejirim kiyimlar kiyish uchun imkoniyatdir."],["Go with","biror kiyim boshqa bir kiyimga yarashmoq = match",2,"No, blue shoes do not go with green socks.","Yo'q, ko'k rangdagi oyoq kiyimlar yashil rangdagi paypoqlar bilan yarashmaydi."],["Hang up","ilmoq, osib qo'ymoq",2,"Don't leave your shirt on the floor–hang it up.","Ko'ylagingizni polga tashlab ketmang–uni ilib qo'ying."],["Put on","kiymoq",2,"I put on my pyjamas and went to bed.","Men pijamamni kiydim va uyquga yotdim."],["Put on","tashkillashtirmoq (masalan, shou)",2,"The designer put on a very successful fashion show.","Dizayner juda bir muvaffaqiyatli moda tomoshasini tashkillashtirdi."],["Take off","yechmoq",2,"He took off his pyjamas and got dressed for school.","U pijamasini yechdi va maktabga borish uchun kiyindi."],["Try on","kiyib ko'rmoq: kiyim yarashgan yoki yarashmaganligini ko'rish uchun",2,"Do you have a changing room where I can try on this shirt?","Bu ko'ylakni kiyib ko'rishim mumkin bo'lgan kiyim almashtirish xonasi bormi?"],["Zip up","kiyim zamogini taqmoq",2,"Zip up your jacket–it's very cold outside.","Kurtkangizning zamogini taqing–tashqari juda sovuq."],["As well as","nafaqat..., balki...; dan tashqari",3,"As well as coats, this shop has some nice handbags.","Paltolardan tashqari, bu do'konda chiroyli sumkalar ham bor."],["Gain weight","vazn orttirmoq",3,"I gained weight and now I can't zip up these jeans.","Men vazn orttirdim, endi esa mana bu jinsi shimni zamogini taqolmayapman."],["Get dressed","kiyinmoq",3,"Go and get dressed for school, kids.","Boringlar, maktabga kiyininglar, bolalar."],["Have a/the feeling (that)","(ni) sezmoq, ko'ngli sezmoq, tuyulmoq",3,"I have a feeling that something great will happen today.","Bugun ajoyib bir narsa ro'y berishini ko'nglim sezyapti."],["In front of","ning to'g'risida, oldida, qarshisida",3,"Joan stood in front of the shop window, looking at the jacket.","Jo'un do'kon derazasi oldida kurtkaga qarab turgandi."],["Keep fit","sog'lom, tetik va baquvvat holatini saqlamoq, jismoniy formasini yo'qotmaslik",3,"He goes running three times a week to keep fit.","U jismoniy formasini yo'qotmaslik uchun bir haftada uch marta yugurishga chiqadi."],["Put on make-up","makiyaj qilmoq, o'ziga oro bermoq, bo'yanmoq",3,"She put on her make-up in front of the mirror.","U ko'zguning qarshisida o'ziga oro berdi."],["The same as","bilan bir xil",3,"Your dress is exactly the same as mine.","Ko'ylagingiz meniki bilan quyib-qo'ygandek bir xil ekan."],["Casual","odatiy",4,"You don't have to wear a suit–just casual clothes.","Kostyum-shim kiyishingiz shart emas– shunchaki odatiy kiyimlaringizni kiying."],["Check(ed)","katak-katakli",4,"Do you prefer this checked shirt to the striped one?","Yo'l-yo'l chiziqlisidan ko'ra katak-katakli ko'ylakni afzal ko'rasizmi?"],["Cotton","paxtadan tikilgan",4,"I prefer cotton socks because they're cooler than woolen ones.","Men paxtadan tikilgan paypoqlarni afzal ko'raman chunki ular junli paypoqlardan sovuqroq."],["Denim","denimdan tikilgan, jinsi materialli",4,"Her blue denim jacket exactly matched her jeans.","Uning ko'k rangli jinsi kurtkasi jinsi shimiga quyib-qo'ygandek mos tushdi."],["Dyed","bo'yalgan, rang berilgan",4,"I have a dyed green T-shirt and I wear it to environmental events.","Mening yashil rangda bo'yalgan futbolkam bor va men uni ekologik tadbirlarga kiyaman."],["(Extra) large","katta o'lchamdagi",4,"My son's so big now that he wears tops that are extra large.","O'g'lim hozir shunchalik kattaki, u katta o'lchamdagi ustki kiyimlar kiyadi."],["Leather","teri, charm, ruscha: ko'jenniy material",4,"Are those boots made of real leather or plastic?","Anavi etik haqiqiy charmdan tikilganmi yoki plastik materialdanmi?"],["Medium","o'rtacha o'lchamli",4,"Do you wear a medium shirt or a large one usually?","Siz odatda o'rtacha o'lchamli ko'ylak kiyasizmi yoki katta o'lchamlisinimi?"],["Modern","zamonaviy",4,"That shop sells really modern clothes–nothing old-fashioned.","U do'kon juda zamonaviy kiyimlar sotadi–urfdan qolgan narsa yo'q."],["Old-fashioned","eskicha, urfdan qolgan",4,"Those trousers are so old-fashioned. My granddad has a pair!","Bu shim juda urfdan qolib ketgan. Bobomda bir juft (shunday shim) bor!"],["Plain","oddiy, ortiqcha rasm yoki chiziqlarsiz",4,"He wears a plain white T-shirt and blue jeans every day.","U har kuni oddiy oq futbolka va ko'k jinsi shim kiyadi."],["Shiny","yaltiroq",4,"Her leather handbag is so shiny that I can see my face in it!","Uning charm sumkasi shu qadar yaltiroqki, men unda o'z yuzimni ko'ra olaman!"],["Smart","bejirim, bashang, elegant",4,"You look very smart in that suit, Gerry!","Bu kostyum-shimda juda bejirim ko'rinarkansiz, Jeri!"],["Spotted","nuqta-nuqtali",4,"You can't wear a spotted tie with a striped shirt!","Yo'l-yo'l chiziqli ko'ylak bilan nuqta-nuqtali bo'yinboq taqib bo'lmaydi!"],["Striped","yo'l-yo'l chiziqli",4,"His team wears a red and white striped shirt and white shorts.","Uning jamoasi qizil va oq chiziqli ko'ylak va oq shortik kiyadi."],["Tight","tor, qisib turadigan, tarang",4,"This shirt's too tight around the neck–I can't breathe.","Bu ko'ylakni bo'yin qismi haddan tashqari tor ekan–nafas ololmayapman."],["Trendy","urf bo'lgan, ommalashgan; mo'dniy",4,"He always looks trendy, like he stepped out of a fashion shop.","U doimo mo'dniy ko'rinadi, xuddi mo'da do'konidan chiqqandek."],["Casually","odatiy tarzda, norasmiy kiyimlar bilan",4,"He was casually dressed in jeans and a polo shirt.","U odatdagidek jinsi shim va yoqali futbolka kiyib olgandi."],["Comfortably","qulay tarzda",4,"She was comfortably dressed in a sweatshirt and old jeans.","U qulay tarzda sviter va eski jinsi shim kiyib olgandi."],["Smartly","bejirim tarzda, mo'dniy tarzda",4,"Why can't you dress smartly and throw away those old jeans?","Nima uchun bu eski jinsi shimni axlatga tashlab yuborib, mo'dniy tarzda kiyinolmaysiz? (= sizga nima halal beradi bunday qilishingizga?)"],["Blog","blog yuritmoq",5,"Finley blogs about his life in Ireland.","Finley Irlandiyadagi hayoti to'g'risida blog yuritadi."],["Blog","blog",5,"You can read about my trip in my blog.","Sayohatim to'g'risida blogimda o'qishingiz mumkin."],["Blogger","blogger",5,"She's a blogger who writes about fashion shows.","U mo'da tomoshalari to'g'risida yozadigan blogger."],["Comfort","yupatmoq, ovutmoq, tasalli bermoq",5,"She comforted herself with the thought that it would soon be spring.","U tez orada bahor keladi degan o'y bilan o'zini o'zi ovutdi."],["Comfort","qulaylik",5,"Learn a new language in the comfort of your own home.","O'z uyingizning qulayligini tark etmagan holda (= onlayn) yangi til o'rganing."],["Comfortable","qulay",5,"I don't care about style–I just want to be comfortable.","Menga mo'daning farqi yo'q–men shunchaki qulay bo'lishni xohlayman."],["Uncomfortable","noqulay",5,"These shoes are really uncomfortable–do you have a bigger size?","Bu oyoq kiyim juda noqulay ekan–kattaroq o'lchamdagisi bormi sizda?"],["Uncomfortably","noqulay tarzda",5,"She slept uncomfortably and woke with a pain in her back.","U noqulay tarzda uxladi va belida og'riq bilan uyg'ondi."],["Fashion","mo'da, urf",5,"Long skirts have come into fashion again.","Uzun yubkalar yana urfga qaytdi."],["Fashionable","urfdagi",5,"Maurice wears fashionable clothes but they never look good on him.","Mo'ris urfdagi kiyimlarni kiyadi, lekin ular hech qachon uning ustida yaxshi ko'rinmaydi (= unga yarashmaydi)."],["Long","uzun",5,"That dress looks a bit long to me.","Bu ko'ylak men uchun biroz uzun ko'rinadi."],["Length","uzunlik",5,"Those trousers aren't the right length–they're too short.","Bu shim kerakli uzunlikda emas–u haddan tashqari kalta."],["Meet","uchrashmoq, ko'rishmoq",5,"The three sisters rarely meet in person, but spend hours on the phone.","Uch opa-singil kamdan- kam shaxsan (= yuzma-yuz) ko'rishadilar, ammo telefonda soatlab vaqt o'tkazadilar."],["Meeting","uchrashuv, uchrashish; majlis",5,"The boss called a meeting at work today, so I have to wear a suit.","Boshliq bugun ish joyida majlis chaqirdi, shuning uchun men kostyum-shim kiyishim zarur."],["Model","modellik qilmoq, kiyimlarni yoki mo'da mahsulotlarini o'zida kiyib ko'rsatmoq",5,"Brad and Cindy are modelling chunky knitwear on the beach.","Bred va Sindi plyajda qalin to'qilgan kiyimlarni namoyish etishyapti. Ralph's been modelling since he was 16. – Ralf 16 yoshidan beri modellik qilib keladi."],["Model","modelyer: kiyimlarni yoki mo'da mahsulotlarini o'zida kiyib ko'rsatuvchi ayol/erkak",5,"She had a successful career as a fashion model.","U mo'da modelyeri sifatida muvaffaqiyatli karyera yuritgan."],["Modelling","modelyerlik sohasi, kiyimlarni yoki mo'da mahsulotlarini o'zida kiyib ko'rsatish",5,"She would like a career in modelling.","U modelyerlik sohasida karyera qilishni xohlaydi."],["Think","o'ylamoq",5,"I didn't think you liked sports.","Sizga sport yoqadi deb o'ylamagandim."],["Thought","o'y-fikr, mulohaza",5,"You have clearly put a lot of thought into your costume.","Ko'rinib turibdiki, libosingizga ancha mulohaza kiritibsiz (= libos to'g'risida ancha o'ylagansiz)."],["Thoughtful","boshqa insonlar haqida qayg'uradigan, mehribon",5,"She's a very thoughtful girl and always remembers my birthday.","U rosa mehribon qiz va doimo mening tug'ilgan kunim yodida turadi."],["Thoughtless","bemulohaza, o'ylamay qilingan",5,"It was thoughtless of you to lose my jacket!","Mening pidjakimni yo'qotib qo'yishingiz bemulohazalik bo'libdi!"],["Thoughtfully","o'yga botib, xayol surib, o'ychan holda",5,"She stood in front of the mirror, looking thoughtfully at the dress.","U ko'zguning qarshisida o'ychan holda ko'ylakka tikilib turdi."],["Thoughtlessly","bemulohaza ravishda, oqibatini o'ylamay",5,"Thoughtlessly, I went out without a jacket and got very cold.","Men oqibatini o'ylamay kurtkasiz ko'chaga chiqib ketdim va juda sovuq qotdim."],["Trendy","urf bo'lgan, ommalashgan, mashhur",5,"She always wears trendy clothes from the most fashionable shops.","U har doim eng zamonaviy do'konlardan urfdagi kiyimlarni kiyadi."],["Train","shug'ullanmoq, mashq qilmoq",5,"I train in the gym for two hours a day.","Men kuniga 2 soat sport zalida shug'ullanaman."],["Trainers","(bir juft) krasovka",5,"Put on your trainers before you play football in the garden.","Bog'da futbol o'ynashdan avval krasovkangizni kiying."],["Wool","hayvon juni",5,"How many balls of wool did you need to knit that sweater?","Bu sviterni to'qish uchun sizga nechta to'p jun kerak bo'ldi?"],["Woolen","hayvon junidan to'qilgan",5,"I don't like woolen clothes because they make me too hot.","Menga hayvon junidan to'qilgan kiyimlar yoqmaydi chunki ular meni haddan tashqari isitib yuboradi."]]},{"n":27,"t":"Places","c":[["Art gallery","san'at galareyasi",0,"There were some beautiful paintings at the art gallery.","San'at galareyasida bir qancha chiroyli suratlar bor edi."],["Bank","bank",0,"I went into the bank to take out some money.","Men (bank hisob raqamimdan) ozgina pul yechib olish uchun bankka kirdim."],["Building","bino",0,"I live on the fourth floor of that building on the corner.","Men burchakdagi anavi binoning to'rtinchi qavatida yashayman."],["Bus/Metro/Petrol/Police/Railway/Train station","avtobus bekati/metro bekati/benzin shaxobchasi/politsiya mahkamasi/temir yo'l bekati/vokzal (poyezd bekati)",0,"Kate handed in the handbag she found at the police station.","Keyt topib olgan sumkasini politsiya mahkamasiga topshirdi."],["Car park","mashina qo'yish joyi, mashinalar turargohi",0,"The car park was full, so she had to park on the street.","Mashinalar turargohi to'lib bo'lgan edi, shuning uchun u mashinasini ko'chaga qo'yishga majbur bo'ldi."],["Castle","qal'a",0,"At the top of the hill is a 500-year-old castle.","Tepalikning eng yuqorisida 500 yillik qal'a bor."],["City/Town centre","shahar markazi",0,"No cars are allowed in the city centre on Saturdays, so shoppers can walk around freely.","Shanba kunlari shahar markazida hech qanday mashinaga ruxsat berilmaydi, shunday ekan xaridorlar bemalol yurishlari mumkin."],["Cottage","qishloq hududida joylashgan uycha, kottej",0,"Our grandma lives in a tiny cottage in the Welsh countryside.","Bizning buvimiz Uels qishlog'idagi kichik bir kottejda yashaydi."],["Countryside","qishloq hududi, shahar tashqarisi: tabiat qo'yni",0,"The countryside around here is full of rivers and forests.","Bu yerdagi qishloq hududi daryolar va o'rmonlarga to'la."],["Flat","kvartira, ko'p qavatli uy xonadoni",0,"They live in a flat on the fifth floor.","Ular beshinchi qavatdagi bir kvartirada yashashadi."],["Guesthouse","kichik mehmonxona, pansionat",0,"We stayed in a little guesthouse run by a German couple.","Biz Germaniyalik juftlik tomonidan yuritiladigan kichik bir pansionatda turdik."],["Museum","muzey",0,"The children went to the castle museum to see the exhibits.","Bolalar eksponatlarni (= ko'rgazmaga qo'yilgan narsalarni) ko'rish uchun qal'a muzeyiga borishdi."],["Office block","ofis binosi: bir nechta kompaniyalarga tegishli bo'lgan ofislarni o'z ichiga oluvchi bino",0,"John works on the sixteenth floor of that office block.","Jo'n anavi ofis binosining o'n oltinchi qavatida ishlaydi."],["Park","park",0,"She takes her dog to the park to run every day.","U itini har kuni yugurishga parkka olib boradi."],["Population","aholi",0,"The population of the town is 255,000.","Shahar aholisi 255,000 nafar."],["Post office","pochta",0,"Can you go to the post office and send a parcel for me?","Pochtaga borib, mening o'rnimga pochta yubora olasizmi?"],["Shopping centre","savdo majmuasi: turli-tuman mahsulotlar sotishga mo'ljallangan ko'plab do'konlardan tashkil topgan bo'ladi",0,"We go to the shopping centre once a month and do all our shopping.","Biz bir oyda bir marta savdo majmuasiga boramiz va barcha xaridimizni qilib olamiz."],["Square","maydon",0,"There was only one hotel in the village and it was in the square.","Qishloqda faqatgina bitta mehmonxona bor edi va u maydonda edi."],["Variety","xilma-xillik, turli-tumanlik",0,"The shop offers a great variety of different clothes.","Do'kon juda ko'p xilma-xil kiyimlarni taqdim qiladi."],["Village","qishloq",0,"Only 100 people still live in the village.","Bor yo'g'i 100 nafar odam hali-hanuz qishloqda yashaydi."],["Cover","qoplamoq, yopmoq, to'smoq",1,"Snow covers the top of the mountain in winter.","Qishda tog'ning cho'qqisini qor qoplaydi."],["Cross (the bridge/street/road)","(ko'prik/ko'cha/mashina yo'lidan) o'tmoq",1,"Look left and right before you cross the road.","Mashina yo'lidan o'tishdan avval, chapga va o'ngga qarang."],["Discover","topib olmoq, duch kelmoq, kashf etmoq",1,"We got lost in Paris yesterday and discovered a lovely café.","Biz kecha Parijda adashib qoldik va ajoyib bir kafeni topib oldik."],["Divide","ajratmoq, bo'lmoq",1,"A wide river divides the two halves of the town.","Bir keng daryo shaharning ikki yarmini ajratib turadi."],["Doubt","shubhalanmoq, shubha qilmoq",1,"I doubt I can come to Spain with you, I'm afraid.","Qo'rqamanki, siz bilan birga Ispaniyaga bora olishimga shubham bor."],["Excuse","ma'zur tutmoq, kechirmoq, avf etmoq",1,"Excuse me, sir, do you know where the town hall is?","Ma'zur tuting, janob, shahar hokimiyati binosi qayerda ekanligini bilasizmi?"],["Hear","eshitmoq",1,"Can you hear the sound of water? We're near the river!","Suvning ovozini eshityapsizmi? Biz daryoga yaqinmiz!"],["Hurry","shoshilmoq, tezroq harakatlanmoq",1,"We have to hurry because the show's about to start.","Shoshilishimiz lozim chunki tomosha boshlanish arafasida."],["Notice","payqamoq, sezmoq",1,"Did you notice how tall that woman was?","U ayolning bo'yi qanchalik balandligini payqadingizmi?"],["Offer","taklif qilmoq",1,"My aunt offered to show me around the city while I was there.","Xolam men shaharda bo'lgan paytimda, menga u yerni ko'rsatishni taklif qildi."],["Park","mashinani joylamoq/qo'ymoq, parkovka qilmoq",1,"You mustn't park your car in front of the hospital.","Mashinangizni shifoxona to'g'risiga qo'ymasligingiz shart."],["Pass (the bank/supermarket/etc)","(bank/supermarket/va hokazo ning yonidan) o'tib ketmoq",1,"To get to the museum, pass the bank and take the first right.","Muzeyga borish uchun, bankdan o'ting va birinchi ko'chadan o'ngga buriling."],["Recognise","tanimoq, bilmoq, eslamoq",1,"I recognise this building from the magazine article about the town.","Men bu binoni shahar to'g'risidagi bir jurnaldagi maqoladan bilaman."],["Recommend","tavsiya qilmoq",1,"If you visit the town, I recommend that you visit the museum.","Agar shaharga tashrif buyursangiz, muzeyga tashrif buyurishni sizga tavsiya qilaman."],["Refuse","rad etmoq, qarshi bo'lmoq, bosh tortmoq",1,"I refuse to walk another step–I'm exhausted.","Men yana bir qadam tashlashdan bosh tortaman–men charchadim."],["Rent","ijaraga bermoq",1,"They rent a house in town for £500 a month.","Shaharda bitta uyni bir oy uchun 500 funt sterlingga ijaraga berishadi."],["Find out","xabar topmoq, bilib olmoq",2,"Where did you find out about this wonderful restaurant?","Ushbu ajoyib restoran to'g'risida qayerdan xabar topdingiz?"],["Knock down (e.g. a wall, a building)","buzib tashlamoq (masalan, devor yoki binoni)",2,"They must knock the building down because it's dangerous.","Binoni buzib tashlashlari kerak chunki u xavfli ekan."],["Knock down (e.g. a person in the street)","mashinada urib yubormoq (masalan, ko'chada biror kimni)",2,"The car was going too fast and knocked down a cyclist.","Mashina haddan tashqari tez ketayotgandi va bir velosipedchini urib yubordi."],["Bad/Good weather","yomon/yaxshi havo",3,"We can't play tennis today because of the bad weather.","Yomon havo tufayli bugun tennis o'ynay olmaymiz."],["Block of flats","ko'p qavatli yashash majmuasi, dom",3,"We live on the fifth floor of a block of flats.","Biz ko'p qavatli yashash majmuasining beshinchi qavatida yashaymiz."],["Go straight ahead/on","to'g'riga/oldinga yurmoq",3,"To find the museum, go straight on through the square.","Muzeyni topish uchun, maydon bo'ylab oldinga yuring."],["Go/Walk past","biror binodan o'tib ketmoq",3,"Go past the post office and take the first left.","Pochtadan o'ting va birinchi ko'chadan chapga buriling."],["In a hurry","shoshilayotgan",3,"He was in a hurry and didn't see the car coming.","U shoshilayotgan edi va mashinani kelayotganini ko'rmadi."],["On the right/left(-hand side)","o'ng/chap tarafda",3,"The bank is on the right-hand side of the street.","Bank ko'chaning o'ng tarafida."],["One-way street","bir tomonlama ko'cha: mashinalar qarama-qarshi yo'nalishda hayday olmaydi",3,"You can't drive down there–it's a one-way street!","U yerga hayday olmaysiz–u bir tomonlama ko'cha."],["Turn right/left","o'ngga/chapga burilmoq",3,"Turn left at the lights and the bank is on your left.","Svetofordan chapga buriling va bank sizning chap tomoningizda bo'ladi."],["Central","markaziy",4,"The central street in the town is the shopping street.","Shahardagi markaziy ko'cha–savdo ko'chasi."],["Foggy","tumanli, tuman tushgan",4,"It was foggy and we couldn't see ten feet in front of the car.","Havo tumanli edi va biz mashinaning oldidagi o'n fut masofani ko'rolmadik."],["Huge","ulkan, katta",4,"A huge rock came down the mountain and nearly crushed the car!","Ulkan qoyatosh tog'dan tushib keldi va mashinani ezib tashlashiga sal qoldi!"],["Icy","muzlagan, muz bilan qoplangan",4,"I slipped over on the icy street.","Men muzlagan ko'chada sirg'alib tushdim."],["Quiet","tinch, shovqindan holi",4,"It's a quiet town with not much going on.","U unchalik ko'p narsa sodir bo'lmaydigan tinch bir shaharcha."],["Narrow","tor",4,"The road is too narrow for more than one car here.","Bu yerdagi mashina yo'li bittadan ko'p mashina uchun haddan tashqari tor."],["Tiny","kichik, mayda",4,"Just 50 people lived in the tiny mountain village.","Tog'da joylashgan kichik qishloqchada bor yo'g'i 50 nafar odam yashardi."],["Wide","keng",4,"It takes five minutes to cross the wide river.","Bu keng daryodan o'tishga besh daqiqa ketadi."],["Windy","shamolli",4,"It was so windy that I could hardly stand up.","Havo shu qadar shamolli ediki men bazo'r tik tura oldim."],["Anywhere","biror yerga, qayergadir",4,"Are you going anywhere this weekend or staying at home?","Bu hafta oxirida biror yerga borasizmi yoki uyda qolasizmi?"],["Nowhere","hech qayerga, hech qayerda",4,"There's nowhere better than London to visit, I think.","O'ylashimcha, tashrif buyurish uchun Londondan yaxshiroq hech qayer yo'q."],["Build","qurmoq, barpo etmoq",5,"They have permission to build 200 new homes.","200 ta yangi uy qurish uchun ularda ruxsat bor."],["Builder","quruvchi, qurilish ishchisi",5,"He works as a builder, mostly building office blocks.","U quruvchi bo'lib ishlaydi, asosan ofis binolari quradi."],["Cross","kesib o'tmoq, (yo'lning, daryoning) narigi tarafiga o'tmoq",5,"Give me your hand while we cross the road.","Mashina yo'lidan kesib o'tayotganimizda qo'lingizni menga bering."],["Crossing","kesib o'tish, (yo'lning, daryoning) narigi tarafiga o'tish",5,"The crossing of the river takes about twenty minutes on the boat.","Daryoni qayiqda kesib o'tish taxminan yigirma daqiqa oladi."],["Doubt","shubha",5,"There is no doubt at all that we did the right thing.","Biz to'g'ri ishni qilganimizga umuman shubha yo'q."],["Doubtful","shubha-gumonga ega, shubhasi bor",5,"I am doubtful that I could live in such a tiny village.","Men bu qadar kichik qishloqchada yashay olishimga shubham bor."],["Doubtfully","shubhalanib, ishonmay",5,"I looked doubtfully at my friend–I didn't think we could make it up the mountain.","Men do'stimga shubhalanib qaradim–tog'ning tepasiga chiqa olamiz deb o'ylamagandim."],["Flash","yonmoq, charaqlamoq, yaltiramoq",5,"Start crossing when the green WALK sign starts to flash.","Yashil rangli YURING belgisi yonishni boshlaganda yo'ldan o'tishni boshlang."],["Flash","chaqnash, yaltirash",5,"The flashes from the guns illuminated the sky.","Qurollardan chiqqan chaqnashlar osmonni yoritib yubordi."],["Flashing","charaqlayotgan, yonayotgan, yaltirayotgan",5,"We saw some flashing lights ahead and stopped the car–it was the police.","Biz oldimizda yonayotgan chiroqlarni ko'rdik va mashinani to'xtatdik–u politsiya edi."],["Fog","tuman",5,"We drove slowly through the fog.","Biz tuman oralab sekinlik bilan haydadik."],["Foggy","tumanli",5,"The road was so foggy that we couldn't keep driving.","Yo'l shu qadar tumanli ediki biz mashinani haydashda davom etolmadik."],["Ice","muz",5,"There was ice on the windows.","Derazalarda muz bor edi. (= Derazalar muzlagan edi)."],["Icy","muzlagan",5,"Be careful driving–the roads are icy.","Mashina haydayotganda ehtiyotkor bo'ling–yo'llar muzlagan."],["Rain","yomg'ir yog'moq",5,"It rained and rained and didn't stop for days.","Yomg'ir yog'averdi, yog'averdi va kunlab to'xtamadi."],["Rain","yomg'ir",5,"It's pouring with rain.","Yomg'ir qattiq yog'yapti."],["Rainy","yomg'irli",5,"I'm tired of the rainy weather–I want to see some sun.","Yomg'irli havodan charchadim–biroz quyoshni ko'rishni istayman."],["Quiet","jimjit, shovqinsiz, tinch",5,"\"Be quiet,\" said the teacher.","”Jim bo'ling,\" dedi o'qituvchi."],["Quietly","shovqin chiqarmay",5,"He came into the room so quietly that I didn't notice him.","U xonaga shu qadar shovqin chiqarmay kirib keldiki, men uni payqamadim."],["Widen","kengaytirmoq",5,"They are going to widen the river to let bigger boats down.","Kattaroq qayiqlarni o'tkazish uchun daryoni kengaytirishmoqchi."],["Width","kenglik",5,"The width of the road is 10 metres.","Yo'lning kengligi 10 metr."],["Widely","keng miqyosda, ko'p odam tomonidan",5,"They speak Spanish widely in South America.","Janubiy Amerikada ispan tilida keng miqyosda gaplashishadi."],["Wind","shamol",5,"The wind is blowing from the south.","Shamol janubdan esmoqda."]]},{"n":30,"t":"Travel","c":[["Airport","aeroport",0,"The plane landed in Athens airport right on time.","Samalyot Asens aeroportiga o'z vaqtida qo'ndi."],["Coach","turistik avtobus (shaharlararo sayohat uchun)",0,"We're going to Manchester by coach since it's cheaper than the train.","Biz Manchesterga turistik avtobus orqali boryapmiz chunki u poyezddan ko'ra arzonroq."],["Delay","kechiktirilish",0,"Our plane left after a short delay because of a late passenger.","Samalyotimiz kechikkan yo'lovchi tufayli yuzaga kelgan qisqa kechiktirilishdan so'ng yo'lga chiqdi."],["Flight attendant","styuardessa: samalyotda xizmat ko'rsatuvchi xodim",0,"The flight attendant said the plane was ready to take off.","Styuardessa samalyot havoga ko'tarilishga tayyor ekanligini aytdi."],["Guest","mehmon",0,"Guests in this hotel come here to relax and enjoy themselves.","Ushbu mehmonxonadagi mehmonlar bu yerga dam olish va mazza qilish uchun kelishadi."],["Hotel","mehmonxona",0,"We don't have enough money to stay in a five-star hotel.","Bizda besh yulduzli mehmonxonada turish uchun yetarlicha pul yo'q."],["Hostel","talabalar, ishchilar yoki sayyohlar uchun maxsus, arzon narxlardagi yotoqxona",0,"The students are staying in hostels as they tour Europe to save money.","Yevropa bo'ylab sayohat qilish davomida, o'quvchilar pul tejab qolish uchun maxsus yotoqxonalarda tunashmoqda."],["Journey","sayohat, safar",0,"The train journey from London to Edinburgh takes 4-5 hours.","Londondan Edinburgga poyezd safari 4-5 soat vaqt oladi."],["Luggage","yuk, bagaj",0,"The only luggage I have is a small suitcase that I can take on the plane with me.","Menda bor yagona yuk–bu men o'zim bilan samalyotga olib chiqishim mumkin bo'lgan kichik bir chamadon."],["Package holiday","barcha xizmatlar uchun oldindan birdaniga to'lanadigan turistik sayohat: transport, yotoqxona va shunga o'xshash barcha narsalar avvaldan tashkillashtirib qo'yiladi",0,"We went on a package holiday to Egypt and it was so cheap!","Biz Misrga sayohat qildik va u juda arzon bo'ldi!"],["Passenger","yo'lovchi",0,"One of the passengers was so ill that the plane had to turn back.","Yo'lovchilardan biri shu qadar betob ediki samalyot ortga qaytishga majbur bo'ldi."],["Passport","pasport",0,"We showed our passports and then went to get our luggage.","Biz pasportlarimizni ko'rsatdik, va keyin yukimizni olishga bordik."],["Plane","samalyot",0,"The plane landed in Gatwick Airport.","Samalyot Gatvik Aeroportiga qo'ndi."],["Platform","platforma (poyezd vokzalida)",0,"What platform does the train to Glasgow leave from?","Glazgo'ga bo'lgan poyezd qaysi platformadan jo'naydi?"],["Seatbelt","xavfsizlik kamari",0,"The police officer stopped the driver for not wearing her seatbelt.","Politsiya ofitseri haydovchini xavfsizlik kamari taqmaganligi uchun to'xtatdi."],["Ship","kema",0,"The ship crosses the Atlantic Ocean from Southampton to New York.","Kema Sausampten shahridan Nyu Yorkka Atlantika okeanini kesib o'tadi."],["Suitcase","chamadon",0,"You have too many things in your suitcase–it won't close.","Chamadoningizda haddan tashqari ko'p narsa bor–u yopilmayapti."],["Tour guide","gid, yo'l boshlovchi",0,"The tour guide showed us the best sights of the city.","Yo'l boshlovchi bizga shaharning eng yaxshi diqqatga sazovor joylarini ko'rsatdi."],["Tourist information centre","sayyohlar uchun ma'lumot markazi",0,"We got a map of the town at the tourist information centre.","Biz sayyohlar uchun ma'lumot markazida shahar xaritasini oldik."],["Traffic jam","tirbandlik",0,"They got stuck in a traffic jam and missed their flight.","Ular tirbandlikda turib qolishdi va parvozlarini o'tkazib yuborishdi."],["Traffic lights","svetofor",0,"The traffic lights turned green and the cars started moving.","Svetofor chiroqlari yashilga o'zgardi va mashinalar harakatlana boshladi."],["Train station","poyezd vokzali",0,"When we get to the train station, what platform do we go to?","Poyezd vokzaliga yetib borganimizda, qaysi platformaga boramiz?"],["Travel agent","sayohat agenti; sayohat agentligi",0,"The travel agent booked me a holiday in Italy.","Sayohat agentligi men uchun Italiyada ta'til tashkillashtirib qo'ydi."],["Trip","sayohat",0,"We're going on a three-day trip to Paris.","Biz Parijga uch kunlik sayohatga ketyapmiz."],["Arrive","yetib bormoq, yetib kelmoq",1,"The train leaves London at 6 pm and arrives in Edinburgh at 10.30.","Poyezd Londonni kechki soat 6 da tark etadi va Edinburgga 10.30 da yetib boradi."],["Camp","toza havoda dam olmoq (odatda chodir tikib)",1,"I prefer to camp on holiday because I love sleeping in a tent.","Men ta'tilda toza havoda dam olishni afzal ko'raman chunki menga chodirda uxlash yoqadi."],["Delay","kechiktirmoq, keyinroqqa qoldirmoq",1,"The coach was delayed by an hour because of engine trouble.","Motordagi muammo tufayli, turistik avtobus bir soatga kechiktirildi."],["Land","(samalyotga nisbatan) qo'nmoq",1,"The plane landed in Paris right on time and we got off.","Samalyot Parijga o'z vaqtida qo'ndi va biz undan tushdik."],["Leave","jo'namoq, yo'lga chiqmoq",1,"I packed my bags and left for the airport.","Men sumkalarimni tayyorladim (= ichiga barcha kerakli narsalarni joyladim) va aeroportga jo'nadim."],["Pack","joylamoq, chamadonini tayyorlamoq",1,"When you pack your suitcase, put in a warm top.","Chamadoningizni tayyorlayotganingizda, issiqqina ustki kiyim solib oling."],["Relax","hordiq chiqarmoq, dam olmoq",1,"I work very hard and go on holiday to relax.","Men juda tirishib ishlayman va dam olish uchun ta'tilga chiqaman."],["Stay","biror joyda tunamoq, turmoq, vaqtinchalik yashamoq",1,"We are staying in a lovely hotel near the sea.","Biz dengiz yaqinidagi ajoyib bir mehmonxonada turibmiz."],["Travel","sayohat qilmoq",1,"I love to travel, especially to countries that are far away.","Men sayohat qilishni sevaman, ayniqsa uzoq-uzoqdagi mamlakatlarga."],["Unpack","chamadonini bo'shatmoq, kiyimlarini olmoq",1,"I unpacked my suitcase and put my clothes in the wardrobe.","Men chamadonimni bo'shatdim va kiyimlarimni kiyim javoniga qo'ydim."],["Check in/out","(mehmonxona yoki aeroportda) ro'yxatdan o'tmoq/mehmonxona pulini to'lamoq va ro'yxatidan chiqmoq",2,"When you get to the airport, you have to check in.","Aeroportga yetib borganingizda, ro'yxatdan o'tishingiz kerak bo'ladi."],["Get off","(avtobus/poyezd/metro/samalyotdan) tushmoq",2,"The coach arrived at the station and the passengers got off.","Turistik avtobus stansiyaga yetib keldi va yo'lovchilar tushishdi."],["Get on","(avtobus/poyezd/metro/samalyotga) chiqmoq",2,"We got on the train at Coventry and travelled north.","Biz Koventri shahrida poyezdga chiqdik va shimolga sayohat qildik."],["Get in","mashinaga o'tirmoq",2,"The taxi stopped and I got in.","Taksi to'xtadi va men unga o'tirdim."],["Hurry up","shoshiling! tezroq bo'ling!",2,"Hurry up or we'll miss the plane!","Shoshiling, aks holda samalyotni o'tkazib yuboramiz!"],["Slow down","sekinlashmoq",2,"Slow down! You nearly crashed!","Sekinlashing! Avariya bo'lishingizga sal qoldi!"],["Put up (a tent)","(chodir) tikmoq, (chodir) rostlamoq",2,"You can't go camping. You can't put up a tent!","Siz kempingga chiqa olmaysiz. Siz chodir tika olmaysiz!"],["Take off","(samalyot va vertalyotga nisbatan) havoga ko'tarilmoq",2,"The plane took off and flew up into the sky.","Samalyot havoga ko'tarildi va osmonga uchib ketdi."],["Travel around (by car, a place, etc)","(mashinada, biror joyni) aylanmoq, sayohat qilmoq",2,"I'm flying to Cuba and travelling around the country for a month.","Men Kubaga uchib ketyapman va bir oy davomida mamlakatni aylanaman."],["At ... km per hour","soatiga... km tezlikda",3,"This car can go at 180 km per hour.","Bu mashina soatiga 180 km tezlikda yura oladi."],["By air/sea/rail/road","havo/dengiz/temiryo'l/mashina yo'li orqali",3,"The fastest way to travel is by air.","Sayohat qilishning eng tez yo'li–havo yo'li orqali."],["By bus/car/plane/taxi/train","avtobusda/mashinada/samalyotda/taksida/poyezdda",3,"There's no time for a bus. We have to go by taxi.","Avtobus uchun vaqt yo'q. Taksida ketishga majburmiz."],["Go camping","ochiq havoda chodir tikib dam olishga bormoq",3,"Let's just throw a tent in the car and go camping.","Keling mashinaga chodir solamiz va ochiq havoda chodir tikib dam olishga boramiz."],["Go on holiday","ta'tilga chiqmoq, dam olishga bormoq",3,"We go on holiday to France every summer.","Biz har yoz faslida Fransiyaga dam olishga boramiz."],["On a journey/trip","safarda, sayohat mobaynida",3,"His wife's Chinese–they met on a trip of his to Hong Kong.","Uning rafiqasi xitoylik–ular uning Gonkongga bo'lgan sayohati mobaynida uchrashishgan."],["On board","kema, samalyot bo'rtida",3,"Once all the passengers are on board, we can leave.","Barcha yo'lovchilar bo'rtga chiqib bo'lishlari bilanoq, biz yo'lga chiqa olamiz."],["On foot","piyoda",3,"I had no money for a bus, so I got here on foot.","Avtobus uchun pulim yo'q edi, shuning uchun bu yerga piyoda keldim."],["See the sights","diqqatga sazovor joylarni aylanmoq, ko'rmoq",3,"On our first day in Paris we went to see the sights.","Parijdagi birinchi kunimizda biz diqqatga sazovor joylarni ko'rish uchun bordik."],["Afraid","qo'rqadigan",4,"I'm afraid of dogs. They really scare me.","Men itlardan qo'rqaman. Ular meni juda qo'rqitadi."],["Brilliant","ajoyib, zo'r = wonderful, great, fantastic",4,"That's a brilliant idea! Let's go camping!","Bu ajoyib fikr! Keling ochiq havoda chodir tikib dam olishga boramiz!"],["Careful","ehtiyotkor",4,"Be careful when you cross the road because the cars go very fast.","Mashina yo'lidan o'tishda ehtiyotkor bo'ling, chunki mashinalar juda tez yuradi."],["Cool","salqin",4,"Even though it's summer, it's still quite cool in the morning.","Hozir yoz bo'lishiga qaramay, hali ham tong payti havo ancha salqin."],["Dirty","kir, iflos, chang bosgan",4,"Our hotel room was dirty, so mum asked them to clean it.","Bizning mehmonxonadagi xonamiz kir edi, shuning uchun oyim ulardan tozalashlarini so'radilar."],["Early","erta, vaqtli, barvaqt",4,"I've got an early flight tomorrow, so I'm going to bed.","Ertaga barvaqt parvozim bor, shuning uchun men uyquga yotyapman."],["Abroad","chet elga, xorijga, xorijdagi, chet elda",4,"This is my first holiday abroad–my other holidays were in Uzbekistan.","Bu mening chet eldagi birinchi ta'tilim–boshqa ta'tillarim O'zbekistonda bo'lgan."],["Again","yana",4,"Let's go to Rome again. Last time it was great.","Keling yana Rimga boramiz. Oldingi safar ajoyib bo'lgandi."],["Arrive","yetib kelmoq, yetib bormoq",5,"She'll arrive in New York at noon.","U Nyu Yorkka qoq peshinda yetib keladi/boradi."],["Arrival","yetib kelish/borish",5,"Our arrival in London was delayed by bad weather.","Londonga yetib borishimiz yomon ob-havo tufayli kechiktirildi."],["Depart","jo'namoq, yo'lga chiqmoq = leave",5,"This train will depart in three minutes.","Bu poyezd uch daqiqada yo'lga chiqadi."],["Departure","jo'nash, yo'lga chiqish",5,"The time of departure is 7.30, but from which platform?","Jo'nash vaqti 7.30, biroq qaysi platformadan?"],["Explore","tadqiq etmoq: biror joy haqida ko'proq o'rganish uchun u yerni aylanmoq",5,"The best way to explore the countryside is on foot.","Shahar tashqarisini tadqiq etishning eng yaxshi yo'li piyoda aylanishdir."],["Explorer","tadqiqotchi, yangi joylarni kashf qiluvchi",5,"He was an explorer who travelled through the Amazon.","U Amazonka o'rmoni bo'ylab sayohat qilgan tadqiqotchi edi."],["Drive","haydamoq",5,"Have you ever driven a racing car?","Hayotingiz davomida qachondir poyga mashinasi haydab ko'rganmisiz?"],["Drive","mashinada aylanish",5,"He offered to take me for a drive later in the day.","U kunning ikkinchi yarmida meni mashinada aylanishga taklif qildi."],["Driver","haydovchi",5,"The driver of the coach had to stop and ask for directions!","Turistik avtobus haydovchi to'xtab, yo'nalish (= qayerga yurish kerakligini) so'rashga majbur bo'ldi!"],["Fly","uchmoq",5,"Geese fly south in the autumn.","G'ozlar kuzda janubga uchishadi."],["Flight","parvoz",5,"What airport does your flight to Paris leave from?","Sizning Parijga bo'lgan parvozingiz qaysi aeroportdan jo'naydi?"],["Park","mashina joylamoq/qo'ymoq, parkovka qilmoq",5,"You can't park the car here.","Mashinani bu yerga qo'ya olmaysiz."],["Parking","parkovka qilish, mashinani qo'yish",5,"Parking at the airport is free for the first 30 minutes.","Aeroportda parkovka qilish dastlabki 30 daqiqa uchun bepul."],["Sail","qayiqda suzmoq, kemada suzmoq",5,"We sailed on a large ocean liner.","Biz ulkan okean kemasida suzdik."],["Sailing","suzish",5,"Sailing across the Atlantic in a small boat is difficult even today.","Atlantika okeanini kichik qayiqda suzib o'tish hattoki hozirgi kunda ham murakkab."],["Sailor","dengizchi, matros",5,"He works as a sailor of a passenger ship.","U yo'lovchi tashish kemasida matros bo'lib ishlaydi."],["Tour","sayohat qilmoq, gastrolga chiqmoq",5,"He's toured across Europe, the UK and North America.","U Yevropa, Birlashgan Qirollik hamda Shimoliy Amerika bo'ylab sayohat qilgan."],["Tour","sayohat, gastrol",5,"We met a group of Italians on a tour in Peru.","Biz Perudagi sayohat davomida bir guruh italyaliklarni uchratdik."],["Tourist","sayyoh, turist",5,"Millions of tourists visit Greece every year.","Har yili millionlab sayyohlar Gretsiyaga tashrif buyuradi."],["Travel","sayohat",5,"The price includes travel from Bangkok to Phuket.","Bu narx Bangkokdan Phuketgacha bo'lgan sayohatni o'z ichiga oladi."],["Traveller","sayohatchi",5,"She's a real traveller and has been to over fifty countries.","U haqiqiy sayohatchi va ellikdan ziyod mamlakatlarda bo'lgan."],["Visit","tashrif buyurmoq",5,"He is planning to visit China later this month.","U bu oyning oxirida Xitoyga tashrif buyurishni rejalashtiryapti."],["Visit","tashrif",5,"It's my first visit to New York.","Bu mening Nyu Yorkka bo'lgan birinchi tashrifim."],["Visitor","mehmon, tashrif buyuruvchi",5,"We've got visitors from abroad staying with us at the moment.","Ayni damda biz bilan turgan chet ellik mehmonlariz bor."]]},{"n":33,"t":"Health And Fitness","c":[["Amount","miqdor",0,"What is a healthy amount of food for an adult?","Voyaga yetgan odam uchun sog'lom oziq-ovqat miqdori qanday?"],["Balanced diet","me'yorlashtirilgan ovqatlanish: sog'lom bo'lish uchun zarur bo'lgan ozuqaviy moddalarni ta'minlay oladigan mahsulotlarni iste'mol qilish",0,"Eat a balanced diet to stay healthy.","Sog'lom holatda qolish uchun me'yorlashtirilgan tarzda ovqatlaning."],["Contents","tarkib, mundarija",0,"I looked through the contents page of the book.","Men kitobning mundarija berilgan varag'iga ko'z yugurtirib chiqdim."],["Exercise","mashq",0,"I'm going to the gym to do some exercise.","Ozroq mashq qilish uchun sport zaliga ketyapman."],["Fault","xato, ayb",0,"It's your fault that we missed the bus–you're so slow.","Avtobusni o'tkazib yuborishimiz sizning aybingiz–siz juda sekinsiz."],["Fever","isitma",0,"The thermometer says 39°C–you've got a fever.","Termometr 39°C deyapti–isitmangiz bor."],["Fitness","jismonan tetiklik",0,"I joined a gym because fitness is important to me.","Men sport zaliga qo'shildim chunki jismonan tetik bo'lish men uchun muhim."],["Fizzy drink","gazli ichimlik, napitka",0,"Ivan doesn't like the bubbles in fizzy drinks.","Gazli ichimliklardagi pufakchalar Ivanga yoqmaydi."],["Fresh/Frozen/Healthy food","svejiy (yangi)/muzlatilgan/sog'liqqa foydali oziq-ovqat",0,"You need to eat more fresh food–go to the market.","Siz ko'proq yangi oziq-ovqat yeyishingiz kerak–bozorga boring."],["Height","balandlik, bo'y",0,"His dad was very tall but he's of medium height.","Uning dadasi juda baland bo'yli edi, lekin uning bo'yi o'rtacha."],["Hospital","shifoxona, kasalxona",0,"Henry is in hospital because he had a car crash.","Henri shifoxonada chunki u avariyaga uchradi."],["Improvement","yaxshilanish",0,"That hair style is a great improvement on your last one.","Bu soch turmagi avvalgisiga qaraganda ajoyib yaxshilanishdir (= avvalgi soch turmagidan ancha yaxshiroq)."],["Large/Double/Small/etc helping (of something)","katta/ikki karra ko'p/kichik/... portsiya",0,"That dessert looks great–give me a large helping.","Bu shirinlik ajoyib ko'rinadi–menga katta portsiyasidan keltiring."],["Medical advice","tibbiy maslahat",0,"I heard you're a doctor and I need medical advice.","Sizni shifokor deb eshitdim va men tibbiy maslahatga muhtojman."],["Miracle","mo'jiza",0,"It's a miracle–my mum was so ill and now she's better.","Bu mo'jiza–mening oyim juda kasal edi, endi esa ahvoli yaxshiroq."],["Quality","sifat",0,"Make sure the food you eat is top quality, not junk.","Iste'mol qiladigan ovqatingiz sog'liqqa zararli emas, balki yuqori sifatli ekanligiga ishonch hosil qiling."],["Quantity","miqdor",0,"When you eat that quantity of food, you'll gain weight.","Buncha miqdorda ovqat yeganingizda, vazn orttirasiz."],["Result","natija",0,"Did you get the results of your medical tests?","Tibbiy tekshiruvlaringiz natijalarini oldingizmi?"],["Skin","teri",0,"I stayed in the sun too long and my skin is red.","Men haddan tashqari uzoq vaqt quyoshda turdim va hozir terim qizargan."],["Spot","nuqta, husnbuzar",0,"He has bad skin and his face is covered in spots.","Uning terisi yomon, yuzi esa husnbuzarlar bilan qoplangan."],["Temperature","harorat",0,"You feel hot–I'm going to take your temperature.","O'zingizni issiq his qilyapsiz–haroratingizni o'lchab ko'raman."],["Way","yo'l, usul",0,"Swimming is a great way to get fit.","Suzish jismonan tetik bo'lishning ajoyib yo'li."],["Allow","yo'l qo'ymoq, ruxsat bermoq",1,"His doctor doesn't allow him to eat much sugar.","Uning shifokori unga ko'p shakar iste'mol qilishga ruxsat bermaydi."],["Break","sindirmoq",1,"John broke his leg while skiing.","Jo'n chang'ida uchayotganda oyog'ini sindirib oldi."],["Burn","kuymoq, kuydirmoq",1,"Wait till the food cools or you'll burn your tongue.","Ovqat sovuguncha kuting, aks holda tilingizni kuydirib olasiz."],["Check","tekshirmoq",1,"Get a dentist to check your teeth every six months.","Tishlaringizni har olti oyda tish shifokoriga tekshirtiring."],["Contain","o'z ichiga olmoq, tarkibida... bor bo'lmoq",1,"The chewing gum doesn't contain any sugar.","Saqichning tarkibida hech qanday shakar yo'q."],["Cough","yo'talmoq",1,"Why are you coughing–is something stuck in your throat?","Nima uchun yo'talyapsiz– tomog'ingizga biror narsa tiqilib qoldimi?"],["Exercise","(jismoniy) mashq qilmoq",1,"If you exercise, you'll get fitter.","Agar mashq qilsangiz, jismonan tetikroq bo'lasiz."],["Feel","his qilmoq",1,"Your cheek is very hot–do you feel ill?","Yuzingiz (asosan yonoq qismi) juda issiq–o'zingizni betob his qilyapsizmi?"],["Hurt","shikastlab olmoq",1,"I fell over and hurt my arm.","Men yiqilib tushdim va qo'limni shikastlab oldim."],["Include","o'z ichiga olmoq",1,"A healthy diet includes fish.","Sog'lom ovqatlanish baliqni o'z ichiga oladi."],["Insist","qattiq turib olmoq, oyoqni tirab turib olmoq",1,"I didn't want to try the dish, but the chef insisted.","Men taomni tatib ko'rishni istamagandim, biroq bosh oshpaz oyog'ini tirab turib oldi."],["Join","qo'shilmoq, (sport zaliga) a'zo bo'lmoq",1,"You need to join a gym and get fit again.","Siz sport zaliga qo'shilib, yana jismonan tetik holatga qaytishingiz kerak."],["Plan","rejalashtirmoq",1,"If you want to lose weight, you need to plan your diet.","Agar vazn yo'qotishni istasangiz, siz ovqatlanishingizni rejalashtirishingiz zarur (= nima yeyish va nima yemaslikni rejalashtirib olish zarur)."],["Rest","dam olmoq, hordiq chiqarmoq",1,"Don't go to the gym every day–rest every other day.","Sport zaliga har kuni bormang–kunora dam oling."],["Sneeze","aksirmoq",1,"Use a tissue when you sneeze, please.","Iltimos, aksirganingizda salfetkadan foydalaning."],["Weigh","og'irligi … bo'lmoq, tosh bosmoq",1,"My mum weighs the same as when she was 20–she hasn't put on weight.","Mening oyim 20 yoshida bo'lganidek bir xil og'irlikka ega–u vazn orttirgani yo'q."],["Eat out","kafe yoki restoranda ovqatlanmoq",2,"I want to eat out tonight in that new French restaurant.","Bugun oqshomda yangi ochilgan fransuz restoranida ovqatlanishni xohlayman."],["Lie down","yotmoq",2,"You look tired. You should go and lie down.","Charchagan ko'rinasiz. Borib yotishingiz kerak."],["Stay up (late)","(juda kech mahalgacha) uxlamay uyg'oq o'tirmoq",2,"How late do you stay up on a Friday night?","Juma kechasida qanchalik kech mahalgacha uxlamay uyg'oq o'tirasiz?"],["As a result","natijada",3,"He fell on the stairs and hurt his back as a result.","U zinaga yiqilib tushdi va natijada belini shikastlab oldi."],["Deal with","bilan shug'ullanmoq, bilan ish yuritmoq",3,"It's not easy to deal with Paul when he's angry.","Po'lning jahli chiqqanida, u bilan ish yuritish oson emas."],["Have a rest","dam olmoq",3,"I don't want to do anything this weekend, just have a rest.","Bu hafta oxirida hech narsa qilishni istamayman, shunchaki dam olishni istayman."],["Have/Take a shower","dush qabul qilmoq",3,"After going to the gym, I always take a shower.","Sport zaliga borgandan so'ng, men har doim dush qabul qilaman."],["Lose weight","vazn yo'qotmoq, ozmoq",3,"After ten weeks on the diet, I started losing weight.","Parxezdagi o'n kundan so'ng, men vazn yo'qota boshladim."],["Once/Twice a day/week/month/year","bir kunda/haftada/oyda/yilda bir marta/ikki marta",3,"I go swimming twice a week to keep fit.","Men jismonan tetik holatimni saqlab qolish uchun bir haftada ikki marta suzishga boraman."],["Take your/someone's temperature","biror kimning haroratini o'lchamoq",3,"The nurse took his temperature with a thermometer.","Hamshira termometr bilan uning haroratini o'lchadi."],["Dizzy","lanj, boshi aylanayotgan",4,"Your face has gone white–do you feel dizzy?","Yuzingiz oqarib ketibdi–boshingiz aylanyaptimi?"],["Fit","jismonan sog'lom va baquvvat, tetik",4,"She's very fit–she goes running every day.","U jismonan juda tetik–u har kuni yugurishga chiqadi."],["General","umumiy",4,"I read some books to get a general idea about diets.","Men dietalar haqida umumiy tasavvurga ega bo'lish uchun bir nechta kitoblarni o'qidim."],["Medical","tibbiy",4,"Go and see a doctor at the medical centre.","Borib, tibbiy markazda shifokorga ko'rining."],["Normal","odatiy, odatdagidek",4,"After so long in hospital, she just wants a normal life again.","Shifoxonada juda uzoq sarflagandan so'ng, u shunchaki odatdagidek hayotga qaytishni istaydi."],["Regular","doimiy",4,"Take regular exercise–every two days at least.","Doimiy mashq qilib turing–hech bo'lmasa har ikki kunning birida."],["Sugar free/sugar-free","shakardan holi, tarkibida shakar bo'lmagan",4,"What makes sugar-free drinks sweet?","Tarkibida shakar bo'lmagan ichimliklarni nima shirin qiladi?"],["(Un)healthy","sog'liqqa foydali (sog'liqqa zararli)",4,"A healthy diet must include fruit and vegetables.","Sog'liqqa foydali ovqatlanish meva va sabzavotlarni o'z ichiga olishi shart. Eating burgers every day is unhealthy, you know. – Har kuni burgerlar yeyish sog'liqqa zararli, bilasizku."],["Generally","umuman olganda",4,"Generally, I eat healthily, but I like a burger now and then.","Umuman olganda, men sog'liqqa foydali narsalar iste'mol qilaman, biroq gohi-gohida menga burger yoqadi."],["Normally","odatda",4,"Normally, I don't like fish, but this is so tasty!","Odatda, menga baliq yoqmaydi, biroq bunisi juda mazali ekan!"],["Balance","muvozanat, me'yor",5,"Try to keep a balance between work and relaxation.","Ish va dam olish o'rtasida me'yorni saqlashga harakat qiling."],["Balance","muvozanatni saqlamoq, me'yorni saqlamoq",5,"She tries to balance home life and career.","U uy hayoti va karyerasini muvozanatda saqlashga harakat qiladi."],["Balanced","muvozanatlashtirilgan, me'yorlashtirilgan",5,"It's important to eat a balanced diet and exercise.","Me'yorlashtirilgan tarzda ovqatlanish va jismoniy mashq qilish muhim."],["Container","idish",5,"Put any food that's left in a plastic container.","Qolib ketgan har qanday ovqatni plastik idishga soling."],["Contents","ichidagi narsalar, tarkibiy qism",5,"The contents of the food are written on the packet.","Oziq-ovqatning tarkibiy qismi ustidagi idish- paketda yozilgan."],["Energy","energiya, g'ayrat",5,"She's always full of energy.","U doimo g'ayratga to'la."],["Energetic","energiyaga boy, serg'ayrat, harakatchan",5,"I feel much more energetic since I started exercising.","Men mashq qilishni boshlaganimdan beri o'zimni ancha serg'ayrat his qilyapman."],["Health","sog'liq",5,"Her health gradually improved.","Uning sog'lig'i asta-sekin yaxshilandi."],["Healthy","sog'liqqa foydali",5,"A salad is a very healthy meal.","Salat sog'liqqa juda foydali taomdir."],["Unhealthy","sog'liqqa zararli",5,"Burgers and chips every day is unhealthy.","Har kuni burger va chipslar yeyish sog'liqqa zararli."],["Healthily","sog'liqqa foydali tarzda",5,"I need to eat more healthily and lose some weight.","Men ko'proq sog'liqqa foydali tarzda ovqatlanishim va biroz vazn yo'qotishim lozim."],["Unhealthily","sog'liqqa zararli tarzda",5,"If you eat so unhealthily, you'll start to gain weight.","Agar bu qadar sog'liqqa zararli tarzda ovqatlansangiz, vazn orttira boshlaysiz."],["High","baland",5,"What's the highest mountain in the US?","AQShdagi eng baland tog' qaysi?"],["Height","balandlik",5,"The height of the door is 2.5 metres.","Eshikning balandligi 2.5 metr."],["Improve","yaxshilanmoq",5,"I hope my French will improve when I go to France.","Umid qilamanki, Fransiyaga borganimda fransuz tilidan bilimim yaxshilanadi."],["Strong","kuchli",5,"Get Carl to lift it–he's as strong as an ox.","Uni Karlga ko'tartiring–u ho'kizdek kuchli."],["Strength","kuch",5,"Lifting weights will improve your strength.","Og'ir narsalar ko'tarish kuchingizni yaxshilaydi."],["Strengthen","kuchaytirmoq",5,"Walking up and down the stairs will strengthen your legs.","Zinadan chiqib-tushish oyoqlaringizni kuchaytiradi."],["Strongly","qattiq, o'ta, juda",5,"\"I strongly advise you to do some exercise,\" the doctor said.","\"Biroz jismoniy mashq qilishingizni qattiq maslahat beraman,\" dedi shifokor."],["Weigh","vazni... bo'lmoq, tosh bosmoq",5,"The average male tiger weighs around 200 kg.","O'rtacha erkak yo'lbars taxminan 200 kg tosh bosadi (= vazni 200 kg chamasi bo'ladi)."],["Weight","og'irlik, vazn",5,"What's the weight of your cat?","Mushugingizning vazni qanday?"]]},{"n":36,"t":"Technology","c":[["App","mobil ilova, dastur",0,"This is an app for a smartphone that finds you a taxi.","Bu sizga taksi topib beradigan smartfon uchun mobil ilova."],["Article","maqola",0,"I read an article in a magazine about laptops.","Men bir jurnalda noutbuklar haqida maqola o'qidim."],["Channel","kanal",0,"Can you change the channel? I don't want to watch this.","Kanalni o'zgartira olasizmi? Buni tomosha qilishni istamayman."],["Documentary","hujjatli film",0,"I saw a documentary about future technology.","Men kelajak texnologiyasi to'g'risida bir hujjatli film ko'rdim."],["Dot","nuqta",0,"The company website is K-L-M dot R-U.","Kompaniya vebsayti K-L-M nuqta R-U."],["Earphones/Headphones","quloqning ichiga kiradigan/quloqning ustidan taqiladigan quloqchin",0,"She can't hear you as she's wearing headphones.","U sizni eshitmaydi chunki qulog'ining ustidan quloqchin taqib olgan."],["Email","elektron pochta, email",0,"Send me an email with details of the party.","Menga bazmning tafsilotlari bilan email jo'nating."],["Episode","qism, epizod",0,"I can't come out tonight–the final episode of my favourite show's on.","Bugun oqshomda ko'chaga chiqolmayman–sevimli tomoshamning yakuniy qismi beriladi."],["Information","ma'lumot, axborot",0,"The article had some great information about new apps.","Maqolada yangi mobil ilovalar haqida ajoyib ma'lumot bor ekan."],["Keyboard","klaviatura",0,"I spilled juice on the keyboard and now the keys stick.","Men klaviatura ustiga sharbat to'kib yubordim, endi esa klaviatura tugmalari yopishib qolyapti."],["Laptop","noutbuk",0,"A laptop is good because you can carry it around.","Noutbuk yaxshi chunki uni ko'tarib yura olasiz."],["Memory","xotira",0,"My new computer has 500 GB of memory.","Yangi kompyuterim 500 GB xotiraga ega."],["Mobile (phone)","uyali telefon, qo'l telefoni",0,"I dropped my mobile in the water and it won't turn on.","Qo'l telefonimni suvga tushirib yubordim, endi esa u yoqilmayapti."],["Mouse","sichqoncha",0,"This mouse isn't working–nothing happened when I clicked.","Bu sichqoncha ishlamayapti– bosganimda hech narsa bo'lmadi."],["PC (personal computer)","shaxsiy kompyuter",0,"I opened the tower of my PC to clean it.","Men shaxsiy kompyuterimning ma'lumotlar saqlanadigan uskunasini tozalash uchun ochdim."],["Program","kompyuter dasturi, ilovasi",0,"He writes programs for a software company.","U dasturiy ta'minot kompaniyasi uchun dasturlar yozadi (= kompyuter dasturlari yaratadi)."],["Programme","teledastur",0,"There's a great programme on TV tonight.","Bugun oqshomda televizorda ajoyib teledastur beriladi."],["Smartphone","smartfon: ko'p funksiyali mobil telefon",0,"He uses his smartphone for surfing the net and sending messages.","U smartfonidan internetda o'tirish va xabarlar jo'natish uchun foydalanadi."],["Screen","ekran",0,"The TV screen has a big crack in it!","Televizor ekranida katta siniq bor!"],["Serial","serial",0,"I watch TV serial every Tuesday night.","Men har seshanba tunida teleserial tomosha qilaman."],["Signal","signal, to'lqin",0,"Have you got a strong signal on your mobile?","Qo'l telefoningizda kuchli signal bormi?"],["Tablet","planshet",0,"Tablets are better than laptops because you can hold them in one hand.","Planshetlar noutbuklardan yaxshiroq chunki siz ularni bir qo'lda ushlay olasiz."],["Text message","yozuvli xabar",0,"Jimmy sent the text message to my old mobile.","Jimi yozuvli xabarni eski qo'l telefonimga jo'natibdi."],["Website","sayt, vebsahifa",0,"The website has 10,000 visitors a day.","Ushbu sayt kuniga 10,000 tashrif buyuruvchiga ega (= har kuni 10,000 odam ushbu saytga kiradi)."],["Charge (a phone/battery)","telefon/batareya quvvatini to'ldirmoq, zaryadlamoq",1,"I need to charge my phone–it's got no battery left.","Men telefonimni zaryadlashim zarur– batareyasi qolmadi."],["Click","tugmani bosmoq (sichqoncha yordamida)",1,"Click on the icon to open the file.","Faylni ochish uchun belgining ustiga bosing."],["Contact","bog'lanmoq",1,"You need to contact your mother–she called twice.","Onangiz bilan bog'lanishingiz lozim–ikki marta qo'ng'iroq qildilar."],["Delete","o'chirmoq",1,"If you deleted the file recently, it'll still be in the recycling bin.","Agar faylni yaqinda o'chirgan bo'lsangiz, u hali ham qayta ishlash qutisida bo'ladi."],["Download","internetdan yuklab olmoq",1,"He's downloading a program from the Internet.","U internetdan bir dastur yuklamoqda."],["Phone","qo'ng'iroq qilmoq",1,"Jim phoned me on my mobile.","Jim uyali telefonimga qo'ng'iroq qildi."],["Reply","javob qaytarmoq",1,"I sent her a message but she didn't reply.","Men unga xabar jo'natdim, biroq u javob qaytarmadi."],["Save","saqlab qo'ymoq",1,"Save any files on a memory stick too.","Har qanday faylni xotira kartasiga (= fleshkaga) ham saqlang."],["Stream","onlayn efirga uzatmoq, onlayn translatsiya qilmoq",1,"This website streams TV programmes from all over the world.","Ushbu sayt butun dunyo bo'ylab teledasturlarni onlayn translatsiya qiladi."],["Text","yozuvli xabar jo'natmoq",1,"He texted his best friend, asking him to cover.","U eng yaxshi do'stiga xabar jo'natib, biror bahona topib uning yo'qligini bildirmay turishini so'radi."],["Upload","internetga yuklamoq, joylamoq",1,"I uploaded a new picture onto my profile page.","Men profilimga yangi rasm yukladim."],["Use","ishlatmoq, foydalanmoq",1,"Most people use a computer for the job nowadays.","Ko'pchilik odamlar hozirgi kunda kompyuterdan ish uchun foydalanadilar."],["Fill in","to'ldirmoq (masalan, anketani)",2,"You have to fill in a form online to join the course.","Kursga qo'shilish uchun internetda bir anketani to'ldirishingiz zarur."],["Switch/Turn off","o'chirmoq",2,"Turn off the computer–time for bed!","Kompyuterni o'chiring–uyqu vaqti bo'ldi!"],["Switch/Turn on","yoqmoq",2,"Switch on the TV–it's time for my show!","Televizorni yoqing–mening ko'rsatuvimning vaqti bo'ldi!"],["Turn up","ovozini balandlatmoq",2,"Can you turn the TV up–I can't hear a thing.","Televizorni ovozini balandlata olasizmi–bironta ham narsa eshitmayapman."],["Turn down","ovozini pasaytirmoq",2,"Turn that music down! I've got a headache!","Musiqaning ovozini pasaytiring! Boshim og'riyapti!"],["Be/Get/Keep/Stay in touch","aloqada bo'lmoq/aloqaga chiqmoq/aloqa saqlamoq/aloqada qolmoq",3,"Text messages make it easier to keep in touch with my friends.","Yozuvli xabarlar do'stlarim bilan aloqani saqlashimni osonlashtiradi."],["Be/Go online","onlayn bo'lmoq/internetga kirmoq",3,"She went online to check her emails.","U emaillarini tekshirish uchun internetga kirdi."],["Chat (with someone) online","(biror kim bilan) internetda suhbatlashmoq",3,"They chatted online for months before meeting.","Ular uchrashishlaridan avval oylab vaqt mobaynida internetda suhbatlashishdi."],["Check your email","elektron pochtasini tekshirmoq: yangi xabarlarni o'qimoq",3,"You didn't send me anything–I checked my email a minute ago.","Siz menga hech narsa jo'natganingiz yo'q–men elektron pochtamni bir daqiqa avval tekshirdim."],["Get/Send a text message","yozuvli xabar qabul qilmoq/jo'natmoq",3,"Paul got a text message from his mother telling him to come home.","Po'l onasidan uyga kelishi aytilgan yozuvli xabar qabul qildi."],["Learn about","biror narsa haqida o'rganmoq, bilib olmoq",3,"I learned about computers from my older brother.","Men akamdan kompyuterlar haqida o'rganib oldim."],["Look for","qidirmoq",3,"I'm looking for Harriet–have you seen her?","Men Hariyetni qidiryapman–uni ko'rdingizmi?"],["On the phone","telefonda (gaplashayotgan)",3,"I talk to my grandma on the phone every week.","Men har hafta buvim bilan telefonda gaplashaman."],["Advanced","takomillashgan",4,"This is the most advanced computer on the market.","Bu bozordagi (= sotib olish mumkin bo'lgan) eng takomillashgan kompyuter."],["Digital","raqamli",4,"Digital cameras are great because you see the photo immediately.","Raqamli kameralar ajoyib chunki suratni darhol ko'rasiz."],["Free","tekin, bepul",4,"The basic software is free and you pay for the advanced program.","Sodda dasturiy ta'minot bepul, takomillashgan dastur uchun esa to'laysiz."],["Main","asosiy",4,"There are around fifty computers in the main office.","Asosiy ofisda taxminan ellikta kompyuter bor."],["Multimedia","mutimediyali: axborot uzatishning xilma-xil usullari, masalan matn, tovush, jonlantirilgan va grafik tasvirlarni qamrab oluvchi texnologiyaga ega",4,"The shop sells multimedia devices like smartphones.","Ushbu do'kon smartfonlar kabi multimediyali qurilmalar sotadi."],["Actually","aslida esa",4,"Programming sounds difficult but actually it's not.","Dasturlash qiyindek eshitiladi, lekin aslida unday emas."],["Afterwards","keyin esa, keyinroq",4,"He showed me how to do it and afterwards I tried.","U menga buni qanday bajarishni ko'rsatdi, keyin esa men urinib ko'rdim."],["Nearly","deyarli,...ga sal qoldi",4,"I nearly have enough money for a new mobile.","Yangi qo'l telefoni uchun deyarli yetarlicha pulim bor."],["Really","juda",4,"That's a really cool phone! Is it yours?","Bu juda zo'r telefon! Bu siznikimi?"],["Communicate","aloqa qilmoq, muloqot qilmoq",5,"We usually communicate by letter.","Biz odatda xat orqali muloqot qilamiz."],["Communication","aloqa, muloqot",5,"Text messages make communication easier and cheaper.","Yozuvli xabarlar muloqotni osonroq va arzonroq qiladi."],["Connect","bog'lanmoq, ulanmoq",5,"Click \"Continue\" to connect to the internet.","Internetga bog'lanish uchun \"Davom etish\"ni bosing."],["Connection","bog'lanish, ulanish, aloqa",5,"How fast is your Internet connection?","Sizning internet aloqangiz qanchalik tez?"],["Easy","oson",5,"Playing tennis is not as easy as it looks.","Tennis o'ynash ko'ringanidek oson emas."],["Easily","osonlik bilan, qiynalmay",5,"I can communicate with my American penfriend much more easily by email.","Men amerikalik xatdoshim bilan email orqali ancha osonroq tarzda muloqot qila olaman."],["Invent","ixtiro qilmoq, yaratmoq",5,"Who invented the first true helicopter?","Birinchi haqiqiy vertalyotni kim yaratgan?"],["Invention","ixtiro",5,"Was the computer the most important invention ever?","Kompyuter eng muhim ixtiro bo'lganmi?"],["Inventor","ixtirochi",5,"The inventor of the telephone was Alexander Graham Bell.","Telefonning ixtirochisi Aligzandr Greyem Bel bo'lgan."],["Inventive","kashfiyotchi, keng tasavvurga ega, yaratuvchan, yangilikka intiluvchan",5,"You have to be inventive to find solutions to problems.","Muammolarga yechimlar topish uchun siz keng tasavvurga ega bo'lishingiz lozim."],["Polite","muloyim, xushmuomala",5,"Please be polite to our guests.","Iltimos, mehmonlarimizga xushmuomala bo'ling."],["Impolite","qo'pol, qo'rs",5,"You didn't say hello–how impolite!","Siz salom bermadingiz–naqadar qo'pollik!"],["Politely","muloyim tarzda, muloyimlik bilan",5,"I politely told him I didn't want the job.","Men ishni xohlamasligimni muloyimlik bilan unga aytdim."],["Impolitely","qo'pol tarzda, qo'pollik bilan",5,"Don't speak so impolitely to your teacher!","O'qituvchingizga bunchalik qo'pollik bilan gapirmang!"],["Possible","mumkin, imkoni bor, iloji bor",5,"It is possible to get there by bus.","U yerga avtobus orqali borish mumkin."],["Impossible","iloji yo'q, imkonsiz, haqiqatga to'g'ri kelmaydigan",5,"It's impossible to win at this computer game.","Bu kompyuter o'yinida g'olib bo'lish imkonsiz."],["Possibility","ehtimollik, bo'lishi mumkin bo'lgan narsa",5,"There is a good possibility that I will study Computer Science.","Kompyuter Ilmini o'rganishim ehtimolligi bor (= katta ehtimollik bilan kompyuter fanini o'rganaman)."],["Print","printerdan chiqarmoq",5,"I'm printing a copy of the document for you.","Siz uchun hujjatning nusxasini printerdan chiqaryapman."],["Printer","printer",5,"There's some paper stuck in the printer.","Printerga ozgina qog'oz tiqilib qolgan."],["Use","foydalanmoq, ishlatmoq",5,"We used a carrot for the snowman's nose.","Biz qorbolaning burni uchun sabzi ishlatdik."],["Use","foydalanish, ishlatish",5,"The use of cameras in this museum is not allowed.","Bu muzeyda kameralardan foydalanishga ruxsat berilmagan (= taqiqlangan)."],["User","foydalanuvchi",5,"They ask users to create a password 14 characters long.","Ular foydalanuvchilardan 14 belgidan iborat parol yaratishni so'rashadi."],["Useful","foydali",5,"A smartphone is very useful when you're travelling.","Sayohat qilayotganingizda, smartfon juda foydali bo'ladi."],["Useless","foydasiz",5,"The information was useless to him.","Ma'lumot unga foydasiz bo'ldi."],["View","ko'rmoq",5,"You can view the sharks from outside the glass tank.","Akulalarni akvarium tashqarisidan ko'rishingiz mumkin."],["View","manzara",5,"The view from the top of the mountain is fantastic.","Tog'ning yuqorisidagi manzara ajoyib."],["Viewer","tomoshabin",5,"The TV show has millions of viewers.","Teleko'rsatuv millionlab tomoshabinlarga ega."],["Write","yozmoq",5,"I wanted to travel and then write about it.","Men sayohat qilishni va keyin bu haqida yozishni xohlagandim."],["Writer","yozuvchi",5,"He works as a writer for a TV show.","U bir teleko'rsatuvda yozuvchi bo'lib ishlaydi."],["Writing","yozish (qobilyati); yozuv, husnixat",5,"Her writing is good, but it's not good enough to write for this serial.","Uning yozishi yaxshi, biroq ushbu serialga yozish uchun yetarlicha yaxshi emas."]]},{"n":39,"t":"Nature","c":[["Beach","plyaj",0,"We lay on the beach getting dry from our swim in the sea.","Biz dengizdagi suzishimizdan qurib plyajda yotdik."],["Climate change","iqlim o'zgarishi",0,"Climate change creates extreme weather all over the world.","Iqlim o'zgarishi butun dunyo bo'ylab ekstremal ob-havoni keltirib chiqaradi."],["Creature","mavjudot, jonzot",0,"The dolphin is a beautiful sea creature.","Delfin chiroyli dengiz mavjudotidir."],["Depth","chuqurlik",0,"The depth of the water is about 10 metres.","Suvning chuqurligi taxminan 10 metr."],["Environment","atrof-muhit",0,"Saving the environment is an important thing to do.","Atrof-muhitni saqlab qolish qilish kerak bo'lgan muhim ishdir."],["Fresh air","toza havo",0,"Go out for a walk and get some fresh air.","Piyoda sayrga chiqing va biroz toza havo oling."],["Fence","panjara, to'siq",0,"The fence between the gardens was blown down in the storm.","Bog'lar orasidagi panjara bo'ronda sinib tushgandi."],["Field","dala, keng va ochiq maydon",0,"There were twenty cows eating grass in the field.","Dalada yigirmata sigir maysa yeyotgandi."],["Flood","suv toshqini",0,"The flood left the village under water.","Suv toshqini qishloqni suv ostida qoldirdi."],["Forest fire","o'rmon yong'ini",0,"The fire fighters fought the forest fire for days.","O't o'chiruvchilar o'rmon yong'ini bilan kunlab kurashdilar."],["Global warming","global isish",0,"Global warming is turning huge areas into deserts.","Global isish ulkan maydonlarni sahrolarga aylantirmoqda."],["Island","orol",0,"They live on a tiny island off the coast of Wales.","Ular Uels qirg'og'i bo'yidagi kichik bir orolchada yashaydilar."],["Litter","chiqindi, axlat",0,"The children were picking up litter from the school field.","Bolalar maktab maydonidan chiqindi terayotgan edilar."],["Litter/Recycling bin","axlat qutisi/qayta ishlab chiqariladigan chiqindilar uchun maxsus quti",0,"Put glass in the recycling bin.","Shishani qayta ishlab chiqariladigan chiqindilar uchun maxsus qutiga soling."],["Motorway","mashina yo'li, shosse, katta yo'l, avtomagistral",0,"It takes an hour to drive to London on the new motorway.","Yangi avtomagistralda Londonga borish uchun bir soat vaqt ketadi."],["Mountain","tog'",0,"We live in a village near the top of the mountain.","Biz tog' cho'qqisi yaqinidagi qishloqda yashaymiz."],["Mud","loy",0,"The floods left the fields full of thick mud.","Suv toshqinlari keng maydonlarni quyuq loyga beladi."],["Oxygen","kislorod",0,"Trees take in carbon dioxide and produce oxygen.","Daraxtlar karbonat angidridni o'ziga singdirib, kislorod ishlab chiqaradi."],["Path","so'qmoq, yo'lka",0,"We walked along a path in the forest.","Biz o'rmondagi so'qmoq bo'ylab yurdik."],["Pollution","ifloslanish",0,"Factories produce a lot of air pollution.","Zavodlar juda ko'p havo ifloslanishini keltirib chiqaradi."],["Rainforest","tropik o'rmon",0,"Thousands of birds and animals live in the Amazon rainforest.","Amazonka tropik o'rmonida minglab qush va hayvonlar yashaydi."],["Silence","jimjitlik, sukunat",0,"There was complete silence in the forest–not even a bird sang.","O'rmonda mutloq jimlik edi– hattoki bir dona qush ham sayramadi."],["Wildlife","yovvoyi tabiat: yovvoyi hayvonlar va o'simliklar",0,"The wildlife in the area needs protecting.","Hududdagi yovvoyi tabiat muhofazaga muhtoj."],["Annoy","g'ashini keltirmoq, jahlini chiqarmoq",1,"Your behaviour is annoying me, so stop it.","Sizning xatti-harakatingiz meni g'ashimni keltiryapti, shunday ekan buni to'xtating."],["Blame","ayblamoq, bo'yniga ilmoq, aybdorni topmoq",1,"We must find who is to blame for the pollution.","Ifloslanishga kim aybdor ekanligini topishimiz kerak."],["Bother","g'ashiga tegmoq, o'ylantirmoq, bezovta qilmoq",1,"Doesn't the rubbish on the beach bother you? It makes me angry.","Plyajdagi chiqindi sizning g'ashingizga tegmaydimi? Bu meni jahlimni chiqaradi."],["Cause","sabab bo'lmoq, keltirib chiqarmoq",1,"Pollution has caused many problems for the fish in the river.","Ifloslanish daryodagi baliqlar uchun ko'plab muammolarga sabab bo'ldi."],["Complain","shikoyat bildirmoq, arz qilmoq",1,"They complained to the police about the noise.","Ular shovqin to'g'risida politsiyaga shikoyat qilishdi."],["Destroy","vayron qilmoq",1,"The fire destroyed huge areas of forest.","Yong'in ulkan o'rmon maydonlarini vayron qildi."],["Dig","yerni qazimoq, kovlamoq",1,"Let's dig here to try and find some potatoes.","Harakat qilib ko'rib, bir nechta kartoshka topish uchun, keling mana shu yerni kovlaymiz."],["Disappear","yo'qolmoq, yo'qolib ketmoq, g'oyib bo'lmoq",1,"Many of the birds have disappeared from this forest.","Qushlarning ko'pchiligi o'rmondan g'oyib bo'ldi."],["Flood","suv toshmoq",1,"The river overflowed and flooded the town.","Daryo o'zanidan chiqib ketdi va shaharga suv toshdi. = Daryo toshib, shaharni suv bosdi."],["Hope","umid qilmoq",1,"We hope we can stop the damage before it's too late.","Umid qilamizki, haddan tashqari kech bo'lishidan avval biz zararni to'xtatib qola olamiz."],["Litter","tartibsiz ravishda tashlangan narsalar biror joyni bulg'agan bo'lmoq",1,"Broken glass littered the streets.","Singan shishalar ko'chalarni bulg'agandi."],["Protect","himoya qilmoq",1,"It is up to us to protect the environment from harm.","Atrof-muhitni ziyondan himoya qilish bizning zimmamizda."],["Remain","o'z holicha qolmoq",1,"Nothing remained of the building after the fire.","Yong'indan so'ng, binodan hech nima qolmadi."],["Remove","olib tashlamoq",1,"We removed most of our furniture from the house.","Biz uydan ko'pchilik mebellarimizni olib tashladik."],["Slip","sirg'alib yiqilib tushmoq",1,"I slipped in the mud and fell down.","Men loyda sirg'aldim va yiqilib tushdim."],["Sting","achishib og'rimoq",1,"My arm really stings where that ant bit me.","Qo'limning chumoli chaqqan joyi juda achishib og'riyapti."],["Waste (water/energy/etc)","(suvni/elektr tokini/...) isrof qilmoq",1,"Don't waste water–turn off that tap.","Suvni isrof qilmang–jo'mrakni o'chiring."],["Clear/Clean up","tozalamoq",2,"The group cleans up beaches along the coast.","Guruh sohil bo'yidagi plyajlarni tozalaydi."],["Go out","(olovga nisbatan) o'chmoq = stop burning",2,"The forest fire went out on its own.","O'rmon yong'ini o'zi o'chdi."],["Put out (a fire)","(olovni) o'chirmoq",2,"The fire fighters managed to put the fire out.","O't o'chiruvchilar yong'inni o'chirishni uddaladilar."],["Throw away","axlatga tashlamoq",2,"Let's throw away all this old furniture.","Keling bu hamma eski mebellarni axlatga tashlaymiz."],["(On) a clear day","ochiq kun(da), bulutsiz kun(da)",3,"On a clear day, you can see the sea from this mountain.","Bulutsiz kunda, ushbu tog'dan turib dengizni ko'rishingiz mumkin."],["In the distance","uzoqda, olis masofa narida",3,"In the distance, you can just see the island.","Olis masofa naridan, faqatgina orolni ko'rishingiz mumkin."],["Instead of","ning o'rniga",3,"Instead of going away this weekend, let's help clean up the forest.","Bu hafta oxirida dam olishga ketishning o'rniga, keling o'rmonni tozalashga yordam beramiz."],["Worry about","haqida qayg'urmoq, tashvishlanmoq",3,"I worry about what future our children will have.","Men farzandlarimiz kelajagi qanday bo'lishi haqida tashvishlanaman."],["Awful","rasvo, yomon, yoqimsiz, daxshat",4,"The smell of the polluted river was awful.","Ifloslangan daryoning hidi yoqimsiz edi."],["Electric","elektrli, tokli",4,"I got an electric shock from the wire.","Men simdan elektrli tok urishi qabul qildim (= meni tok urdi)."],["Impossible","imkonsiz, haqiqatga to'g'ri kelmaydigan",4,"It's impossible to know how long we have to change the planet.","Sayyorani o'zgartirish uchun qancha vaqtimiz borligini bilish imkonsiz."],["Shallow","sayoz, uncha chuqur emas",4,"The water was very shallow–it came up to my knees.","Suv juda sayoz edi–u tizzalarimgacha chiqdi."],["Silent","jimjit, shovqinsiz, tinch",4,"Everyone had gone and the village was silent.","Hamma ketib bo'lgandi va qishloq jimjit edi."],["Simple","oddiy, sodda va tushunishga oson",4,"They have a very simple diet–mostly vegetables.","Ular juda oddiy ovqatlanishadi–asosan sabzavotlar bilan."],["Sudden","to'satdan sodir bo'lgan, qo'qqisdan, kutilmaganda",4,"I felt a sudden pain in my arm.","Men qo'limda kutilmaganda og'riq his qildim."],["Wooden","yog'ochdan yasalgan",4,"The wooden furniture was all destroyed in the fire.","Yog'ochdan yasalgan mebellarning hammasi yong'inda vayron bo'lgandi."],["Suddenly","to'satdan, kutilmaganda, qo'qqisdan",4,"Suddenly, water began to come into the room.","To'satdan, suv xonaga oqib kira boshladi."],["Fortunately","yaxshiyamki, baxtim(iz)ga",4,"Fortunately, nobody was hurt in the fire.","Yaxshiyamki, yong'inda hech kim shikastlanmabdi."],["Unfortunately","afsuski, baxtga qarshi",4,"Unfortunately, the flood washed away our car.","Afsuski, toshqin mashinamizni oqizib ketibdi."],["Complaint","shikoyat, arz",5,"We made a complaint about the pollution from the factory.","Biz zavoddan chiqayotgan ifloslanish to'g'risida arz qildik."],["Deep","chuqur",5,"The water is only a few centimetres deep.","Suv bor yo'g'i bir necha santimetr chuqur."],["Deepen","chuqurlashmoq",5,"The flood waters continue to deepen.","Toshqin suvlari chuqurlashishda davom etmoqda."],["Deeply","chuqur tarzda, juda, o'ta, qattiq",5,"I'm deeply worried about what will happen to the wildlife.","Men yovvoyi tabiatga nima bo'lishidan qattiq xavotirdaman."],["Distant","uzoq, olis",5,"The airport was about 20 kilometres distant.","Aeroport taxminan 20 kilometr uzoq edi."],["Distance","masofa",5,"In the distance, we could see the forest burning.","Olis masofa narida, biz o'rmon yonayotganini ko'ra olardik."],["Distantly","uzoq tarzda",5,"I'm distantly related to the king.","Men qirol bilan uzoq qarindoshman."],["Electricity","elektr toki",5,"All the houses now have electricity.","Endi barcha uylar elektr tokiga ega."],["Flooded","suv toshgan, suv bosgan",5,"The entire farm is flooded with water.","Butun fermani suv bosgan."],["Hope","umid",5,"Don't lose hope","we'll find her. – Umidingizni yo'qotmang–biz uni topamiz."],["Hopeful","umidvor",5,"They are hopeful that the floods won't get worse.","Ular toshqinlar yomonlashmasligiga umidvor."],["Hopefully","umid qilamizki, Xudo xohlasa, Inshaallah",5,"Hopefully, the fire will go out on its own.","Umid qilamizki, olov o'zi o'chadi."],["Muddy","loyli, loy bosgan",5,"The fields were muddy from the rain.","Dalalar yomg'ir tufayli loy bosgandi."],["Please","mamnun qilmoq, xursand qilmoq",5,"You can't please everybody.","Hammani ham xursand qilolmaysiz."],["Pleasant","yoqimli, ajoyib",5,"We had a pleasant evening eating and singing.","Oqshomni ovqatlanib va qo'shiq kuylab ajoyib o'tkazdik."],["Unpleasant","yoqimsiz",5,"What an unpleasant man! He was so rude!","Naqadar yoqimsiz odam! Juda qo'pol ekan!"],["Pleasantly","yoqimli ravishda",5,"I was pleasantly surprised about how they look after the forest.","O'rmonga qanchalik g'amxo'rlik qilishlaridan yoqimli tarzda hayratlandim. (= Ularning o'rmonga qanday qarashlari meni hayratda qoldirdi.)"],["Unpleasantly","yoqimsiz ravishda",5,"The woman spoke to us very unpleasantly, saying we were not welcome there.","Ayol u yerda bizni xush ko'rmasliklarini aytib, bizga juda yoqimsiz ravishda gapirdi."],["Pollute","ifloslantirmoq",5,"Pesticides can kill wildlife and pollute the atmosphere.","Pestitsidlar (= ekin maydonlarida qo'llaniladigan qurt-qumursqalarga qarshi kimyoviy moddalar) yovvoyi tabiatni o'ldirishi va atmosferani ifloslantirishi mumkin."],["Polluted","ifloslangan",5,"The air is very polluted and makes you cough.","Havo juda ifloslangan va u odamni yo'taltiradi."],["Silently","jimjit tarzda, shovqin chiqarmay",5,"I walked as silently as I could so as not to scare the animals.","Men hayvonlarni qo'rqitib yubormaslik uchun qo'limdan kelgancha shovqin chiqarmay yurdim."],["Simply","oddiygina, shunchaki, xolos",5,"The people here live simply from farming.","Bu yerdagi odamlar oddiygina dehqonchilik bilan kun kechiradilar."],["Wood","yog'och, o'tin, taxta",5,"He chopped some wood for the fire.","U olov uchun biroz o'tin chopdi."]]},{"n":42,"t":"Global Problems","c":[["Army","armiya",0,"The army are helping villages damaged in the fire.","Armiya yong'inda zarar ko'rgan qishloqlarga yordam bermoqda."],["Bomb","bomba",0,"Luckily, the police found the bomb.","Yaxshiyamki, politsiya bombani topdi."],["Campaign","bir qator rejali harakatlar: odatda biror ijtimoiy, tijoriy yoki siyosiy maqsadni ko'zlab uyushtiriladigan reja-dasturlar",0,"The charity started a campaign to end famine.","Xayriya tashkiloti ocharchilikka barham berish maqsadida bir qator rejali harakatlarni boshladi."],["Charity","xayriya (tashkiloti)",0,"We always donate to charity at Christmas.","Biz har doim Rojdestvo bayramida xayriya tashkilotiga xayr-ehson qilamiz."],["Conditions","holat, ahvol, vaziyat va shart-sharoitlar",0,"Conditions in the town are getting better.","Shahardagi shart-sharoitlar yaxshilanib bormoqda."],["Disease","kasallik, xastalik (asosan ichki organlar bilan bog'liq kasalliklar)",0,"He caught the disease and was very ill, but he's better now.","U xastalikka chalindi va juda betob edi, biroq hozir yaxshiroq bo'lib qolgan."],["Famine","ocharchilik",0,"The charity brought food to the area where the famine was.","Xayriya tashkiloti ocharchilik mavjud bo'lgan hududga oziq-ovqat olib keldi."],["Fear","qo'rquv",0,"My greatest fear is getting lost in the mountains.","Mening eng katta qo'rquvim tog'larda adashib qolishdir."],["Government","hukumat, hokimiyat",0,"The government says it will build the villages again.","Hukumatning aytishicha, u qishloqlarni qayta qurar ekan."],["Hope","umid",0,"Our hope is that the government will help.","Umidimiz hukumat yordam berishidan."],["Immigrant","immigrant, muhojir",0,"The immigrants left their home country to find a better life.","Muhojirlar yaxshiroq hayot topish maqsadida ona vatanlarini tark etishgan."],["Pain","og'riq",0,"Cream made the pain from the burn a little less.","Krem kuyishdan qolgan og'riqni biroz kamaytirdi."],["Panic","sarosima, vahima",0,"In the panic, some children lost their parents.","Sarosimada, ba'zi bolalar ota-onalarini yo'qotib qo'yishdi."],["Peace","tinchlik",0,"After years of war, there is peace in the country.","Yillab davom etgan urushdan keyin, mamlakatda tinchlik hukm surmoqda."],["Poverty","nochorlik, kambag'allik, qashshoqlik",0,"There's a lot of poverty in this area–they have nothing.","Ushbu hududda qashshoqlik juda ko'p– ularning hech vaqosi yo'q."],["Race","irq",0,"It was the first time he'd seen someone not of his race.","U o'z irqiga mansub bo'lmagan odamni birinchi marta ko'rib turgandi."],["Racism","irqchilik",0,"Racism is terrible–everyone is the same underneath.","Irqchilik daxshatli narsa–hamma ham ich- ichidan bir xil."],["Safety","xavfsizlik, xavfsiz joy-hudud",0,"The army moved evryone to a place of safety.","Armiya barchani xavfsiz joyga ko'chirdi."],["Soldier","askar",0,"The army sent in hundreds of soldiers to help.","Armiya yordam berish uchun yuzlab askarlarni jalb qildi."],["Solution","yechim",0,"We have to find a solution to the problem–fast!","Muammoga yechim topishimiz lozim–tezlik bilan!"],["Terrorism","terrorchilik",0,"The government works hard to fight terrorism.","Hukumat terrorchilikka qarshi kurashish uchun qattiq harakat qiladi."],["Terrorist","terrorchi",0,"The police caught the terrorists before they could act.","Terrorchilar harakat qila olishidan avval, politsiya ularni qo'lga oldi."],["War","urush",0,"The war is finally over and we have peace.","Urush va nihoyat tugadi va bizda tinchlik (hukm surmoqda)."],["Beg","sadaqa so'ramoq, yolvorib so'ramoq",1,"I gave some money to an old man begging in the street.","Ko'chada sadaqa so'rayotgan bir qariyaga ozgina pul berdim."],["Burn","kuymoq, kuydirmoq",1,"I touched the hot oven and burned my finger.","Men qaynoq pechga tegindim va barmog'imni kuydirib oldim."],["Cure","tuzatmoq, davolamoq",1,"They may have found a medicine that cures the cold.","Shamollashni davolaydigan dori topgan bo'lishlari mumkin."],["Donate","xayr-ehson qilmoq",1,"How much money do you donate to charity?","Xayriyaga qancha pul xayr-ehson qilasiz?"],["Escape","qochmoq",1,"Everyone managed to escape the fire.","Hamma yong'indan qochib qola oldi."],["Fear","qo'rqmoq",1,"We feared for their lives, but they were all right.","Biz ularni hayotidan qo'rqdik, lekin ular sog'- salomat ekan."],["Guard","qo'riqlamoq",1,"There were ten men guarding the bank.","Bankni o'n nafar odam qo'riqlayotgandi."],["Hurt","shikastlamoq, jarohatlamoq",1,"The fire destroyed houses but luckily no one was hurt.","Yong'in uylarni vayron qildi, ammo yaxshiyamki hech kim shikastlanmadi."],["Panic","sarosimaga tushmoq",1,"Don't panic! Leave the building calmly.","Sarosimaga tushmang! Binoni tinchlik bilan tark eting."],["Punish","jazolamoq",1,"The teacher punished the boys by making them clean the desks.","O'qituvchi bolalarga partalarni tozalatish orqali ularni jazoladi."],["Save","saqlab qolmoq, asrab qolmoq, qutqarmoq",1,"We saved the girl from the water.","Biz qizaloqni suvdan qutqarib qoldik."],["Solve","hal qilmoq, muammoni yechmoq",1,"I solved our problem–you can thank me later.","Men muammoyimizni hal qildim–keyinroq tashakkur bildirsangiz bo'ladi."],["Fall down","qulamoq; yiqilib tushmoq",2,"Many buildings fell down in the earthquake.","Ko'plab binolar zilzila davomida qulab tushdi."],["Get ou t","tashqariga chiqmoq",2,"\"Get out of the house!\" shouted the policeman.","\"Uydan tashqariga chiqing!\" deb baqirdi politsiyachi."],["Go down","pastga tushmoq",2,"We went down the mountain to the river.","Biz tog' bo'ylab daryo tomon pastga tushdik."],["Go off","portlamoq; (quroldan) o'q uzmoq, otmoq",2,"Luckily, there was no one in the building when the bomb went off.","Yaxshiyamki, bomba portlaganda, binoda hech kim yo'q edi."],["Go up","yuqoriga chiqmoq",2,"Let's go up to the top floor of the house.","Keling uyning eng yuqori qavatiga chiqamiz."],["Run away (from someone/something)","(biror kim/narsa) dan qochmoq",2,"Animals running away from the fire came through the village.","Yong'indan qochayotgan hayvonlar qishloq oralab o'tishdi."],["Be on fire","o't ostida bo'lmoq, yonayotgan bo'lmoq",3,"The forest is on fire–I can see the flames.","O'rmon o't ostida–alangalarni ko'ryapman."],["Care about (someone/something)","(biror kim/narsa) haqida qayg'urmoq",3,"We care about these people, so we want to help them.","Biz bu odamlar haqida qayg'uramiz, shuning uchun ularga yordam berishni xohlaymiz."],["Depend on (someone/something)","(biror kim/narsa) ga suyanmoq, tayanmoq, ishonmoq",3,"These people are depending on us to help them.","Bu odamlar bizning yordam berishimizga suyanishmoqda."],["Escape from (someone/something)","(biror kim/narsa) dan qochmoq",3,"The animals crossed the river to escape from the fire.","Hayvonlar yong'indan qochish uchun daryoni kesib o'tishdi."],["Forgive for (doing something)","(biror narsa qilgani) uchun kechirmoq",3,"Forgive me for scaring you–I didn't mean to.","Sizni qo'rqitib yuborganim uchun meni kechiring– bunday qilishni xohlamagandim."],["Frightened by someone/of something","biror kimdan/biror narsadan qo'rqqan",3,"Children are often frightened of the darkness.","Bolalar odatda qorong'ulikdan qo'rqadilar."],["Get better/worse","yaxshilanmoq/yomonlashmoq",3,"Things are getting better for the area where the famine was.","Ocharchilik bo'lib o'tgan hududda ahvol yaxshilanmoqda."],["Give (money) to charity","xayriyaga (pul) bermoq, xayr-ehson qilmoq",3,"The school children raised £500 to give to charity.","Maktab o'quvchilari xayriyaga berish uchun 500 funt sterling yig'ishdi."],["Make a plan","reja tuzmoq",3,"The army made a plan to save the trapped villagers.","Armiya tuzoqqa tushib qolgan qishloq aholisini qutqarish uchun reja tuzdi."],["Tell a lie/the truth","yolg'on/haqiqatni gapirmoq",3,"The newspapers should tell people the truth about the famine.","Gazetalar odamlarga ocharchilik to'g'risidagi haqiqatni aytishi kerak."],["Homeless","uysiz, boshpanasiz",4,"The charity helps homeless people to get off the streets.","Xayriya tashkiloti boshpanasiz odamlarga ko'chadan ketishga yordam beradi."],["Illiterate","o'qish va yozishni bilmaydigan, savodsiz",4,"He teaches illiterate adults to read and write.","U katta yoshli savodsiz odamlarga o'qish va yozishni o'rgatadi."],["Overcrowded","gavjum, haddan tashqari ko'p odam bor bo'lgan",4,"The tent was overcrowded, with three families sleeping in it.","Chodirda haddan tashqari ko'p odam bor edi, ichida uchta oila uxlab yotgandi."],["Poor","kambag'al, nochor, qashshoq",4,"The people here are very poor and often hungry.","Bu yerdagi odamlar juda kambag'al va odatda och."],["Rich","boy, badavlat",4,"Rich people should give money to charity.","Boy odamlar xayriyaga pul berishlari kerak."],["Safe","xavfsiz",4,"You're safe now–the danger has passed.","Endi xavfsizsiz–xavf o'tib ketdi."],["Terrible","rasvo, yomon, daxshatli",4,"We had a terrible year, but the next one will be better.","Bu yil rasvo yil bo'ldi, lekin keyingisi yaxshiroq bo'ladi."],["Everywhere","hamma yerda",4,"There's water everywhere–what happened?","Hamma yer suv bo'lib yotibdi–nima ro'y berdi?"],["Immediately","darhol, hoziroq",4,"We need the police to come here immediately.","Politsiya darhol bu yerga kelishi kerak."],["Maybe","balkim, bo'lishi mumkin, ehtimoli bor",4,"Maybe I helped, but I'm not sure.","Balkim yordam bergandirman, lekin ishonchim komil emas. (= Yordam bergan bo'lishim mumkin, lekin aniq bilmayman.)"],["Perhaps","balkim, bo'lishi mumkin, ehtimoli bor",4,"Perhaps I'll come back one day, but I don't know.","Balkim bir kun kelib qaytib kelarman, lekin bilmayman."],["Soon","tez orada, yaqin kunlarda",4,"Soon the rains will come and end the dry spell.","Tez orada yomg'irlar keladi va qisqa vaqtga cho'zilgan qurg'oqchilik mavsumini o'z nihoyasiga yetkazadi."],["Advise","maslahat bermoq",5,"I advise you to come here in spring–it's the best season.","Bu yerga bahorda kelishingizni maslahat beraman–u eng yaxshi fasl."],["Advice","maslahat",5,"Let me give you a piece of advice.","Sizga bir maslahat berishimga ijozat bering."],["Angry","jahli chiqqan",5,"Please don't be angry with me. It wasn't my fault.","Iltimos, mendan jahlingiz chiqmasin. Bu mening aybim emas edi."],["Anger","jahl",5,"His face went red with anger.","Uning yuzi jahldan qizarib ketdi."],["Angrily","jahl bilan",5,"She shouted angrily that the people there needed help.","U yerdagi odamlar yordamga muhtojligini jahl bilan baqirib aytdi u."],["Care","qayg'urmoq",5,"She cares deeply about environmental issues.","U atrof-muhit muammolari haqida chuqur qayg'uradi."],["Care","parvarish, qarash, ehtiyot qilish; yordam",5,"Some people were badly injured and needed medical care.","Ba'zi odamlar og'ir jarohatlangandi va tibbiy yordamga muhtoj edi."],["Careful","ehtiyotkor, e'tiborli",5,"Be careful–the buildings are ready to fall down.","Ehtiyotkor bo'ling–binolar qulay deb turibdi."],["Careless","ehtiyotsiz, be'etibor",5,"Some careless smoker started the fire.","Qandaydir ehtiyotsiz sigaret chekuvchi odam yong'inni boshlagan."],["Carefully","ehtiyotkorlik bilan",5,"We walked carefully across the old bridge.","Biz eski ko'prik bo'ylab ehtiyotkorlik bilan yurib o'tdik."],["Carelessly","ehtiyotsizlik bilan",5,"If you act carelessly, you will get hurt.","Agar ehtiyotsizlik bilan harakat qilsangiz, shikastlanasiz."],["Die","o'lmoq, halok bo'lmoq, vafot etmoq",5,"My father died suddenly at the age of 48.","Mening otam 48 yoshida kutilmaganda vafot etgan."],["Death","o'lim",5,"Some people were hurt, but there were no deaths.","Ba'zi odamlar shikastlangandi, biroq hech qanday o'limlar bo'lmagan."],["Dead","o'lik",5,"The police don't know whether he's alive or dead.","Politsiya uning tirik yoki o'lik ekanligini bilmaydi."],["Harm","ziyon yetkazmoq, zarar keltirmoq",5,"Pollution can harm marine life.","Ifloslanish dengiz hayotiga ziyon yetkazishi mumkin."],["Harm","ziyon, zarar",5,"Hard work never did anyone any harm.","Qattiq mehnat hech qachon hech kimga zarar keltirmagan."],["Harmful","ziyonli, zararli",5,"The snake is not harmful to people.","Bu ilon odamlarga zararli emas."],["Harmless","beziyon, bezarar",5,"Don't be scared of the spider–it's harmless.","O'rgimchakdan qo'rqmang–u bezarar."],["Health","sog'liq",5,"Regular exercise is good for your health.","Muntazam jismoniy mashqlar sog'lig'ingiz uchun yaxshi."],["Healthy","sog'lom",5,"The people are poor but healthy.","Odamlar qashshoq, lekin sog'lom."],["Healthily","sog'lom tarzda",5,"They live very healthily, working hard on their farms.","Ular tomorqalarida qattiq ishlab, sog'lom tarzda hayot kechiradilar."],["Hungry","och",5,"By dinner time we all felt really hungry.","Kechki ovqat paytigacha, biz barchamiz o'zimizni juda ochiqqan his qildik."],["Hunger","ochlik",5,"You could see the hunger on the children's faces.","Bolalarning yuzlarida ochlik ko'rinib turardi."],["Hungrily","ochlik bilan, ochiqib",5,"The children ate the food hungrily.","Bolalar ovqatni ochiqib yeyishdi."],["Ill","kasal, betob, xasta",5,"We both started to feel ill shortly after the meal.","Ovqatdan biroz o'tib, biz ikkovimiz ham o'zimizni kasal his qila boshladik."],["Illness","kasallik, betoblik, xastalik (asosan ruhiyatga ta'sir o'tkazadigan kasalliklar)",5,"The doctor gave him some medicine for the illness.","Shifokor unga kasallikka qarshi ozroq dori berdi."],["Lose","yo'qotmoq, ayrilmoq, judo bo'lmoq",5,"She lost a leg in a car crash.","U avariyada bir oyog'idan ayrilgan."],["Loss","judolik, ayrilish, yo'qotish",5,"The loss of their homes didn't stop the people smiling.","Uylaridan judo bo'lish odamlarni tabassum qilishdan to'xtatmadi."],["Lost","yo'qolib qolgan",5,"The boy was lost in the forest for days, but lived.","Bolakay kunlab vaqt davomida o'rmonda yo'qolib qolgandi, lekin yashab qolgan."],["Medicine","dori; tibbiyot",5,"Did you take your medicine?","Doringizni ichdingizmi?"],["Medical","tibbiy",5,"That man needs medical care immediately.","Bu kishiga zudlik bilan tibbiy yordam kerak."],["Save","saqlab qolmoq, qutqarmoq",5,"If you really want to save the planet, sell your car.","Agar siz haqiqatdan ham sayyorani qutqarishni xohlasangiz, mashinangizni sotib yuboring."],["Safety","xavfsizlik; xavfsiz joy-hudud",5,"The monkey went back into the safety of the forest.","Maymun xavfsiz o'rmonga qaytib kirib ketdi."],["Safely","sog'-omon, beshikast",5,"The girl came safely back just before night.","Qizaloq tun bo'lishidan shundoqqina avval sog'- omon qaytib keldi."],["Science","ilm-fan",5,"We need to invest more in science and technology.","Biz ilm-fan va texnologiyaga ko'proq investitsiya kiritishimiz zarur."],["Scientist","olim",5,"Scientists are trying to find a way to fight the illness.","Olimlar kasallikka qarshi kurashish yo'lini topishga harakat qilishmoqda."],["Scientific","ilmiy",5,"A scientific study found the people were surprisingly healthy.","Bir ilmiy tadqiqot shuni ko'rsatdiki, u odamlar hayratlanarli darajada sog'lom ekan."],["Society","jamiyat",5,"We must also consider the needs of the older members of society.","Biz jamiyatning keksa a'zolarining ham ehtiyojlarini e'tiborga olishimiz kerak."],["Social","ijtimoiy",5,"Their social system keeps those poor people alive because they all help one another.","Ularning ijtimoiy tizimi ushbu qashshoq odamlarni omon saqlaydi chunki ularning bari bir-biriga yordam beradi."],["Survive","omon qolmoq",5,"Nobody can survive long without water.","Hech kim suvsiz uzoq omon qola olmaydi."],["Survivor","omon qolgan odam",5,"The army found a survivor under the fallen tree.","Armiya qulagan daraxt tagida bir omon qolgan odamni topdi."],["Survival","omon qolish",5,"The survival of the village after the fire depends on the government.","Yong'indan keyin qishloqning omon qolishi hukumatga bog'liq."]]}]};
